-- ===== collaboration-watch.sql (sha256 49f4e7840a6bf5c5) =====
-- Deployment candidate, not applied. Shared project-room identity for collaboration
-- and synchronized viewing. No drafts, media binaries or user communications.
begin;
create schema if not exists sdi_private;
revoke all on schema sdi_private from public;
grant usage on schema sdi_private to authenticated;
create table public.sdi_rooms (
 id uuid primary key default gen_random_uuid(),
 owner_id uuid not null references auth.users(id) on delete cascade,
 title text not null check (length(trim(title)) between 1 and 100),
 closed boolean not null default false,
 created_at timestamptz not null default now()
);
create table public.sdi_room_members (
 room_id uuid not null references public.sdi_rooms(id) on delete cascade,
 user_id uuid not null references auth.users(id) on delete cascade,
 owner_approved boolean not null default false,
 member_accepted boolean not null default false,
 revoked boolean not null default false,
 primary key(room_id,user_id)
);
-- Private lookup avoids recursive membership RLS. Never accepts an arbitrary
-- subject; every read is evaluated against the current JWT identity.
create function sdi_private.room_access(r uuid) returns boolean
language sql stable security definer set search_path='' as $$
 select auth.uid() is not null and exists (
  select 1 from public.sdi_rooms room where room.id=r and not room.closed
  and (room.owner_id=auth.uid() or exists (
   select 1 from public.sdi_room_members m where m.room_id=r and m.user_id=auth.uid()
   and m.owner_approved and m.member_accepted and not m.revoked)))
$$;
create function sdi_private.room_owner(r uuid) returns boolean
language sql stable security definer set search_path='' as $$
 select auth.uid() is not null and exists (
  select 1 from public.sdi_rooms where id=r and owner_id=auth.uid() and not closed)
$$;
revoke all on function sdi_private.room_access(uuid), sdi_private.room_owner(uuid) from public;
grant execute on function sdi_private.room_access(uuid), sdi_private.room_owner(uuid) to authenticated;
alter table public.sdi_rooms enable row level security;
alter table public.sdi_room_members enable row level security;
create policy room_read on public.sdi_rooms for select to authenticated using (sdi_private.room_access(id));
create policy room_create on public.sdi_rooms for insert to authenticated with check (owner_id=auth.uid());
create policy room_update on public.sdi_rooms for update to authenticated using (owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy member_read on public.sdi_room_members for select to authenticated using (user_id=auth.uid() or sdi_private.room_owner(room_id));
-- Membership creation/consent uses narrowly validated service operations. No
-- direct client mutation can self-approve, forge consent, or undo revocation.
revoke all on public.sdi_rooms, public.sdi_room_members from public, anon, authenticated;
grant select,insert on public.sdi_rooms to authenticated;
grant update(title,closed) on public.sdi_rooms to authenticated;
grant select on public.sdi_room_members to authenticated;

-- Only the publication service inserts approved, rights-cleared public renditions.
-- Private media needs a separately authorized short-lived delivery service.
create table public.sdi_watch_media (
 id uuid primary key default gen_random_uuid(),
 title text not null check(length(title) between 1 and 200),
 url text not null check(url ~ '^https://'),
 duration double precision not null check(duration > 0 and duration <= 3600),
 approved boolean not null default false,
 expires_at timestamptz
);
alter table public.sdi_watch_media enable row level security;
create policy media_read on public.sdi_watch_media for select to authenticated using (approved and (expires_at is null or expires_at>now()));
revoke all on public.sdi_watch_media from public, anon, authenticated;
grant select on public.sdi_watch_media to authenticated;
create table public.sdi_watch_sessions (
 id uuid primary key default gen_random_uuid(),
 room_id uuid not null unique references public.sdi_rooms(id) on delete cascade,
 media_id uuid not null references public.sdi_watch_media(id),
 position double precision not null default 0 check(position >= 0 and position <= 3600),
 playing boolean not null default false,
 revision bigint not null default 0,
 updated_at timestamptz not null default clock_timestamp()
);
alter table public.sdi_watch_sessions enable row level security;
create policy watch_read on public.sdi_watch_sessions for select to authenticated using(sdi_private.room_access(room_id));
create policy watch_create on public.sdi_watch_sessions for insert to authenticated with check(sdi_private.room_owner(room_id) and exists(select 1 from public.sdi_watch_media where id=media_id));
create policy watch_update on public.sdi_watch_sessions for update to authenticated using(sdi_private.room_owner(room_id)) with check(sdi_private.room_owner(room_id) and exists(select 1 from public.sdi_watch_media where id=media_id));
create function sdi_private.watch_stamp() returns trigger language plpgsql set search_path='' as $$
begin
 if TG_OP='UPDATE' then new.revision=old.revision+1;
 else new.revision=0; end if;
 new.updated_at=clock_timestamp();
 return new;
end $$;
revoke all on function sdi_private.watch_stamp() from public;
create trigger watch_stamp before insert or update on public.sdi_watch_sessions for each row execute function sdi_private.watch_stamp();
revoke all on public.sdi_watch_sessions from public, anon, authenticated;
grant select,insert on public.sdi_watch_sessions to authenticated;
grant update(position,playing,media_id) on public.sdi_watch_sessions to authenticated;
commit;

-- ===== room-invitations.sql (sha256 ec1905700dfb4ac5) =====
-- Unapplied candidate. Requires collaboration-watch.sql and pgcrypto in extensions.
begin;
create table sdi_private.room_invites (
 id uuid primary key default gen_random_uuid(), room_id uuid not null references public.sdi_rooms(id) on delete cascade,
 token_hash bytea not null unique, expires_at timestamptz not null,
 remaining integer not null check(remaining between 0 and 20), revoked boolean not null default false
);
create table sdi_private.room_request_budget (
 user_id uuid primary key references auth.users(id) on delete cascade,
 window_start timestamptz not null, attempts integer not null
);
create table sdi_private.room_blocks (
 room_id uuid not null references public.sdi_rooms(id) on delete cascade,
 user_id uuid not null references auth.users(id) on delete cascade,
 primary key(room_id,user_id)
);
alter table public.sdi_room_members add column request_expires_at timestamptz;
alter table sdi_private.room_invites enable row level security;
alter table sdi_private.room_request_budget enable row level security;
alter table sdi_private.room_blocks enable row level security;
revoke all on sdi_private.room_invites,sdi_private.room_request_budget,sdi_private.room_blocks from public,anon,authenticated;
-- One bounded operation boundary. Token inputs must be redacted by gateway logs.
create function sdi_private.room_action(action text, room uuid default null, subject uuid default null,
 code text default null, title text default null, consent boolean default false) returns jsonb
language plpgsql security definer set search_path='' as $$
declare
 actor uuid := auth.uid(); invitation sdi_private.room_invites; secret text;
 target public.sdi_rooms; count_attempts integer; created uuid;
begin
 if actor is null or not sdi_private.account_active() or not exists(select 1 from auth.users where id=actor and not is_anonymous)
 then return jsonb_build_object('error','Sign in with a full account.'); end if;
 insert into sdi_private.room_request_budget values(actor,clock_timestamp(),1)
 on conflict(user_id) do update set
 attempts=case when sdi_private.room_request_budget.window_start < clock_timestamp()-interval '1 minute' then 1 else sdi_private.room_request_budget.attempts+1 end,
 window_start=case when sdi_private.room_request_budget.window_start < clock_timestamp()-interval '1 minute' then clock_timestamp() else sdi_private.room_request_budget.window_start end
 returning attempts into count_attempts;
 -- Return errors rather than raising so attempted operations remain rate counted.
 if count_attempts>30 then return jsonb_build_object('error','Too many requests. Wait a minute.'); end if;
 if action='create' then
  if title is null or length(trim(title)) not between 1 and 100 or not consent then
   return jsonb_build_object('error','A room name and explicit consent are required.'); end if;
  if (select count(*) from public.sdi_rooms where owner_id=actor and not closed)>=20 then
   return jsonb_build_object('error','Close an existing room before creating another.'); end if;
  insert into public.sdi_rooms(owner_id,title) values(actor,trim(title)) returning id into created;
  return jsonb_build_object('room_id',created,'status','created');
 end if;
 if action in ('preview','request') then
  if code is null or length(code)<>64 then return jsonb_build_object('error','Invitation is unavailable.'); end if;
  select * into invitation from sdi_private.room_invites where token_hash=extensions.digest(code,'sha256') for update;
  if not found or invitation.revoked or invitation.remaining<=0 or invitation.expires_at<=clock_timestamp() then
   return jsonb_build_object('error','Invitation is unavailable.'); end if;
  select * into target from public.sdi_rooms where id=invitation.room_id and not closed for update;
  if not found or exists(select 1 from sdi_private.room_blocks where room_id=invitation.room_id and user_id=actor) then
   return jsonb_build_object('error','Invitation is unavailable.'); end if;
  if action='preview' then return jsonb_build_object('room_id',target.id,'title',target.title,'status','preview'); end if;
  if not consent then return jsonb_build_object('error','Accept the room invitation first.'); end if;
  if target.owner_id=actor then return jsonb_build_object('error','You already own this room.'); end if;
  if exists(select 1 from public.sdi_room_members where room_id=target.id and user_id=actor and not revoked) then
   return jsonb_build_object('status','already_requested','room_id',target.id); end if;
  if (select count(*) from public.sdi_room_members where room_id=target.id and not revoked)>=50 then
   return jsonb_build_object('error','This room has reached its member limit.'); end if;
  insert into public.sdi_room_members(room_id,user_id,member_accepted,owner_approved,revoked,request_expires_at)
  values(target.id,actor,true,false,false,invitation.expires_at)
  on conflict(room_id,user_id) do update set member_accepted=true,owner_approved=false,revoked=false,request_expires_at=excluded.request_expires_at;
  update sdi_private.room_invites set remaining=remaining-1 where id=invitation.id;
  return jsonb_build_object('status','pending_owner_approval','room_id',target.id);
 end if;
 select * into target from public.sdi_rooms where id=room and not closed for update;
 if not found then return jsonb_build_object('error','Room is unavailable.'); end if;
 if action='leave' and target.owner_id<>actor then
  update public.sdi_room_members set revoked=true,member_accepted=false,owner_approved=false where room_id=room and user_id=actor;
  return jsonb_build_object('status','left');
 end if;
 if target.owner_id<>actor then return jsonb_build_object('error','Only the owner can perform this operation.'); end if;
 if action='invite' then
  update public.sdi_room_members set revoked=true where room_id=room and not owner_approved;
  update sdi_private.room_invites set revoked=true where room_id=room;
  secret=encode(extensions.gen_random_bytes(32),'hex');
  insert into sdi_private.room_invites(room_id,token_hash,expires_at,remaining)
  values(room,extensions.digest(secret,'sha256'),clock_timestamp()+interval '24 hours',20);
  return jsonb_build_object('status','invitation_created','code',secret);
 elsif action='revoke_invites' then
  update sdi_private.room_invites set revoked=true where room_id=room;
  update public.sdi_room_members set revoked=true where room_id=room and not owner_approved;
 elsif action='approve' then
  update public.sdi_room_members set owner_approved=true where room_id=room and user_id=subject
  and member_accepted and not revoked and request_expires_at>clock_timestamp()
  and not exists(select 1 from sdi_private.room_blocks where room_id=room and user_id=subject);
  if not found then return jsonb_build_object('error','The pending request expired or is unavailable.'); end if;
 elsif action in ('remove','block') then
  update public.sdi_room_members set revoked=true,owner_approved=false where room_id=room and user_id=subject;
  if action='block' and subject is not null then insert into sdi_private.room_blocks values(room,subject) on conflict do nothing; end if;
 elsif action='close' then
  update public.sdi_rooms set closed=true where id=room;
  update sdi_private.room_invites set revoked=true where room_id=room;
 else return jsonb_build_object('error','Unsupported room operation.');
 end if;
 return jsonb_build_object('status','updated');
end $$;
revoke all on function sdi_private.room_action(text,uuid,uuid,text,text,boolean) from public;
grant execute on function sdi_private.room_action(text,uuid,uuid,text,text,boolean) to authenticated;
create function public.sdi_room_action(action text,room uuid default null,subject uuid default null,
 code text default null,title text default null,consent boolean default false) returns jsonb
language sql security invoker set search_path='' as $$
 select sdi_private.room_action(action,room,subject,code,title,consent)
$$;
revoke all on function public.sdi_room_action(text,uuid,uuid,text,text,boolean) from public,anon;
grant execute on function public.sdi_room_action(text,uuid,uuid,text,text,boolean) to authenticated;
-- Only the bounded operation permits room creation/closure; no bypass via REST.
revoke insert,update on public.sdi_rooms from authenticated;
revoke update(title,closed) on public.sdi_rooms from authenticated;
commit;

-- ===== war-room.sql (sha256 9ff11666a34e0020) =====
-- Unapplied implementation candidate; requires collaboration-watch.sql.
begin;
alter table public.sdi_watch_media add column owner_id uuid references auth.users(id) on delete cascade;
alter table public.sdi_watch_media add column render_digest text check(render_digest ~ '^[a-f0-9]{64}$');
create table sdi_private.war_matches (
 id uuid primary key default gen_random_uuid(), creator uuid not null references auth.users(id) on delete cascade,
 opponent uuid not null references auth.users(id) on delete cascade,
 left_media uuid not null references public.sdi_watch_media(id), right_media uuid references public.sdi_watch_media(id),
 left_digest text not null, right_digest text,
 status text not null default 'pending' check(status in ('pending','active','completed','withdrawn','removed')),
 starts_at timestamptz, ends_at timestamptz, created_at timestamptz not null default clock_timestamp(),
 check(creator<>opponent)
);
create table sdi_private.war_votes (
 match_id uuid not null references sdi_private.war_matches(id) on delete cascade,
 voter uuid not null references auth.users(id) on delete cascade,
 choice text not null check(choice in ('left','right')), primary key(match_id,voter)
);
create table sdi_private.war_results (
 match_id uuid primary key references sdi_private.war_matches(id),
 left_votes bigint not null check(left_votes>=0), right_votes bigint not null check(right_votes>=0),
 outcome text not null check(outcome in('left','right','tie')),
 left_digest text not null, right_digest text not null,
 finalized_at timestamptz not null default clock_timestamp()
);
alter table sdi_private.war_results enable row level security;
revoke all on sdi_private.war_results from public,anon,authenticated;
create table sdi_private.war_budget (
 user_id uuid primary key references auth.users(id) on delete cascade,
 starts_at timestamptz not null, attempts integer not null
);
create table sdi_private.war_blocks (
 blocker uuid not null references auth.users(id) on delete cascade,
 blocked uuid not null references auth.users(id) on delete cascade, primary key(blocker,blocked)
);
alter table sdi_private.war_matches enable row level security;
alter table sdi_private.war_votes enable row level security;
alter table sdi_private.war_budget enable row level security;
alter table sdi_private.war_blocks enable row level security;
revoke all on sdi_private.war_matches,sdi_private.war_votes,sdi_private.war_budget,sdi_private.war_blocks from public,anon,authenticated;
-- Every privileged path binds to auth.uid(). Client never supplies voter identity.
create function sdi_private.war_action(action text, match uuid default null, media uuid default null,
 opponent uuid default null, choice text default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare actor uuid:=auth.uid(); n integer; m sdi_private.war_matches; video public.sdi_watch_media; result jsonb;
begin
 if actor is null or not sdi_private.account_active() or not exists(select 1 from auth.users where id=actor and not is_anonymous) then
  return jsonb_build_object('error','Sign in with a full account.'); end if;
 insert into sdi_private.war_budget values(actor,clock_timestamp(),1)
 on conflict(user_id) do update set
 attempts=case when sdi_private.war_budget.starts_at<clock_timestamp()-interval '1 minute' then 1 else sdi_private.war_budget.attempts+1 end,
 starts_at=case when sdi_private.war_budget.starts_at<clock_timestamp()-interval '1 minute' then clock_timestamp() else sdi_private.war_budget.starts_at end
 returning attempts into n;
 if n>60 then return jsonb_build_object('error','Too many requests. Wait a minute.'); end if;
 if action='list' then
  select coalesce(jsonb_agg(row_to_json(items)),'[]'::jsonb) into result from (
   select w.id,w.creator,w.opponent,w.status,w.ends_at,l.title as left_title,l.url as left_url,
    r.title as right_title,r.url as right_url,final.outcome,
    coalesce(final.left_votes,(select count(*) from sdi_private.war_votes where match_id=w.id and war_votes.choice='left')) as left_votes,
    coalesce(final.right_votes,(select count(*) from sdi_private.war_votes where match_id=w.id and war_votes.choice='right')) as right_votes,
    (select war_votes.choice from sdi_private.war_votes where match_id=w.id and voter=actor) as my_vote
   from sdi_private.war_matches w join public.sdi_watch_media l on l.id=w.left_media
   left join public.sdi_watch_media r on r.id=w.right_media
   left join sdi_private.war_results final on final.match_id=w.id
   where (w.status in('active','completed') or (w.status='pending' and actor in(w.creator,w.opponent)))
   and l.approved and l.render_digest=w.left_digest and (l.expires_at is null or l.expires_at>clock_timestamp())
   and (w.status='pending' or (r.approved and r.render_digest=w.right_digest and (r.expires_at is null or r.expires_at>clock_timestamp())))
   and not exists(select 1 from sdi_private.war_blocks b where
     (b.blocker=actor and b.blocked in(w.creator,w.opponent)) or (b.blocked=actor and b.blocker in(w.creator,w.opponent)))
   order by w.created_at desc limit 100
  ) items;
  return jsonb_build_object('matches',result);
 elsif action='propose' then
  if opponent is null or opponent=actor or not exists(select 1 from auth.users where id=opponent and not is_anonymous) then
   return jsonb_build_object('error','Choose another eligible creator.'); end if;
  if exists(select 1 from sdi_private.war_blocks b where (b.blocker=actor and b.blocked=opponent) or (b.blocker=opponent and b.blocked=actor)) then
   return jsonb_build_object('error','Matchup unavailable.'); end if;
  if (select count(*) from sdi_private.war_matches where creator=actor and status in('pending','active') and (ends_at is null or ends_at>clock_timestamp()))>=5 then
   return jsonb_build_object('error','Finish or withdraw an existing matchup first.'); end if;
  select * into video from public.sdi_watch_media where id=media and owner_id=actor and approved and render_digest is not null
   and (expires_at is null or expires_at>clock_timestamp());
  if not found then return jsonb_build_object('error','Select your approved rendered video.'); end if;
  insert into sdi_private.war_matches(creator,opponent,left_media,left_digest) values(actor,opponent,media,video.render_digest);
 elsif action='block' then
  if opponent is null or opponent=actor then return jsonb_build_object('error','Invalid creator.'); end if;
  insert into sdi_private.war_blocks values(actor,opponent) on conflict do nothing;
  update sdi_private.war_matches set status='withdrawn' where status in('pending','active') and
   ((creator=actor and war_matches.opponent=war_action.opponent) or (creator=war_action.opponent and war_matches.opponent=actor));
 else
  select * into m from sdi_private.war_matches where id=match for update;
  if not found then return jsonb_build_object('error','Matchup unavailable.'); end if;
  if action='withdraw' then
   if actor not in(m.creator,m.opponent) then return jsonb_build_object('error','Only participants can withdraw.'); end if;
   if m.ends_at is not null and m.ends_at<=clock_timestamp() then return jsonb_build_object('error','Voting has ended; contact moderation for an appeal.'); end if;
   update sdi_private.war_matches set status='withdrawn' where id=match;
  elsif action='accept' then
   if m.opponent<>actor or m.status<>'pending' then return jsonb_build_object('error','No pending invitation.'); end if;
   if exists(select 1 from sdi_private.war_blocks b where (b.blocker=actor and b.blocked=m.creator) or (b.blocker=m.creator and b.blocked=actor)) then
    return jsonb_build_object('error','Matchup unavailable.'); end if;
   select * into video from public.sdi_watch_media where id=media and owner_id=actor and approved and render_digest is not null
    and (expires_at is null or expires_at>clock_timestamp()+interval '24 hours');
   if not found then return jsonb_build_object('error','Select an approved video available for the voting period.'); end if;
   if not exists(select 1 from public.sdi_watch_media where id=m.left_media and approved and render_digest=m.left_digest and (expires_at is null or expires_at>clock_timestamp()+interval '24 hours')) then
    return jsonb_build_object('error','The other video is unavailable.'); end if;
   update sdi_private.war_matches set right_media=media,right_digest=video.render_digest,status='active',starts_at=clock_timestamp(),ends_at=clock_timestamp()+interval '24 hours' where id=match;
  elsif action='vote' then
   if choice is null or choice not in('left','right') or actor in(m.creator,m.opponent) or m.status<>'active' or m.ends_at<=clock_timestamp() then
    return jsonb_build_object('error','Voting is not available to this account.'); end if;
   if exists(select 1 from sdi_private.war_blocks b where (b.blocker=actor and b.blocked in(m.creator,m.opponent)) or (b.blocked=actor and b.blocker in(m.creator,m.opponent))) then
    return jsonb_build_object('error','Voting is unavailable.'); end if;
   if (select count(*) from public.sdi_watch_media where approved and (expires_at is null or expires_at>clock_timestamp())
     and ((id=m.left_media and render_digest=m.left_digest) or (id=m.right_media and render_digest=m.right_digest)))<>2 then
    return jsonb_build_object('error','A submitted video is no longer approved.'); end if;
   insert into sdi_private.war_votes values(match,actor,choice) on conflict(match_id,voter) do update set choice=excluded.choice;
  else return jsonb_build_object('error','Unsupported operation.'); end if;
 end if;
 return jsonb_build_object('status','confirmed');
end $$;
revoke all on function sdi_private.war_action(text,uuid,uuid,uuid,text) from public;
grant execute on function sdi_private.war_action(text,uuid,uuid,uuid,text) to authenticated;
create function public.sdi_war_action(action text,match uuid default null,media uuid default null,opponent uuid default null,choice text default null) returns jsonb
language sql security invoker set search_path='' as $$select sdi_private.war_action(action,match,media,opponent,choice)$$;
revoke all on function public.sdi_war_action(text,uuid,uuid,uuid,text) from public,anon;
grant execute on function public.sdi_war_action(text,uuid,uuid,uuid,text) to authenticated;
commit;

