create table sdi_private.feed_budget (
 actor uuid primary key references auth.users(id) on delete cascade,
 started_at timestamptz not null, attempts integer not null
);
alter table sdi_private.feed_posts enable row level security;
alter table sdi_private.feed_likes enable row level security;
alter table sdi_private.feed_follows enable row level security;
alter table sdi_private.feed_blocks enable row level security;
alter table sdi_private.feed_reports enable row level security;
alter table sdi_private.feed_budget enable row level security;
revoke all on sdi_private.feed_posts,sdi_private.feed_likes,sdi_private.feed_follows,sdi_private.feed_blocks,sdi_private.feed_reports,sdi_private.feed_budget from public,anon,authenticated;
-- Publication service alone inserts approved posts. API returns only eligible video.
-- Paging is snapshot-stable (#217, #220): page 0 returns an `as_of` instant and
-- later pages sent with that instant exclude posts published after it, so new
-- publications shift nothing until the member refreshes. A snapshot older than a
-- day is refused. Trending's like-based rank is computed at request time and is
-- documented as refresh-based, not frozen.
create function sdi_private.feed_action(action text, post_id uuid default null, target uuid default null,
 enabled boolean default true, category text default 'recent', page integer default 0, reason text default null,
 as_of timestamptz default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare actor_id uuid:=auth.uid(); entry sdi_private.feed_posts; n integer; items jsonb; snapshot timestamptz;
begin
 if actor_id is null or not sdi_private.account_active() or not exists(select 1 from auth.users where id=actor_id and not is_anonymous) then
  return jsonb_build_object('error','Sign in with a full account.'); end if;
 insert into sdi_private.feed_budget values(actor_id,clock_timestamp(),1)
 on conflict(actor) do update set attempts=case when feed_budget.started_at<clock_timestamp()-interval '1 minute' then 1 else feed_budget.attempts+1 end,
 started_at=case when feed_budget.started_at<clock_timestamp()-interval '1 minute' then clock_timestamp() else feed_budget.started_at end returning attempts into n;
 if n>60 then return jsonb_build_object('error','Please wait before trying again.'); end if;
 if action='list' then
  if page<0 or page>39 or category not in('recent','following','featured','trending') then return jsonb_build_object('error','Invalid feed page.'); end if;
  snapshot:=least(coalesce(as_of,clock_timestamp()),clock_timestamp());
  if snapshot<clock_timestamp()-interval '1 day' then return jsonb_build_object('error','This feed snapshot has expired. Refresh the feed.'); end if;
  select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into items from (
   select p.id,p.creator,p.creator_name,p.caption,p.published_at,p.allow_export,m.title,m.url,
    (select count(*) from sdi_private.feed_likes l where l.post=p.id) as likes,
    exists(select 1 from sdi_private.feed_likes l where l.post=p.id and l.actor=actor_id) as liked,
    exists(select 1 from sdi_private.feed_follows f where f.actor=actor_id and f.creator=p.creator) as following
   from sdi_private.feed_posts p join public.sdi_watch_media m on m.id=p.media_id
   where p.visible and m.approved and m.owner_id=p.creator and m.render_digest is not null
   and p.published_at<=snapshot
   and (m.expires_at is null or m.expires_at>clock_timestamp())
   and not exists(select 1 from sdi_private.feed_blocks b where (b.actor=actor_id and b.creator=p.creator) or (b.actor=p.creator and b.creator=actor_id))
   and (category<>'featured' or p.featured)
   and (category<>'following' or exists(select 1 from sdi_private.feed_follows f where f.actor=actor_id and f.creator=p.creator))
   order by case when category='trending' then (select count(*) from sdi_private.feed_likes l where l.post=p.id and l.created_at>clock_timestamp()-interval '7 days') else 0 end desc,
    p.published_at desc,p.id desc limit 25 offset page*25
  ) item;
  return jsonb_build_object('posts',items,'has_more',jsonb_array_length(items)=25,'as_of',snapshot);
 end if;
 if action in('follow','block') then
  if target is null or target=actor_id or not exists(select 1 from auth.users where id=target) then return jsonb_build_object('error','Creator unavailable.'); end if;
  if action='block' then
   if enabled then
    insert into sdi_private.feed_blocks values(actor_id,target) on conflict do nothing;
    delete from sdi_private.feed_follows where (actor=actor_id and creator=target) or (actor=target and creator=actor_id);
   else delete from sdi_private.feed_blocks where actor=actor_id and creator=target; end if;
  else
   if exists(select 1 from sdi_private.feed_blocks where (actor=actor_id and creator=target) or (actor=target and creator=actor_id)) then return jsonb_build_object('error','Creator unavailable.'); end if;
   if enabled then insert into sdi_private.feed_follows values(actor_id,target) on conflict do nothing;
   else delete from sdi_private.feed_follows where actor=actor_id and creator=target; end if;
  end if;
 else
  select p.* into entry from sdi_private.feed_posts p join public.sdi_watch_media m on m.id=p.media_id
   where p.id=post_id and p.visible and m.approved and m.owner_id=p.creator and m.render_digest is not null
   and (m.expires_at is null or m.expires_at>clock_timestamp())
   and not exists(select 1 from sdi_private.feed_blocks b where (b.actor=actor_id and b.creator=p.creator) or (b.actor=p.creator and b.creator=actor_id));
  if not found then return jsonb_build_object('error','Post unavailable.'); end if;
  if action='like' then
   if enabled then insert into sdi_private.feed_likes(post,actor) values(post_id,actor_id) on conflict do nothing;
   else delete from sdi_private.feed_likes where post=post_id and actor=actor_id; end if;
  elsif action='report' and reason in('rights','abuse','unsafe','spam') then
   insert into sdi_private.feed_reports(post,actor,reason) values(post_id,actor_id,reason)
   on conflict(post,actor) do update set reason=excluded.reason;
  else return jsonb_build_object('error','Unsupported feed operation.'); end if;
 end if;
 return jsonb_build_object('status','confirmed');
end $$;
revoke all on function sdi_private.feed_action(text,uuid,uuid,boolean,text,integer,text,timestamptz) from public;
grant execute on function sdi_private.feed_action(text,uuid,uuid,boolean,text,integer,text,timestamptz) to authenticated;
create function public.sdi_feed_action(action text,post_id uuid default null,target uuid default null,
 enabled boolean default true,category text default 'recent',page integer default 0,reason text default null,
 as_of timestamptz default null) returns jsonb
language sql security invoker set search_path='' as $$select sdi_private.feed_action(action,post_id,target,enabled,category,page,reason,as_of)$$;
revoke all on function public.sdi_feed_action(text,uuid,uuid,boolean,text,integer,text,timestamptz) from public,anon;
grant execute on function public.sdi_feed_action(text,uuid,uuid,boolean,text,integer,text,timestamptz) to authenticated;
commit;

-- ===== admin-approval.sql (sha256 98485dfcaea66cc6) =====
-- Unapplied candidate. Provision role records through a protected owner operation,
-- never from a client-supplied password, profile, username or email.
begin;
create table sdi_private.admin_roles (
 user_id uuid primary key references auth.users(id) on delete cascade,
 enabled boolean not null default false, owner boolean not null default false, revision bigint not null default 1,
 permissions text[] not null default '{}' check(permissions <@ array['users','reviews','moderation','publishing','overview','finance'])
);
create table sdi_private.render_reviews (
 id uuid primary key default gen_random_uuid(), creator uuid not null references auth.users(id) on delete cascade,
 title text not null check(length(title) between 1 and 200), source_revision text not null,
 render_digest text not null check(render_digest ~ '^[a-f0-9]{64}$'),
 preview_url text not null check(preview_url ~ '^https://'), preview_expires_at timestamptz not null,
 consent_version text not null, rights_summary text not null, rights_cleared boolean not null default false,
 destinations text[] not null check(destinations <@ array['feed','youtube','social']),
 spatter_generated boolean not null default false,
 state text not null default 'pending' check(state in('pending','approved','rejected','changes')),
 version bigint not null default 1, created_at timestamptz not null default clock_timestamp()
);
create table sdi_private.render_decisions (
 id uuid primary key default gen_random_uuid(), review_id uuid not null references sdi_private.render_reviews(id),
 actor uuid not null references auth.users(id), owner_at_decision boolean not null,
 render_title text not null, source_revision text not null, rights_summary text not null,
 render_digest text not null, review_version bigint not null, consent_version text not null,
 destinations text[] not null, decision text not null, note text not null check(length(note)<=2000),
 created_at timestamptz not null default clock_timestamp()
);
alter table sdi_private.admin_roles enable row level security;
alter table sdi_private.render_reviews enable row level security;
alter table sdi_private.render_decisions enable row level security;
revoke all on sdi_private.admin_roles,sdi_private.render_reviews,sdi_private.render_decisions from public,anon,authenticated;
create function sdi_private.admin_authorized() returns boolean language sql stable security definer set search_path='' as $$
 select auth.uid() is not null and auth.jwt()->>'aal'='aal2'
 and exists(select 1 from sdi_private.admin_roles where user_id=auth.uid() and enabled)
 and exists(select 1 from auth.sessions s where s.user_id=auth.uid() and s.id::text=auth.jwt()->>'session_id')
$$;
revoke all on function sdi_private.admin_authorized() from public;
grant execute on function sdi_private.admin_authorized() to authenticated;
create function sdi_private.admin_can(capability text) returns boolean language sql stable security definer set search_path='' as $$
 select sdi_private.admin_authorized() and capability=any(array['users','reviews','moderation','publishing','overview','finance'])
 and exists(select 1 from sdi_private.admin_roles where user_id=auth.uid() and enabled
  and (owner or capability=any(permissions)))
$$;
revoke all on function sdi_private.admin_can(text) from public,anon;
grant execute on function sdi_private.admin_can(text) to authenticated;
-- Service-side revisions invalidate approval. A preview URL renewal does not
-- change the render, but also cannot alter consent/destination evidence silently.
create function sdi_private.invalidate_render_approval() returns trigger language plpgsql set search_path='' as $$
begin
 if row(new.render_digest,new.source_revision,new.consent_version,new.rights_cleared,new.destinations,new.spatter_generated,new.creator,new.rights_summary)
 is distinct from row(old.render_digest,old.source_revision,old.consent_version,old.rights_cleared,old.destinations,old.spatter_generated,old.creator,old.rights_summary) then
  new.version=old.version+1; new.state='pending';
 end if;
 return new;
end $$;
revoke all on function sdi_private.invalidate_render_approval() from public;
create trigger invalidate_render_approval before update on sdi_private.render_reviews for each row execute function sdi_private.invalidate_render_approval();
create function sdi_private.review_action(action text,review uuid default null,digest text default null,
 version bigint default null,decision text default null,note text default '') returns jsonb
language plpgsql security definer set search_path='' as $$
declare r sdi_private.render_reviews; is_owner boolean; result jsonb;
begin
 if not sdi_private.admin_can('reviews') or not sdi_private.account_active() then return jsonb_build_object('error','Current video-review permission and MFA are required.'); end if;
 select owner into is_owner from sdi_private.admin_roles where user_id=auth.uid();
 if action='list' then
  select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into result from (
   select id,title,source_revision,render_digest,preview_url,preview_expires_at,consent_version,rights_summary,
    rights_cleared,destinations,spatter_generated,state,render_reviews.version
   from sdi_private.render_reviews where state='pending' order by created_at limit 50
  ) item;
  return jsonb_build_object('reviews',result,'owner',is_owner);
 end if;
 if action is null or action<>'decide' or review is null or digest is null or version is null or decision is null or note is null or decision not in('approved','rejected','changes') or length(note)>2000 then
  return jsonb_build_object('error','Invalid review decision.'); end if;
 select * into r from sdi_private.render_reviews where id=review for update;
 if not found or r.render_digest<>digest or r.version<>version or r.state<>'pending' then
  return jsonb_build_object('error','This render changed or was already reviewed. Reload the queue.'); end if;
 if decision='approved' and (not r.rights_cleared or length(r.consent_version)=0 or cardinality(r.destinations)=0
  or r.preview_expires_at<=clock_timestamp() or (r.spatter_generated and not is_owner)) then
  return jsonb_build_object('error','Approval requires current rights, consent, a playable render and owner approval for Spatter.'); end if;
 insert into sdi_private.render_decisions(review_id,actor,owner_at_decision,render_title,source_revision,rights_summary,render_digest,review_version,consent_version,destinations,decision,note)
 values(r.id,auth.uid(),is_owner,r.title,r.source_revision,r.rights_summary,r.render_digest,r.version,r.consent_version,r.destinations,decision,note);
 update sdi_private.render_reviews set state=decision where id=r.id;
 return jsonb_build_object('status','confirmed');
end $$;
revoke all on function sdi_private.review_action(text,uuid,text,bigint,text,text) from public;
grant execute on function sdi_private.review_action(text,uuid,text,bigint,text,text) to authenticated;
create function public.sdi_review_action(action text,review uuid default null,digest text default null,
 version bigint default null,decision text default null,note text default '') returns jsonb
language sql security invoker set search_path='' as $$select sdi_private.review_action(action,review,digest,version,decision,note)$$;
revoke all on function public.sdi_review_action(text,uuid,text,bigint,text,text) from public,anon;
grant execute on function public.sdi_review_action(text,uuid,text,bigint,text,text) to authenticated;
-- History returns snapshots from the decision, never mutable current render
-- metadata or an expired private preview link.
create function sdi_private.review_history(page integer default 0) returns jsonb
language plpgsql security definer set search_path='' as $$
declare result jsonb;
begin
 if not sdi_private.admin_can('reviews') or not sdi_private.account_active() then
  return jsonb_build_object('error','Current administrator MFA session required.');end if;
 if page is null or page not between 0 and 199 then return jsonb_build_object('error','Invalid history page.');end if;
 select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into result from (
  select id,review_id,actor,owner_at_decision,render_title,source_revision,rights_summary,
   render_digest,review_version,consent_version,destinations,decision,note,created_at
  from sdi_private.render_decisions order by created_at desc,id limit 50 offset page*50
 ) item;
 return jsonb_build_object('decisions',result);
end $$;
revoke all on function sdi_private.review_history(integer) from public,anon;
grant execute on function sdi_private.review_history(integer) to authenticated;
create function public.sdi_review_history(page integer default 0) returns jsonb
language sql security invoker set search_path='' as $$select sdi_private.review_history(page)$$;
revoke all on function public.sdi_review_history(integer) from public,anon;
grant execute on function public.sdi_review_history(integer) to authenticated;
commit;

-- ===== admin-users.sql (sha256 03d8663e934810c6) =====
-- Unapplied candidate. Requires admin-approval.sql and current feature candidates.
begin;
create table sdi_private.account_controls (
 user_id uuid primary key references auth.users(id) on delete cascade,
 state text not null check(state in('active','suspended','banned')),
 reason text not null, updated_at timestamptz not null default clock_timestamp()
);
create table sdi_private.admin_user_audit (
 id uuid primary key default gen_random_uuid(), actor uuid not null references auth.users(id),
 subject uuid not null, action text not null, reason text not null check(length(reason) between 1 and 2000),
 previous_state text, created_at timestamptz not null default clock_timestamp()
);
alter table sdi_private.account_controls enable row level security;
alter table sdi_private.admin_user_audit enable row level security;
create index admin_user_audit_subject_history on sdi_private.admin_user_audit(subject,created_at desc,id desc);
revoke all on sdi_private.account_controls,sdi_private.admin_user_audit from public,anon,authenticated;
create function sdi_private.account_active() returns boolean language sql stable security definer set search_path='' as $$
 select auth.uid() is not null and exists(select 1 from auth.users where id=auth.uid())
 and not exists(select 1 from sdi_private.account_controls where user_id=auth.uid() and state<>'active')
 and exists(select 1 from auth.sessions where user_id=auth.uid() and id::text=auth.jwt()->>'session_id')
$$;
revoke all on function sdi_private.account_active() from public;
grant execute on function sdi_private.account_active() to authenticated;
create function sdi_private.users_action(action text,subject uuid default null,query text default '',page integer default 0,reason text default '')
returns jsonb language plpgsql security definer set search_path='' as $$
declare result jsonb; before_state text; denial jsonb;
begin
 if not sdi_private.admin_can('users') or not sdi_private.account_active() then return jsonb_build_object('error','Administrator MFA authorization required.'); end if;
 -- Account-state changes need a recent second factor and are rate limited; every
 -- refusal is recorded (admin_gate in admin-hardening.sql, resolved at run time).
 if action in('suspend','ban','restore','signout','note') then
  denial:=sdi_private.admin_gate('users_action.'||action,'users',action<>'note',30);
  if denial is not null then return denial; end if;
 end if;
 if action='history' then
  if subject is null or page is null or page<0 or page>199 then return jsonb_build_object('error','Select an account and valid history page.'); end if;
  select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into result from (
   select a.id,a.actor,a.subject,a.action,a.reason,a.previous_state,a.created_at
   from sdi_private.admin_user_audit a where a.subject=users_action.subject
   order by a.created_at desc,a.id desc limit 50 offset page*50
  ) item;
  return jsonb_build_object('events',result,'has_more',exists(
   select 1 from sdi_private.admin_user_audit a where a.subject=users_action.subject
   order by a.created_at desc,a.id desc limit 1 offset (page+1)*50));
 end if;
 if action='list' then
  if page is null or page<0 or page>199 or query is null or length(query)>100 then return jsonb_build_object('error','Invalid directory query.'); end if;
  select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into result from (
   select u.id, coalesce(u.raw_user_meta_data->>'username','Member') as username,
    case when u.email is null then null else left(u.email,1)||'***@'||split_part(u.email,'@',2) end as masked_email,
    u.created_at,u.last_sign_in_at,coalesce(c.state,'active') as state,
    (select count(*) from sdi_private.feed_posts p where p.creator=u.id) as content_count,
    (select coalesce(jsonb_agg(method.provider order by method.provider),'[]'::jsonb)
     from (select distinct i.provider from auth.identities i where i.user_id=u.id) method) as sign_in_methods,
    case when sdi_private.admin_can('moderation') then
     (select count(*) from sdi_private.feed_reports r join sdi_private.feed_posts p on p.id=r.post where p.creator=u.id)
     else null end as feed_report_count,
    -- Plan is billing data: shown only with the finance capability (billing.sql
    -- installs later; entitlements come only from signed provider events).
    case when sdi_private.admin_can('finance') then
     coalesce((select e.tier from sdi_private.entitlements e where e.user_id=u.id
      order by case e.tier when 'pro' then 0 else 1 end,e.paid_through desc limit 1),'free')
     else null end as plan
   from auth.users u left join sdi_private.account_controls c on c.user_id=u.id
   where query='' or position(lower(query) in lower(coalesce(u.raw_user_meta_data->>'username','')))>0 or u.id::text=query
   order by u.created_at desc,u.id limit 50 offset page*50
  ) item;
  return jsonb_build_object('users',result,'has_more',jsonb_array_length(result)=50);
 end if;
 if subject is null or subject=auth.uid() or reason is null or length(trim(reason)) not between 1 and 2000 then
  return jsonb_build_object('error','Select another account and provide a reason.'); end if;
 if exists(select 1 from sdi_private.admin_roles where user_id=subject and enabled) then
  return jsonb_build_object('error','Administrator accounts require the separate owner recovery procedure.'); end if;
 perform 1 from auth.users where id=subject for update;
 if not found then return jsonb_build_object('error','Account unavailable.'); end if;
 select state into before_state from sdi_private.account_controls where user_id=subject;
 if action in('suspend','ban','restore') then
  insert into sdi_private.account_controls(user_id,state,reason) values(subject,
   case action when 'suspend' then 'suspended' when 'ban' then 'banned' else 'active' end,trim(reason))
  on conflict(user_id) do update set state=excluded.state,reason=excluded.reason,updated_at=clock_timestamp();
 elsif action not in('signout','note') then return jsonb_build_object('error','Unsupported account action.'); end if;
 if action in('suspend','ban','signout') then delete from auth.sessions where user_id=subject; end if;
 insert into sdi_private.admin_user_audit(actor,subject,action,reason,previous_state) values(auth.uid(),subject,action,trim(reason),coalesce(before_state,'active'));
 return jsonb_build_object('status','confirmed');
end $$;
revoke all on function sdi_private.users_action(text,uuid,text,integer,text) from public;
grant execute on function sdi_private.users_action(text,uuid,text,integer,text) to authenticated;
create function public.sdi_users_action(action text,subject uuid default null,query text default '',page integer default 0,reason text default '') returns jsonb
language sql security invoker set search_path='' as $$select sdi_private.users_action(action,subject,query,page,reason)$$;
revoke all on function public.sdi_users_action(text,uuid,text,integer,text) from public,anon;
grant execute on function public.sdi_users_action(text,uuid,text,integer,text) to authenticated;

-- Restrictive policies apply session/suspension checks alongside membership.
create policy active_account_rooms on public.sdi_rooms as restrictive for all to authenticated
 using(sdi_private.account_active()) with check(sdi_private.account_active());
create policy active_account_members on public.sdi_room_members as restrictive for all to authenticated
 using(sdi_private.account_active()) with check(sdi_private.account_active());
create policy active_account_watch on public.sdi_watch_sessions as restrictive for all to authenticated
 using(sdi_private.account_active()) with check(sdi_private.account_active());
create policy active_account_media on public.sdi_watch_media as restrictive for all to authenticated
 using(sdi_private.account_active()) with check(sdi_private.account_active());

-- A restricted member may authenticate afresh solely to read/appeal their own
-- restriction. This does not relax account_active() on any product endpoint.
create table sdi_private.account_appeals (
 id uuid primary key default gen_random_uuid(),
 subject uuid not null references auth.users(id) on delete cascade,
 restriction_at timestamptz not null,
 explanation text not null check(length(explanation) between 1 and 2000),
 state text not null default 'pending' check(state in('pending','accepted','rejected','superseded')),
 reply text check(length(reply)<=2000), reviewer uuid references auth.users(id),
 created_at timestamptz not null default clock_timestamp(), decided_at timestamptz,
 unique(subject,restriction_at)
);
alter table sdi_private.account_appeals enable row level security;
revoke all on sdi_private.account_appeals from public,anon,authenticated;
create index account_appeals_queue on sdi_private.account_appeals(state,created_at,id);
create function sdi_private.account_appeal_action(action text,appeal uuid default null,
 explanation text default '',reply text default '',restriction text default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare actor_id uuid:=auth.uid(); control sdi_private.account_controls;
 item sdi_private.account_appeals; target uuid; items jsonb; outcome jsonb;
begin
 if actor_id is null or not exists(select 1 from auth.users where id=actor_id and not is_anonymous)
 or not exists(select 1 from auth.sessions where user_id=actor_id and id::text=auth.jwt()->>'session_id') then
  return jsonb_build_object('error','A current signed-in account is required.');end if;
 if action in('mine','submit') then
  -- Use the same lock order as account actions: user, control, appeal.
  perform 1 from auth.users where id=actor_id for update;
  select * into control from sdi_private.account_controls where user_id=actor_id for update;
  if action='submit' then
   if control.user_id is null or control.state='active' then return jsonb_build_object('error','No current account restriction to appeal.');end if;
   if restriction is distinct from control.updated_at::text then return jsonb_build_object('error','Account restriction changed. Refresh before submitting.');end if;
   if explanation is null or length(trim(explanation)) not between 1 and 2000 then
    return jsonb_build_object('error','Explain your request in 1–2000 characters.');end if;
   if not exists(select 1 from sdi_private.account_appeals where subject=actor_id and restriction_at=control.updated_at) then
    if (select count(*) from sdi_private.account_appeals where subject=actor_id and created_at>clock_timestamp()-interval '1 day')>=3 then
     return jsonb_build_object('error','Daily appeal limit reached.');end if;
    insert into sdi_private.account_appeals(subject,restriction_at,explanation)
    values(actor_id,control.updated_at,trim(explanation));
   end if;
  end if;
  select coalesce(jsonb_agg(row_to_json(entry)),'[]'::jsonb) into items from (
   select id,explanation,state,reply,created_at,decided_at from sdi_private.account_appeals
   where subject=actor_id order by created_at desc,id desc limit 20
  ) entry;
  return jsonb_build_object('account_state',coalesce(control.state,'active'),'restriction',control.updated_at::text,'appeals',items,
   'can_appeal',coalesce(control.state<>'active',false) and not exists(
    select 1 from sdi_private.account_appeals where subject=actor_id and restriction_at=control.updated_at));
 end if;
 if not sdi_private.admin_can('users') or not sdi_private.account_active() then
  return jsonb_build_object('error','Current administrator MFA authorization required.');end if;
 if action='queue' then
  select coalesce(jsonb_agg(row_to_json(entry)),'[]'::jsonb) into items from (
   select a.id,a.subject,a.explanation,a.state,a.created_at,c.state as account_state
   from sdi_private.account_appeals a left join sdi_private.account_controls c on c.user_id=a.subject
   where a.state='pending' order by a.created_at,a.id limit 50
  ) entry;
  return jsonb_build_object('appeals',items);
 end if;
 if action is null or action not in('accept','reject') or appeal is null
 or reply is null or length(trim(reply)) not between 1 and 2000 then
  return jsonb_build_object('error','Select an appeal and provide a member-visible decision reason.');end if;
 select subject into target from sdi_private.account_appeals where id=appeal;
 if target is null or target=actor_id then return jsonb_build_object('error','Appeal unavailable for review.');end if;
 perform 1 from auth.users where id=target for update;
 select * into control from sdi_private.account_controls where user_id=target for update;
 select * into item from sdi_private.account_appeals where id=appeal for update;
 if item.state<>'pending' then return jsonb_build_object('error','This appeal was already decided. Refresh the queue.');end if;
 if control.user_id is null or control.state='active' or control.updated_at<>item.restriction_at then
  update sdi_private.account_appeals set state='superseded',reviewer=actor_id,decided_at=clock_timestamp(),
   reply='The account restriction changed. Check your current account status.' where id=appeal;
  return jsonb_build_object('status','superseded');end if;
 if action='accept' then
  outcome=sdi_private.users_action('restore',target,'',0,'Appeal '||appeal::text||': '||left(trim(reply),1900));
  if outcome->>'status' is distinct from 'confirmed' then return outcome;end if;
 else
  insert into sdi_private.admin_user_audit(actor,subject,action,reason,previous_state)
  values(actor_id,target,'appeal_rejected','Appeal '||appeal::text||': '||left(trim(reply),1900),control.state);
 end if;
 update sdi_private.account_appeals set state=case action when 'accept' then 'accepted' else 'rejected' end,
  reply=trim(reply),reviewer=actor_id,decided_at=clock_timestamp() where id=appeal;
 return jsonb_build_object('status','confirmed');
end $$;
