grant execute on function public.sdi_admin_overview() to authenticated;
commit;

-- ===== feed-integrity.sql (sha256 0713701e1fbfaccb) =====
-- Unapplied candidate. Install after admin-overview.sql (needs video-feed, moderation,
-- war-room, admin-users, publishing-jobs and upload-registration).
-- Closes feed/War Room integrity gaps: self-likes, restricted creators in listings,
-- report upserts reopening decided reports, proposals that never expire, and
-- 24-hour artifact expiry defeating review approval.
begin;
-- Restricted (suspended/banned) creators disappear from every listing and reaction.
create function sdi_private.creator_restricted(subject uuid) returns boolean
language sql stable security definer set search_path='' as $$
 select subject is null or exists(select 1 from sdi_private.account_controls c where c.user_id=subject and c.state<>'active')
$$;
revoke all on function sdi_private.creator_restricted(uuid) from public,anon;
grant execute on function sdi_private.creator_restricted(uuid) to authenticated,service_role;

-- A decided report keeps its decision; only a pending report can change reason.
create or replace function sdi_private.report_revision() returns trigger language plpgsql set search_path='' as $$
begin
 if old.state<>'pending' then new.reason=old.reason; new.state=old.state; new.version=old.version; return new; end if;
 if new.reason is distinct from old.reason then new.version=old.version+1; end if;
 return new;
end $$;

-- Same signature as video-feed.sql (snapshot-stable paging through `as_of`, #217/#220).
create or replace function sdi_private.feed_action(action text, post_id uuid default null, target uuid default null,
 enabled boolean default true, category text default 'recent', page integer default 0, reason text default null,
 as_of timestamptz default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare actor_id uuid:=auth.uid(); entry sdi_private.feed_posts; n integer; items jsonb; snapshot timestamptz;
begin
 if actor_id is null or not sdi_private.account_active() or not exists(select 1 from auth.users where id=actor_id and not is_anonymous) then
  return jsonb_build_object('error','Sign in with a full account.'); end if;
 insert into sdi_private.feed_budget values(actor_id,clock_timestamp(),1)
 on conflict(actor) do update set attempts=case when feed_budget.started_at<clock_timestamp()-interval '1 minute' then 1 else feed_budget.attempts+1 end,
 started_at=case when feed_budget.started_at<clock_timestamp()-interval '1 minute' then clock_timestamp() else feed_budget.started_at end returning attempts into n;
 if n>60 then return jsonb_build_object('error','Please wait before trying again.'); end if;
 if action='list' then
  if page<0 or page>39 or category not in('recent','following','featured','trending') then return jsonb_build_object('error','Invalid feed page.'); end if;
  snapshot:=least(coalesce(as_of,clock_timestamp()),clock_timestamp());
  if snapshot<clock_timestamp()-interval '1 day' then return jsonb_build_object('error','This feed snapshot has expired. Refresh the feed.'); end if;
  select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into items from (
   select p.id,p.creator,p.creator_name,p.caption,p.published_at,p.allow_export,m.title,m.url,
    (select count(*) from sdi_private.feed_likes l where l.post=p.id) as likes,
    exists(select 1 from sdi_private.feed_likes l where l.post=p.id and l.actor=actor_id) as liked,
    exists(select 1 from sdi_private.feed_follows f where f.actor=actor_id and f.creator=p.creator) as following
   from sdi_private.feed_posts p join public.sdi_watch_media m on m.id=p.media_id
   where p.visible and m.approved and m.owner_id=p.creator and m.render_digest is not null
   and p.published_at<=snapshot
   and (m.expires_at is null or m.expires_at>clock_timestamp())
   and not sdi_private.creator_restricted(p.creator)
   and not exists(select 1 from sdi_private.feed_blocks b where (b.actor=actor_id and b.creator=p.creator) or (b.actor=p.creator and b.creator=actor_id))
   and (category<>'featured' or p.featured)
   and (category<>'following' or exists(select 1 from sdi_private.feed_follows f where f.actor=actor_id and f.creator=p.creator))
   order by case when category='trending' then (select count(*) from sdi_private.feed_likes l where l.post=p.id and l.created_at>clock_timestamp()-interval '7 days') else 0 end desc,
    p.published_at desc,p.id desc limit 25 offset page*25
  ) item;
  return jsonb_build_object('posts',items,'has_more',jsonb_array_length(items)=25,'as_of',snapshot);
 end if;
 if action in('follow','block') then
  if target is null or target=actor_id or not exists(select 1 from auth.users where id=target) then return jsonb_build_object('error','Creator unavailable.'); end if;
  if action='block' then
   if enabled then
    insert into sdi_private.feed_blocks values(actor_id,target) on conflict do nothing;
    delete from sdi_private.feed_follows where (actor=actor_id and creator=target) or (actor=target and creator=actor_id);
   else delete from sdi_private.feed_blocks where actor=actor_id and creator=target; end if;
  else
   if sdi_private.creator_restricted(target) or exists(select 1 from sdi_private.feed_blocks where (actor=actor_id and creator=target) or (actor=target and creator=actor_id)) then
    return jsonb_build_object('error','Creator unavailable.'); end if;
   if enabled then insert into sdi_private.feed_follows values(actor_id,target) on conflict do nothing;
   else delete from sdi_private.feed_follows where actor=actor_id and creator=target; end if;
  end if;
 else
  select p.* into entry from sdi_private.feed_posts p join public.sdi_watch_media m on m.id=p.media_id
   where p.id=post_id and p.visible and m.approved and m.owner_id=p.creator and m.render_digest is not null
   and (m.expires_at is null or m.expires_at>clock_timestamp())
   and not sdi_private.creator_restricted(p.creator)
   and not exists(select 1 from sdi_private.feed_blocks b where (b.actor=actor_id and b.creator=p.creator) or (b.actor=p.creator and b.creator=actor_id));
  if not found then return jsonb_build_object('error','Post unavailable.'); end if;
  if action='like' then
   if entry.creator=actor_id then return jsonb_build_object('error','You cannot like your own video.'); end if;
   if enabled then insert into sdi_private.feed_likes(post,actor) values(post_id,actor_id) on conflict do nothing;
   else delete from sdi_private.feed_likes where post=post_id and actor=actor_id; end if;
  elsif action='report' and reason in('rights','abuse','unsafe','spam') then
   if entry.creator=actor_id then return jsonb_build_object('error','Use consent withdrawal for your own video.'); end if;
   if (select count(*) from sdi_private.feed_reports r where r.actor=actor_id and r.created_at>clock_timestamp()-interval '1 day')>=10 then
    return jsonb_build_object('error','Daily report limit reached.'); end if;
   -- One report per account per post. A dismissed or actioned report is final;
   -- a repeat submission records nothing new and never reopens the queue item.
   insert into sdi_private.feed_reports(post,actor,reason) values(post_id,actor_id,reason) on conflict(post,actor) do nothing;
   return jsonb_build_object('status','recorded');
  else return jsonb_build_object('error','Unsupported feed operation.'); end if;
 end if;
 return jsonb_build_object('status','confirmed');
end $$;

-- War Room: proposals expire after seven days and stop counting toward the
-- five-active limit; restricted creators and their matches leave listings.
alter table sdi_private.war_matches drop constraint war_matches_status_check;
alter table sdi_private.war_matches add constraint war_matches_status_check
 check(status in ('pending','active','completed','withdrawn','removed','expired'));
create function sdi_private.war_proposal_live(m sdi_private.war_matches) returns boolean
language sql stable set search_path='' as $$
 select m.status='pending' and m.created_at>clock_timestamp()-interval '7 days'
$$;
revoke all on function sdi_private.war_proposal_live(sdi_private.war_matches) from public,anon;
grant execute on function sdi_private.war_proposal_live(sdi_private.war_matches) to authenticated,service_role;
create function sdi_private.war_expire_proposals() returns integer
language plpgsql security definer set search_path='' as $$
declare n integer;
begin
 update sdi_private.war_matches set status='expired' where status='pending' and created_at<=clock_timestamp()-interval '7 days';
 get diagnostics n=row_count; return n;
end $$;
revoke all on function sdi_private.war_expire_proposals() from public,anon,authenticated;
grant execute on function sdi_private.war_expire_proposals() to service_role;
create function public.sdi_war_expire_proposals() returns integer language sql security invoker set search_path='' as $$select sdi_private.war_expire_proposals()$$;
revoke all on function public.sdi_war_expire_proposals() from public,anon,authenticated;
grant execute on function public.sdi_war_expire_proposals() to service_role;

create or replace function sdi_private.war_action(action text, match uuid default null, media uuid default null,
 opponent uuid default null, choice text default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare actor uuid:=auth.uid(); n integer; m sdi_private.war_matches; video public.sdi_watch_media; result jsonb;
begin
 if actor is null or not sdi_private.account_active() or not exists(select 1 from auth.users where id=actor and not is_anonymous) then
  return jsonb_build_object('error','Sign in with a full account.'); end if;
 insert into sdi_private.war_budget values(actor,clock_timestamp(),1)
 on conflict(user_id) do update set
 attempts=case when sdi_private.war_budget.starts_at<clock_timestamp()-interval '1 minute' then 1 else sdi_private.war_budget.attempts+1 end,
 starts_at=case when sdi_private.war_budget.starts_at<clock_timestamp()-interval '1 minute' then clock_timestamp() else sdi_private.war_budget.starts_at end
 returning attempts into n;
 if n>60 then return jsonb_build_object('error','Too many requests. Wait a minute.'); end if;
 if action='list' then
  select coalesce(jsonb_agg(row_to_json(items)),'[]'::jsonb) into result from (
   select w.id,w.creator,w.opponent,w.status,w.ends_at,l.title as left_title,l.url as left_url,
    r.title as right_title,r.url as right_url,final.outcome,
    coalesce(final.left_votes,(select count(*) from sdi_private.war_votes where match_id=w.id and war_votes.choice='left')) as left_votes,
    coalesce(final.right_votes,(select count(*) from sdi_private.war_votes where match_id=w.id and war_votes.choice='right')) as right_votes,
    (select war_votes.choice from sdi_private.war_votes where match_id=w.id and voter=actor) as my_vote
   from sdi_private.war_matches w join public.sdi_watch_media l on l.id=w.left_media
   left join public.sdi_watch_media r on r.id=w.right_media
   left join sdi_private.war_results final on final.match_id=w.id
   where (w.status in('active','completed') or (sdi_private.war_proposal_live(w) and actor in(w.creator,w.opponent)))
   and l.approved and l.render_digest=w.left_digest and (l.expires_at is null or l.expires_at>clock_timestamp())
   and (w.status='pending' or (r.approved and r.render_digest=w.right_digest and (r.expires_at is null or r.expires_at>clock_timestamp())))
   and not sdi_private.creator_restricted(w.creator) and not sdi_private.creator_restricted(w.opponent)
   and not exists(select 1 from sdi_private.war_blocks b where
     (b.blocker=actor and b.blocked in(w.creator,w.opponent)) or (b.blocked=actor and b.blocker in(w.creator,w.opponent)))
   order by w.created_at desc limit 100
  ) items;
  return jsonb_build_object('matches',result);
 elsif action='propose' then
  if opponent is null or opponent=actor or not exists(select 1 from auth.users where id=opponent and not is_anonymous)
   or sdi_private.creator_restricted(opponent) then
   return jsonb_build_object('error','Choose another eligible creator.'); end if;
  if exists(select 1 from sdi_private.war_blocks b where (b.blocker=actor and b.blocked=opponent) or (b.blocker=opponent and b.blocked=actor)) then
   return jsonb_build_object('error','Matchup unavailable.'); end if;
  if (select count(*) from sdi_private.war_matches w where w.creator=actor and
   (sdi_private.war_proposal_live(w) or (w.status='active' and (w.ends_at is null or w.ends_at>clock_timestamp()))))>=5 then
   return jsonb_build_object('error','Finish or withdraw an existing matchup first.'); end if;
  select * into video from public.sdi_watch_media where id=media and owner_id=actor and approved and render_digest is not null
   and (expires_at is null or expires_at>clock_timestamp());
  if not found then return jsonb_build_object('error','Select your approved rendered video.'); end if;
  insert into sdi_private.war_matches(creator,opponent,left_media,left_digest) values(actor,opponent,media,video.render_digest);
 elsif action='block' then
  if opponent is null or opponent=actor then return jsonb_build_object('error','Invalid creator.'); end if;
  insert into sdi_private.war_blocks values(actor,opponent) on conflict do nothing;
  update sdi_private.war_matches set status='withdrawn' where status in('pending','active') and
   ((creator=actor and war_matches.opponent=war_action.opponent) or (creator=war_action.opponent and war_matches.opponent=actor));
 else
  select * into m from sdi_private.war_matches where id=match for update;
  if not found then return jsonb_build_object('error','Matchup unavailable.'); end if;
  if m.status='pending' and not sdi_private.war_proposal_live(m) then
   update sdi_private.war_matches set status='expired' where id=m.id;
   return jsonb_build_object('error','This proposal expired after seven days.'); end if;
  if action='withdraw' then
   if actor not in(m.creator,m.opponent) then return jsonb_build_object('error','Only participants can withdraw.'); end if;
   if m.ends_at is not null and m.ends_at<=clock_timestamp() then return jsonb_build_object('error','Voting has ended; contact moderation for an appeal.'); end if;
   update sdi_private.war_matches set status='withdrawn' where id=match;
  elsif action='accept' then
   if m.opponent<>actor or m.status<>'pending' then return jsonb_build_object('error','No pending invitation.'); end if;
   if sdi_private.creator_restricted(m.creator) or exists(select 1 from sdi_private.war_blocks b where (b.blocker=actor and b.blocked=m.creator) or (b.blocker=m.creator and b.blocked=actor)) then
    return jsonb_build_object('error','Matchup unavailable.'); end if;
   select * into video from public.sdi_watch_media where id=media and owner_id=actor and approved and render_digest is not null
    and (expires_at is null or expires_at>clock_timestamp()+interval '24 hours');
   if not found then return jsonb_build_object('error','Select an approved video available for the voting period.'); end if;
   if not exists(select 1 from public.sdi_watch_media where id=m.left_media and approved and render_digest=m.left_digest and (expires_at is null or expires_at>clock_timestamp()+interval '24 hours')) then
    return jsonb_build_object('error','The other video is unavailable.'); end if;
   update sdi_private.war_matches set right_media=media,right_digest=video.render_digest,status='active',starts_at=clock_timestamp(),ends_at=clock_timestamp()+interval '24 hours' where id=match;
  elsif action='vote' then
   if choice is null or choice not in('left','right') or actor in(m.creator,m.opponent) or m.status<>'active' or m.ends_at<=clock_timestamp() then
    return jsonb_build_object('error','Voting is not available to this account.'); end if;
   if sdi_private.creator_restricted(m.creator) or sdi_private.creator_restricted(m.opponent)
    or exists(select 1 from sdi_private.war_blocks b where (b.blocker=actor and b.blocked in(m.creator,m.opponent)) or (b.blocked=actor and b.blocker in(m.creator,m.opponent))) then
    return jsonb_build_object('error','Voting is unavailable.'); end if;
   if (select count(*) from public.sdi_watch_media where approved and (expires_at is null or expires_at>clock_timestamp())
     and ((id=m.left_media and render_digest=m.left_digest) or (id=m.right_media and render_digest=m.right_digest)))<>2 then
    return jsonb_build_object('error','A submitted video is no longer approved.'); end if;
   insert into sdi_private.war_votes values(match,actor,choice) on conflict(match_id,voter) do update set choice=excluded.choice;
  else return jsonb_build_object('error','Unsupported operation.'); end if;
 end if;
 return jsonb_build_object('status','confirmed');
end $$;

-- Problem 6: intake registers artifacts with a 24-hour expiry while approval and
-- every publishing lease require an unexpired artifact. Private renders under
-- review are retained seven days; an approved render is retained thirty days so
-- the publishing worker can finish. Retention is bounded and documented; nothing
-- here publishes or extends a preview URL. Rejected renders expire as registered.
create function sdi_private.retain_artifact_for_review() returns trigger language plpgsql set search_path='' as $$
begin
 new.expires_at=greatest(new.expires_at,clock_timestamp()+interval '7 days');
 return new;
end $$;
revoke all on function sdi_private.retain_artifact_for_review() from public;
create trigger retain_artifact_for_review before insert on sdi_private.render_artifacts
for each row execute function sdi_private.retain_artifact_for_review();
create function sdi_private.retain_artifact_after_approval() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if new.state='approved' and (old.state is distinct from 'approved' or new.version<>old.version) then
  update sdi_private.render_artifacts set expires_at=greatest(expires_at,clock_timestamp()+interval '30 days')
  where review_id=new.id and version=new.version and render_digest=new.render_digest;
 end if;
 return new;
end $$;
revoke all on function sdi_private.retain_artifact_after_approval() from public,anon,authenticated;
create trigger retain_artifact_after_approval after update on sdi_private.render_reviews
for each row execute function sdi_private.retain_artifact_after_approval();
-- Keyset (cursor) paging for the social wall (#217, #220). Each page is ordered by
-- (score desc, published_at desc, id desc) and the next page starts strictly after
-- the last row's key, so posts published, liked or removed meanwhile can neither
-- duplicate nor skip a row the member has not reached. `score` is 0 except in
-- Trending, where it counts likes inside the seven days ending at the snapshot
-- instant; likes recorded after the snapshot do not move rows. An unlike or a
-- moderation removal can still lower or drop a row: that row is simply absent or
-- appears once more further down, which the client de-duplicates by identity.
-- `can_download` is the creator's export permission AND a current paid
-- entitlement of the viewer (billing.sql); the Free plan cannot download (#219).
create index if not exists feed_posts_recent on sdi_private.feed_posts(published_at desc,id desc) where visible;
create index if not exists feed_likes_post_time on sdi_private.feed_likes(post,created_at);
create function sdi_private.feed_page(category text default 'recent', page_cursor text default null, as_of timestamptz default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare actor_id uuid:=auth.uid(); n integer; items jsonb; snapshot timestamptz; total integer; paid boolean;
 parts text[]; c_score bigint; c_published timestamptz; c_id uuid; last_row jsonb; next_cursor text;
begin
 if actor_id is null or not sdi_private.account_active() or not exists(select 1 from auth.users where id=actor_id and not is_anonymous) then
  return jsonb_build_object('error','Sign in with a full account.'); end if;
 insert into sdi_private.feed_budget values(actor_id,clock_timestamp(),1)
 on conflict(actor) do update set attempts=case when feed_budget.started_at<clock_timestamp()-interval '1 minute' then 1 else feed_budget.attempts+1 end,
 started_at=case when feed_budget.started_at<clock_timestamp()-interval '1 minute' then clock_timestamp() else feed_budget.started_at end returning attempts into n;
 if n>60 then return jsonb_build_object('error','Please wait before trying again.'); end if;
 if category is null or category not in('recent','following','featured','trending') then return jsonb_build_object('error','Invalid feed page.'); end if;
 if page_cursor is not null then
  if as_of is null then return jsonb_build_object('error','A feed cursor needs its snapshot. Refresh the feed.'); end if;
  if length(page_cursor)>120 or page_cursor !~ '^[0-9]{1,9}\|[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}Z\|[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
   return jsonb_build_object('error','Invalid feed cursor. Refresh the feed.'); end if;
  parts:=string_to_array(page_cursor,'|');
  begin
   c_score:=parts[1]::bigint; c_published:=parts[2]::timestamptz; c_id:=parts[3]::uuid;
  exception when others then return jsonb_build_object('error','Invalid feed cursor. Refresh the feed.');
  end;
 end if;
 snapshot:=least(coalesce(as_of,clock_timestamp()),clock_timestamp());
 if snapshot<clock_timestamp()-interval '1 day' then return jsonb_build_object('error','This feed snapshot has expired. Refresh the feed.'); end if;
 paid:=exists(select 1 from sdi_private.entitlements e where e.user_id=actor_id);
 with eligible as (
  select p.id,p.creator,p.creator_name,p.caption,p.published_at,p.allow_export,m.title,m.url,
   case when category='trending' then (select count(*) from sdi_private.feed_likes l where l.post=p.id
    and l.created_at>snapshot-interval '7 days' and l.created_at<=snapshot) else 0 end::bigint as score
  from sdi_private.feed_posts p join public.sdi_watch_media m on m.id=p.media_id
  where p.visible and m.approved and m.owner_id=p.creator and m.render_digest is not null
  and p.published_at<=snapshot
  and (m.expires_at is null or m.expires_at>clock_timestamp())
  and not sdi_private.creator_restricted(p.creator)
  and not exists(select 1 from sdi_private.feed_blocks b where (b.actor=actor_id and b.creator=p.creator) or (b.actor=p.creator and b.creator=actor_id))
  and (category<>'featured' or p.featured)
  and (category<>'following' or exists(select 1 from sdi_private.feed_follows f where f.actor=actor_id and f.creator=p.creator))
 ), window_rows as (
  select * from eligible e
  where page_cursor is null or (e.score,e.published_at,e.id)<(c_score,c_published,c_id)
  order by e.score desc,e.published_at desc,e.id desc limit 26
 ), numbered as (
  select w.*,row_number() over(order by w.score desc,w.published_at desc,w.id desc) as position from window_rows w
 )
 select count(*)::integer,
  coalesce(jsonb_agg(jsonb_build_object('id',x.id,'creator',x.creator,'creator_name',x.creator_name,'caption',x.caption,
   'published_at',x.published_at,'allow_export',x.allow_export,'can_download',x.allow_export and paid,'title',x.title,'url',x.url,
   'score',x.score,
   'likes',(select count(*) from sdi_private.feed_likes l where l.post=x.id),
   'liked',exists(select 1 from sdi_private.feed_likes l where l.post=x.id and l.actor=actor_id),
   'following',exists(select 1 from sdi_private.feed_follows f where f.actor=actor_id and f.creator=x.creator))
   order by x.position) filter(where x.position<=25),'[]'::jsonb),
  (select jsonb_build_object('score',y.score,'published_at',y.published_at,'id',y.id) from numbered y where y.position=25)
 into total,items,last_row from numbered x;
 if total>25 then
  next_cursor:=(last_row->>'score')||'|'||to_char((last_row->>'published_at')::timestamptz at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')||'|'||(last_row->>'id');
 end if;
 return jsonb_build_object('posts',items,'has_more',total>25,'next_cursor',next_cursor,'as_of',snapshot,'download_requires_plan',not paid);
end $$;
revoke all on function sdi_private.feed_page(text,text,timestamptz) from public,anon;
grant execute on function sdi_private.feed_page(text,text,timestamptz) to authenticated;
create function public.sdi_feed_page(category text default 'recent', page_cursor text default null, as_of timestamptz default null) returns jsonb
language sql security invoker set search_path='' as $$select sdi_private.feed_page(category,page_cursor,as_of)$$;
revoke all on function public.sdi_feed_page(text,text,timestamptz) from public,anon;
grant execute on function public.sdi_feed_page(text,text,timestamptz) to authenticated;

-- Creator totals for the profile (#224): counted from the same eligible rows the
-- feed shows, never estimated. A blocked or restricted creator is unavailable.
-- `following` is returned only to the account itself.
create function sdi_private.creator_stats(subject uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare viewer uuid:=auth.uid(); target uuid:=coalesce(subject,auth.uid()); posts bigint; likes bigint; followers bigint; follows bigint;
begin
 if viewer is null or not sdi_private.account_active() or not exists(select 1 from auth.users where id=viewer and not is_anonymous) then
  return jsonb_build_object('error','Sign in with a full account.'); end if;
 if not exists(select 1 from auth.users where id=target and not is_anonymous)
  or (target<>viewer and (sdi_private.creator_restricted(target)
   or exists(select 1 from sdi_private.feed_blocks b where (b.actor=viewer and b.creator=target) or (b.actor=target and b.creator=viewer)))) then
  return jsonb_build_object('error','Profile unavailable.'); end if;
 select count(*),coalesce(sum((select count(*) from sdi_private.feed_likes l where l.post=p.id)),0) into posts,likes
 from sdi_private.feed_posts p join public.sdi_watch_media m on m.id=p.media_id
 where p.creator=target and p.visible and m.approved and m.owner_id=p.creator and m.render_digest is not null
  and (m.expires_at is null or m.expires_at>clock_timestamp());
 select count(*) into followers from sdi_private.feed_follows f where f.creator=target and not sdi_private.creator_restricted(f.actor);
 if target=viewer then select count(*) into follows from sdi_private.feed_follows f where f.actor=target; end if;
 return jsonb_build_object('subject',target,'published_videos',posts,'likes_received',likes,'followers',followers,'following',follows);
end $$;
revoke all on function sdi_private.creator_stats(uuid) from public,anon;
grant execute on function sdi_private.creator_stats(uuid) to authenticated;
create function public.sdi_creator_stats(subject uuid default null) returns jsonb
language sql security invoker set search_path='' as $$select sdi_private.creator_stats(subject)$$;
revoke all on function public.sdi_creator_stats(uuid) from public,anon;
grant execute on function public.sdi_creator_stats(uuid) to authenticated;
commit;

-- ===== feed-publication.sql (sha256 947055bb143f9ac2) =====
-- Unapplied candidate. Install after feed-integrity.sql.
-- Publication path for the 'feed' destination. Only the publishing service claims
-- and finishes feed jobs; every claim, renewal and finish re-evaluates
-- release_allowed(review, version, digest, 'feed'): owner/admin approval of the
-- exact digest, creator consent, cleared rights, active account, retained artifact
-- and owner approval for Spatter renders. Nothing here publishes without it.
begin;
-- Creator-controlled file-export permission. Not part of approval evidence, so
-- toggling it does not invalidate the review; it is copied to the live post.
alter table sdi_private.render_reviews add column allow_export boolean not null default false;
alter table public.sdi_watch_media add column review_id uuid references sdi_private.render_reviews(id);
create unique index watch_media_render_digest on public.sdi_watch_media(render_digest) where render_digest is not null;
create function sdi_private.export_consent(review uuid,version bigint,allowed boolean) returns jsonb
language plpgsql security definer set search_path='' as $$
declare r sdi_private.render_reviews;
begin
 if not sdi_private.account_active() then return jsonb_build_object('error','Current account session required.');end if;
 if review is null or version is null or allowed is null then return jsonb_build_object('error','Select a render and an explicit export choice.');end if;
 select * into r from sdi_private.render_reviews where id=review and creator=auth.uid() for update;
 if not found or r.version<>version then return jsonb_build_object('error','Render changed. Refresh before changing export permission.');end if;
 update sdi_private.render_reviews set allow_export=allowed where id=r.id;
 update sdi_private.feed_posts p set allow_export=allowed from public.sdi_watch_media m
  where m.id=p.media_id and m.render_digest=r.render_digest and p.creator=auth.uid();
 return jsonb_build_object('status','confirmed','allow_export',allowed);
end $$;
revoke all on function sdi_private.export_consent(uuid,bigint,boolean) from public,anon;
grant execute on function sdi_private.export_consent(uuid,bigint,boolean) to authenticated;
create function public.sdi_export_consent(review uuid,version bigint,allowed boolean) returns jsonb
language sql security invoker set search_path='' as $$select sdi_private.export_consent(review,version,allowed)$$;
revoke all on function public.sdi_export_consent(uuid,bigint,boolean) from public,anon;
grant execute on function public.sdi_export_consent(uuid,bigint,boolean) to authenticated;

-- Creators can queue the feed destination of an approved render themselves.
create or replace function sdi_private.creator_review(action text,review uuid default null,version bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare r sdi_private.render_reviews; items jsonb; target text;
begin
 if not sdi_private.account_active() then return jsonb_build_object('error','Current account session required.');end if;
 if action='list' then
  select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into items from (
   select id,title,render_digest,render_reviews.version,state,consent_version,destinations,allow_export,
    sdi_private.release_allowed(id,render_reviews.version,render_digest,'youtube') as can_publish,
    sdi_private.release_allowed(id,render_reviews.version,render_digest,'feed') as can_publish_feed
   from sdi_private.render_reviews where creator=auth.uid() order by created_at desc,id limit 100
  ) item;
  return jsonb_build_object('reviews',items);
 end if;
 if action is null or action not in('withdraw_consent','publish_youtube','publish_feed') or review is null or version is null then
  return jsonb_build_object('error','Select a current reviewed render.');end if;
 select * into r from sdi_private.render_reviews where id=review and creator=auth.uid() for update;
 if not found or r.version<>version then return jsonb_build_object('error','Render changed. Refresh before acting.');end if;
 if action='withdraw_consent' then
  update sdi_private.render_reviews set consent_version='',destinations=array[]::text[],state='pending' where id=r.id;
  return jsonb_build_object('status','consent_withdrawn');
 end if;
 target:=case action when 'publish_feed' then 'feed' else 'youtube' end;
 if exists(select 1 from sdi_private.publish_jobs where review_id=r.id and review_version=r.version and destination=target) then
  return jsonb_build_object('error','This render already has a publishing job. Manage it in Publishing activity.');end if;
 return sdi_private.publish_action('enqueue',r.id,target,null);
end $$;

-- Worker claim for feed jobs. Mirrors publish_claim but for the feed destination;
-- the worker copies the private artifact bytes to the approved HTTPS hosting and
-- must verify the SHA-256 of the actual bytes before calling finish.
create function sdi_private.feed_publish_claim() returns jsonb language plpgsql security definer set search_path='' as $$
declare j sdi_private.publish_jobs; a sdi_private.render_artifacts; r sdi_private.render_reviews; name text;
begin
 update sdi_private.publish_jobs set state='reconcile',last_error='Worker lease expired; reconcile hosting before retry.',updated_at=clock_timestamp()
 where state='leased' and lease_expires<clock_timestamp();
 select * into j from sdi_private.publish_jobs where state='queued' and destination='feed' and attempts<5 and next_attempt<=clock_timestamp()
 order by created_at for update skip locked limit 1;
 if not found then return jsonb_build_object('empty',true);end if;
 if not sdi_private.release_allowed(j.review_id,j.review_version,j.render_digest,'feed') then
  update sdi_private.publish_jobs set state='cancelled',last_error='Approval, consent, rights or artifact no longer valid.',updated_at=clock_timestamp() where id=j.id;
  return jsonb_build_object('empty',true);
 end if;
 select * into a from sdi_private.render_artifacts where review_id=j.review_id and version=j.review_version;
 select * into r from sdi_private.render_reviews where id=j.review_id;
 select left(coalesce(nullif(trim(raw_user_meta_data->>'username'),''),'Member'),100) into name from auth.users where id=j.creator;
 update sdi_private.publish_jobs set state='leased',attempts=attempts+1,lease=gen_random_uuid(),lease_expires=clock_timestamp()+interval '2 minutes',updated_at=clock_timestamp()
 where id=j.id returning * into j;
 return jsonb_build_object('job',j.id,'lease',j.lease,'destination','feed','digest',j.render_digest,'object_key',a.object_key,
  'byte_count',a.byte_count,'title',a.title,'description',a.description,'made_for_kids',a.made_for_kids,
  'creator',j.creator,'creator_name',name,'allow_export',r.allow_export,'spatter_generated',r.spatter_generated);
end $$;
-- Finish inserts the approved public rendition and the visible post atomically.
-- If approval lapsed or cancellation raced the copy, the hosted copy is already
-- public, so the job becomes removal_pending for the feed removal worker.
create function sdi_private.feed_publish_finish(job uuid,token uuid,url text,duration double precision,failure text default null) returns boolean
language plpgsql security definer set search_path='' as $$
declare j sdi_private.publish_jobs; a sdi_private.render_artifacts; r sdi_private.render_reviews; media uuid; name text;
begin
 select * into j from sdi_private.publish_jobs where id=job and lease=token and destination='feed' for update;
 if not found then return false;end if;
 if j.state='published' then return j.result_url=url;end if;
 if j.state not in('leased','cancel_requested','reconcile') then return false;end if;
 if failure is not null then
  update sdi_private.publish_jobs set state=case when j.state='cancel_requested' then 'cancelled' else 'failed' end,
   last_error=left(failure,500),next_attempt=clock_timestamp()+make_interval(secs=>least(3600,30*power(2,j.attempts)::integer)),updated_at=clock_timestamp() where id=j.id;
  return true;
 end if;
 if url is null or url !~ '^https://' or length(url)>2048 or duration is null or duration<=0 or duration>3600 then return false;end if;
 if j.state='cancel_requested' or not sdi_private.release_allowed(j.review_id,j.review_version,j.render_digest,'feed') then
  -- The copy step is over, so the lease is released and removal may start at once.
  update sdi_private.publish_jobs set state='removal_pending',provider_id='feed:'||j.render_digest,result_url=url,lease=null,lease_expires=null,
   last_error='Hosted copy must be removed: approval or consent changed before release.',updated_at=clock_timestamp() where id=j.id;
  return true;
 end if;
 select * into a from sdi_private.render_artifacts where review_id=j.review_id and version=j.review_version;
 select * into r from sdi_private.render_reviews where id=j.review_id;
 select left(coalesce(nullif(trim(raw_user_meta_data->>'username'),''),'Member'),100) into name from auth.users where id=j.creator;
 insert into public.sdi_watch_media(title,url,duration,approved,owner_id,render_digest,review_id)
 values(left(a.title,200),url,duration,true,j.creator,j.render_digest,j.review_id)
 on conflict(render_digest) where render_digest is not null do update set title=excluded.title,url=excluded.url,duration=excluded.duration,
  approved=true,owner_id=excluded.owner_id,review_id=excluded.review_id,expires_at=null
 returning id into media;
 insert into sdi_private.feed_posts(media_id,creator,creator_name,caption,visible,allow_export)
 values(media,j.creator,name,left(a.description,2000),true,r.allow_export)
 on conflict(media_id) do update set creator=excluded.creator,creator_name=excluded.creator_name,caption=excluded.caption,
  visible=true,allow_export=excluded.allow_export,published_at=clock_timestamp();
 update sdi_private.publish_jobs set state='published',provider_id='feed:'||media::text,result_url=url,phase='release',updated_at=clock_timestamp() where id=j.id;
 return true;
end $$;
-- Removal worker for hosted feed copies: moderation removals (removal_jobs) and
-- cancelled-after-copy publish jobs. Confirmed deletion is the only success.
alter table sdi_private.removal_jobs add column attempts integer not null default 0;
alter table sdi_private.removal_jobs add column lease uuid;
alter table sdi_private.removal_jobs add column lease_expires timestamptz;
create function sdi_private.feed_removal_claim() returns jsonb language plpgsql security definer set search_path='' as $$
declare j sdi_private.publish_jobs; d sdi_private.removal_jobs; target text;
begin
 select * into j from sdi_private.publish_jobs where state='removal_pending' and destination='feed' and result_url is not null
  and removal_attempts<5 and (lease_expires is null or lease_expires<clock_timestamp()-interval '60 seconds')
  order by updated_at for update skip locked limit 1;
 if found then
  update sdi_private.publish_jobs set lease=gen_random_uuid(),lease_expires=clock_timestamp()+interval '2 minutes',
   removal_attempts=removal_attempts+1,updated_at=clock_timestamp() where id=j.id returning * into j;
  return jsonb_build_object('source','publish_job','job',j.id,'lease',j.lease,'url',j.result_url,'digest',j.render_digest);
 end if;
 select rj.* into d from sdi_private.removal_jobs rj join public.sdi_watch_media m on m.id=rj.media_id
  where rj.state in('pending','failed') and rj.attempts<5 and m.review_id is not null
  and (rj.lease_expires is null or rj.lease_expires<clock_timestamp()-interval '60 seconds')
  order by rj.created_at for update of rj skip locked limit 1;
 if not found then return jsonb_build_object('empty',true);end if;
 select url into target from public.sdi_watch_media where id=d.media_id;
 update sdi_private.removal_jobs set state='running',lease=gen_random_uuid(),lease_expires=clock_timestamp()+interval '2 minutes',attempts=attempts+1
  where id=d.id returning * into d;
 return jsonb_build_object('source','removal_job','job',d.id,'lease',d.lease,'url',target,'digest',d.render_digest);
end $$;
create function sdi_private.feed_removal_finish(source text,job uuid,token uuid,confirmed boolean) returns boolean
language plpgsql security definer set search_path='' as $$
begin
 if confirmed is null then return false;end if;
 if source='publish_job' then
  update sdi_private.publish_jobs set state=case when confirmed then 'cancelled' else 'removal_pending' end,
   result_url=case when confirmed then null else result_url end,
   last_error=case when confirmed then 'Hosted feed copy removed; originals preserved.' else 'Feed copy removal not confirmed; bounded retry pending.' end,
   lease=null,lease_expires=null,updated_at=clock_timestamp()
  where id=job and lease=token and state='removal_pending' and destination='feed';
  return found;
 elsif source='removal_job' then
  update sdi_private.removal_jobs set state=case when confirmed then 'complete' else 'failed' end,lease=null,lease_expires=null
  where id=job and lease=token and state='running';
  return found;
 end if;
 return false;
end $$;
revoke all on function sdi_private.feed_publish_claim(),sdi_private.feed_publish_finish(uuid,uuid,text,double precision,text),
 sdi_private.feed_removal_claim(),sdi_private.feed_removal_finish(text,uuid,uuid,boolean) from public,anon,authenticated;
grant execute on function sdi_private.feed_publish_claim(),sdi_private.feed_publish_finish(uuid,uuid,text,double precision,text),
 sdi_private.feed_removal_claim(),sdi_private.feed_removal_finish(text,uuid,uuid,boolean) to service_role;
create function public.sdi_feed_publish_claim() returns jsonb language sql security invoker set search_path='' as $$select sdi_private.feed_publish_claim()$$;
create function public.sdi_feed_publish_finish(job uuid,token uuid,url text,duration double precision,failure text default null) returns boolean
language sql security invoker set search_path='' as $$select sdi_private.feed_publish_finish(job,token,url,duration,failure)$$;
create function public.sdi_feed_removal_claim() returns jsonb language sql security invoker set search_path='' as $$select sdi_private.feed_removal_claim()$$;
create function public.sdi_feed_removal_finish(source text,job uuid,token uuid,confirmed boolean) returns boolean
language sql security invoker set search_path='' as $$select sdi_private.feed_removal_finish(source,job,token,confirmed)$$;
revoke all on function public.sdi_feed_publish_claim(),public.sdi_feed_publish_finish(uuid,uuid,text,double precision,text),
 public.sdi_feed_removal_claim(),public.sdi_feed_removal_finish(text,uuid,uuid,boolean) from public,anon,authenticated;
grant execute on function public.sdi_feed_publish_claim(),public.sdi_feed_publish_finish(uuid,uuid,text,double precision,text),
 public.sdi_feed_removal_claim(),public.sdi_feed_removal_finish(text,uuid,uuid,boolean) to service_role;
commit;

-- ===== rooms-v2.sql (sha256 3fc2e08a25799b69) =====
-- Unapplied candidate. Install after feed-publication.sql (needs room-invitations.sql,
-- moderation.sql and admin-users.sql). Rooms remain invitation-based collaboration on
-- an explicitly shared Studio project: no chat, calls, media streams or draft harvesting.
-- project_ref is an opaque identifier of the shared on-device project, never content.
begin;
alter table public.sdi_rooms add column project_ref text check(length(project_ref) between 1 and 200);
alter table public.sdi_rooms add column project_title text check(length(project_title) between 1 and 100);
alter table public.sdi_rooms add column permissions text[] not null default array['view']
 check(permissions <@ array['view','edit'] and 'view'=any(permissions));
alter table public.sdi_rooms add column project_revision bigint not null default 1;
alter table public.sdi_rooms add column command_revision bigint not null default 0;
alter table public.sdi_room_members add column role text not null default 'viewer' check(role in('editor','viewer'));
-- Editing requires the room to share edit permission AND an editor role (or ownership).
create function sdi_private.room_can_edit(r uuid) returns boolean
language sql stable security definer set search_path='' as $$
 select auth.uid() is not null and exists (
  select 1 from public.sdi_rooms room where room.id=r and not room.closed and 'edit'=any(room.permissions)
  and (room.owner_id=auth.uid() or exists (
   select 1 from public.sdi_room_members m where m.room_id=r and m.user_id=auth.uid()
   and m.owner_approved and m.member_accepted and not m.revoked and m.role='editor')))
$$;
revoke all on function sdi_private.room_can_edit(uuid) from public,anon;
grant execute on function sdi_private.room_can_edit(uuid) to authenticated;

create table sdi_private.room_reports (
 id uuid primary key default gen_random_uuid(), room_id uuid not null references public.sdi_rooms(id),
 reporter uuid not null references auth.users(id), reason text not null check(reason in('rights','abuse','unsafe','spam')),
 detail text not null default '' check(length(detail)<=2000),
 state text not null default 'pending' check(state in('pending','dismissed','closed')),
 revision bigint not null default 1, created_at timestamptz not null default clock_timestamp(), unique(room_id,reporter)
);
create table sdi_private.room_moderation_audit (
 id uuid primary key default gen_random_uuid(), report_id uuid not null references sdi_private.room_reports(id),
 room_id uuid not null, actor uuid not null references auth.users(id), decision text not null,
 reason text not null check(length(reason) between 1 and 2000), created_at timestamptz not null default clock_timestamp()
);
-- Versioned shared edits: one append per operation id, strictly increasing room
-- revision, explicit conflicts. Payloads are bounded Studio commands, not media.
create table sdi_private.room_commands (
 room_id uuid not null references public.sdi_rooms(id) on delete cascade, revision bigint not null,
 op_id uuid not null, author uuid not null references auth.users(id), base_revision bigint not null,
 kind text not null check(length(kind) between 1 and 64), payload jsonb not null check(octet_length(payload::text)<=65536),
 created_at timestamptz not null default clock_timestamp(), primary key(room_id,revision), unique(room_id,op_id)
);
create table sdi_private.room_command_budget (
 user_id uuid primary key references auth.users(id) on delete cascade, window_start timestamptz not null, attempts integer not null
);
alter table sdi_private.room_reports enable row level security;
alter table sdi_private.room_moderation_audit enable row level security;
alter table sdi_private.room_commands enable row level security;
alter table sdi_private.room_command_budget enable row level security;
revoke all on sdi_private.room_reports,sdi_private.room_moderation_audit,sdi_private.room_commands,sdi_private.room_command_budget from public,anon,authenticated;

create function sdi_private.room_manage(action text,room uuid default null,subject uuid default null,role text default null,
 project_ref text default null,project_title text default null,permissions text[] default null,revision bigint default null,
 reason text default null,detail text default null) returns jsonb
language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare actor uuid:=auth.uid(); target public.sdi_rooms; n integer; items jsonb; my_role text;
begin
 if actor is null or not sdi_private.account_active() or not exists(select 1 from auth.users where id=actor and not is_anonymous) then
  return jsonb_build_object('error','Sign in with a full account.'); end if;
 insert into sdi_private.room_request_budget values(actor,clock_timestamp(),1)
 on conflict(user_id) do update set
 attempts=case when room_request_budget.window_start<clock_timestamp()-interval '1 minute' then 1 else room_request_budget.attempts+1 end,
 window_start=case when room_request_budget.window_start<clock_timestamp()-interval '1 minute' then clock_timestamp() else room_request_budget.window_start end
 returning attempts into n;
 if n>30 then return jsonb_build_object('error','Too many requests. Wait a minute.'); end if;
 if action='my_requests' then
  select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into items from (
   select r.id as room_id,r.title,r.owner_id,m.request_expires_at from public.sdi_room_members m join public.sdi_rooms r on r.id=m.room_id
   where m.user_id=actor and m.member_accepted and not m.owner_approved and not m.revoked and m.request_expires_at>clock_timestamp() and not r.closed
   order by m.request_expires_at limit 100
  ) item;
  return jsonb_build_object('requests',items);
 end if;
 select * into target from public.sdi_rooms where id=room and not closed for update;
 if not found or not sdi_private.room_access(target.id) then return jsonb_build_object('error','Room is unavailable.'); end if;
 if action='summary' then
  select case when target.owner_id=actor then 'owner' else (select m.role from public.sdi_room_members m where m.room_id=target.id and m.user_id=actor) end into my_role;
  return jsonb_build_object('room_id',target.id,'title',target.title,'owner_id',target.owner_id,'project_ref',target.project_ref,'project_title',target.project_title,
   'permissions',to_jsonb(target.permissions),'project_revision',target.project_revision,'command_revision',target.command_revision,'my_role',my_role,
   'can_edit',sdi_private.room_can_edit(target.id),
   'members',(select count(*) from public.sdi_room_members m where m.room_id=target.id and m.owner_approved and m.member_accepted and not m.revoked));
 end if;
 if action='report' then
  if reason is null or reason not in('rights','abuse','unsafe','spam') or detail is null or length(detail)>2000 then
   return jsonb_build_object('error','Choose a report reason.'); end if;
  if target.owner_id=actor then return jsonb_build_object('error','Close your own room instead of reporting it.'); end if;
  if exists(select 1 from sdi_private.room_reports where room_id=target.id and reporter=actor) then return jsonb_build_object('status','recorded'); end if;
  if (select count(*) from sdi_private.room_reports where reporter=actor and created_at>clock_timestamp()-interval '1 day')>=10 then
   return jsonb_build_object('error','Daily report limit reached.'); end if;
  insert into sdi_private.room_reports(room_id,reporter,reason,detail) values(target.id,actor,room_manage.reason,trim(room_manage.detail)) on conflict do nothing;
  return jsonb_build_object('status','recorded');
 end if;
 if target.owner_id<>actor then return jsonb_build_object('error','Only the owner can perform this operation.'); end if;
 if action='set_project' then
  if project_ref is null or length(trim(project_ref)) not between 1 and 200 or project_title is null or length(trim(project_title)) not between 1 and 100
   or permissions is null or not permissions <@ array['view','edit'] or not 'view'=any(permissions) or revision is distinct from target.project_revision then
   return jsonb_build_object('error','Current project reference, title, permissions and revision are required.'); end if;
  update public.sdi_rooms set project_ref=trim(room_manage.project_ref),project_title=trim(room_manage.project_title),permissions=room_manage.permissions,
   project_revision=project_revision+1 where id=target.id;
  return jsonb_build_object('status','updated','project_revision',target.project_revision+1);
 elsif action='set_role' then
  if subject is null or subject=actor or role is null or role not in('editor','viewer') then return jsonb_build_object('error','Choose a member and a role.'); end if;
  if role='editor' and not 'edit'=any(target.permissions) then return jsonb_build_object('error','Share the project with edit permission before assigning editors.'); end if;
  update public.sdi_room_members set role=room_manage.role where room_id=target.id and user_id=subject and owner_approved and member_accepted and not revoked;
  if not found then return jsonb_build_object('error','That member is not an active participant.'); end if;
  return jsonb_build_object('status','updated');
 end if;
 return jsonb_build_object('error','Unsupported room operation.');
end $$;
revoke all on function sdi_private.room_manage(text,uuid,uuid,text,text,text,text[],bigint,text,text) from public,anon;
grant execute on function sdi_private.room_manage(text,uuid,uuid,text,text,text,text[],bigint,text,text) to authenticated;
create function public.sdi_room_manage(action text,room uuid default null,subject uuid default null,role text default null,
 project_ref text default null,project_title text default null,permissions text[] default null,revision bigint default null,
 reason text default null,detail text default null) returns jsonb language sql security invoker set search_path='' as $$
 select sdi_private.room_manage(action,room,subject,role,project_ref,project_title,permissions,revision,reason,detail)$$;
revoke all on function public.sdi_room_manage(text,uuid,uuid,text,text,text,text[],bigint,text,text) from public,anon;
grant execute on function public.sdi_room_manage(text,uuid,uuid,text,text,text,text[],bigint,text,text) to authenticated;

create function sdi_private.room_command(action text,room uuid default null,op_id uuid default null,base_revision bigint default null,
 kind text default null,payload jsonb default null,after bigint default 0,page_size integer default 200) returns jsonb
language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare actor uuid:=auth.uid(); target public.sdi_rooms; n integer; existing bigint; items jsonb;
begin
 if actor is null or not sdi_private.account_active() then return jsonb_build_object('error','Sign in with a full account.'); end if;
 insert into sdi_private.room_command_budget values(actor,clock_timestamp(),1)
 on conflict(user_id) do update set
 attempts=case when room_command_budget.window_start<clock_timestamp()-interval '1 minute' then 1 else room_command_budget.attempts+1 end,
 window_start=case when room_command_budget.window_start<clock_timestamp()-interval '1 minute' then clock_timestamp() else room_command_budget.window_start end
 returning attempts into n;
 if n>300 then return jsonb_build_object('error','Too many edits per minute. Pause and resynchronize.'); end if;
 if action='since' then
  if not sdi_private.room_access(room) then return jsonb_build_object('error','Room is unavailable.'); end if;
  select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into items from (
   select revision,op_id,author,base_revision,kind,payload,created_at from sdi_private.room_commands
   where room_id=room and revision>coalesce(after,0) order by revision limit least(greatest(coalesce(page_size,200),1),500)
  ) item;
  return jsonb_build_object('commands',items,'head',(select command_revision from public.sdi_rooms where id=room));
 end if;
 if action<>'append' then return jsonb_build_object('error','Unsupported command operation.'); end if;
 if not sdi_private.room_can_edit(room) then return jsonb_build_object('error','You can view this project but not edit it.'); end if;
 if op_id is null or base_revision is null or kind is null or length(kind) not between 1 and 64 or payload is null or jsonb_typeof(payload)<>'object'
  or octet_length(payload::text)>65536 then return jsonb_build_object('error','A command id, base revision, kind and bounded payload are required.'); end if;
 select * into target from public.sdi_rooms where id=room and not closed for update;
 if not found then return jsonb_build_object('error','Room is unavailable.'); end if;
 select revision into existing from sdi_private.room_commands where room_id=target.id and op_id=room_command.op_id;
 if existing is not null then return jsonb_build_object('status','duplicate','revision',existing,'head',target.command_revision); end if;
 if base_revision<>target.command_revision then
  select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into items from (
   select revision,op_id,author,base_revision,kind,payload,created_at from sdi_private.room_commands
   where room_id=target.id and revision>base_revision order by revision limit 200
  ) item;
  return jsonb_build_object('error','conflict','head',target.command_revision,'missing',items);
 end if;
 if target.command_revision>=100000 then return jsonb_build_object('error','This room reached its edit history limit. Start a new shared project.'); end if;
 insert into sdi_private.room_commands(room_id,revision,op_id,author,base_revision,kind,payload)
 values(target.id,target.command_revision+1,op_id,actor,base_revision,kind,payload);
 update public.sdi_rooms set command_revision=command_revision+1 where id=target.id;
 return jsonb_build_object('status','applied','revision',target.command_revision+1);
end $$;
revoke all on function sdi_private.room_command(text,uuid,uuid,bigint,text,jsonb,bigint,integer) from public,anon;
grant execute on function sdi_private.room_command(text,uuid,uuid,bigint,text,jsonb,bigint,integer) to authenticated;
create function public.sdi_room_command(action text,room uuid default null,op_id uuid default null,base_revision bigint default null,
 kind text default null,payload jsonb default null,after bigint default 0,page_size integer default 200) returns jsonb
language sql security invoker set search_path='' as $$select sdi_private.room_command(action,room,op_id,base_revision,kind,payload,after,page_size)$$;
revoke all on function public.sdi_room_command(text,uuid,uuid,bigint,text,jsonb,bigint,integer) from public,anon;
grant execute on function public.sdi_room_command(text,uuid,uuid,bigint,text,jsonb,bigint,integer) to authenticated;

-- Admin queue for room reports. Closing a room ends access for everyone; it never
-- deletes anyone's on-device project. Reporter identity is not returned.
create function sdi_private.room_moderate(action text,report uuid default null,revision bigint default null,reason text default '') returns jsonb
language plpgsql security definer set search_path='' as $$
declare r sdi_private.room_reports; target public.sdi_rooms; items jsonb;
begin
 if not sdi_private.admin_can('moderation') or not sdi_private.account_active() then return jsonb_build_object('error','Current admin MFA session required.');end if;
 if action='list' then
  select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into items from (
   select rp.id,rp.room_id,rp.reason,rp.detail,rp.revision,rp.created_at,room.title,room.owner_id,room.closed,
    (select count(*) from public.sdi_room_members m where m.room_id=room.id and m.owner_approved and not m.revoked) as members,
    (select count(*) from sdi_private.room_reports o where o.room_id=room.id) as report_count
   from sdi_private.room_reports rp join public.sdi_rooms room on room.id=rp.room_id where rp.state='pending' order by rp.created_at,rp.id limit 50
  ) item;
  return jsonb_build_object('reports',items);
 end if;
 if action is null or action not in('dismiss','close') or report is null or revision is null or reason is null or length(trim(reason)) not between 1 and 2000 then
  return jsonb_build_object('error','A current report and decision reason are required.');end if;
 select * into r from sdi_private.room_reports where id=report for update;
 if not found or r.state<>'pending' or r.revision<>revision then return jsonb_build_object('error','Report changed. Refresh the queue.');end if;
 select * into target from public.sdi_rooms where id=r.room_id for update;
 if auth.uid() in(target.owner_id,r.reporter) then return jsonb_build_object('error','An uninvolved administrator must decide.');end if;
 if action='close' then
  update public.sdi_rooms set closed=true where id=target.id;
  update sdi_private.room_invites set revoked=true where room_id=target.id;
  update sdi_private.room_reports set state='closed',revision=room_reports.revision+1 where room_id=target.id and state='pending';
 else
  update sdi_private.room_reports set state='dismissed',revision=room_reports.revision+1 where id=r.id;
 end if;
 insert into sdi_private.room_moderation_audit(report_id,room_id,actor,decision,reason) values(r.id,target.id,auth.uid(),action,trim(reason));
 return jsonb_build_object('status','confirmed');
end $$;
revoke all on function sdi_private.room_moderate(text,uuid,bigint,text) from public,anon;
grant execute on function sdi_private.room_moderate(text,uuid,bigint,text) to authenticated;
create function public.sdi_room_moderate(action text,report uuid default null,revision bigint default null,reason text default '') returns jsonb
language sql security invoker set search_path='' as $$select sdi_private.room_moderate(action,report,revision,reason)$$;
revoke all on function public.sdi_room_moderate(text,uuid,bigint,text) from public,anon;
grant execute on function public.sdi_room_moderate(text,uuid,bigint,text) to authenticated;

-- Problem 9: creators can appeal a feed removal; an uninvolved administrator decides.
-- Acceptance restores the exact removed digest only while its hosted copy still
-- exists; once removed, the creator resubmits through the normal review path.
alter table sdi_private.moderation_appeals add column render_digest text;
alter table sdi_private.moderation_appeals add column reviewer uuid references auth.users(id);
alter table sdi_private.moderation_appeals add column reply text check(length(reply)<=2000);
alter table sdi_private.moderation_appeals add column decided_at timestamptz;
alter table sdi_private.moderation_appeals add column revision bigint not null default 1;
create unique index moderation_appeals_one_pending on sdi_private.moderation_appeals(media_id) where state='pending';
alter table sdi_private.removal_jobs drop constraint removal_jobs_state_check;
alter table sdi_private.removal_jobs add constraint removal_jobs_state_check check(state in('pending','running','complete','failed','withdrawn'));
create function sdi_private.moderation_appeal(action text,media uuid default null,explanation text default '',appeal uuid default null,
 revision bigint default null,note text default '') returns jsonb
language plpgsql security definer set search_path='' as $$
declare actor_id uuid:=auth.uid(); m public.sdi_watch_media; a sdi_private.moderation_appeals; removal sdi_private.moderation_audit; items jsonb;
begin
 if actor_id is null or not exists(select 1 from auth.users where id=actor_id and not is_anonymous)
 or not exists(select 1 from auth.sessions where user_id=actor_id and id::text=auth.jwt()->>'session_id') then
  return jsonb_build_object('error','A current signed-in account is required.');end if;
 if action in('mine','submit') then
  if action='submit' then
   if media is null or explanation is null or length(trim(explanation)) not between 1 and 2000 then
    return jsonb_build_object('error','Select your removed video and explain your appeal.');end if;
   select * into m from public.sdi_watch_media where id=media and owner_id=actor_id for update;
   select d.* into removal from sdi_private.moderation_audit d where d.media_id=media and d.action='remove' order by d.created_at desc limit 1;
   if not found or m.id is null or m.approved or removal.created_at<clock_timestamp()-interval '30 days' then
    return jsonb_build_object('error','No removal of your video is open for appeal.');end if;
   if exists(select 1 from sdi_private.moderation_appeals where media_id=media and state='pending') then return jsonb_build_object('status','recorded');end if;
   if (select count(*) from sdi_private.moderation_appeals where creator=actor_id and created_at>clock_timestamp()-interval '1 day')>=3 then
    return jsonb_build_object('error','Daily appeal limit reached.');end if;
   insert into sdi_private.moderation_appeals(media_id,creator,explanation,render_digest) values(media,actor_id,trim(explanation),removal.render_digest);
  end if;
  select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into items from (
   select ap.id,ap.media_id,v.title,ap.explanation,ap.state,ap.reply,ap.created_at,ap.decided_at from sdi_private.moderation_appeals ap
   join public.sdi_watch_media v on v.id=ap.media_id where ap.creator=actor_id order by ap.created_at desc,ap.id limit 50
  ) item;
  return jsonb_build_object('appeals',items);
 end if;
 if not sdi_private.admin_can('moderation') or not sdi_private.account_active() then return jsonb_build_object('error','Current admin MFA session required.');end if;
 if action='queue' then
  select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into items from (
   select ap.id,ap.media_id,ap.creator,ap.explanation,ap.render_digest,ap.revision,ap.created_at,v.title,v.url,
    (select d.reason from sdi_private.moderation_audit d where d.media_id=ap.media_id and d.action='remove' order by d.created_at desc limit 1) as removal_reason,
    (select j.state from sdi_private.removal_jobs j where j.media_id=ap.media_id and j.render_digest=ap.render_digest) as removal_state
   from sdi_private.moderation_appeals ap join public.sdi_watch_media v on v.id=ap.media_id where ap.state='pending' order by ap.created_at,ap.id limit 50
  ) item;
  return jsonb_build_object('appeals',items);
 end if;
 if action is null or action not in('accept','reject') or appeal is null or revision is null or note is null or length(trim(note)) not between 1 and 2000 then
  return jsonb_build_object('error','Select an appeal and provide a member-visible decision reason.');end if;
 select * into a from sdi_private.moderation_appeals where id=appeal for update;
 if not found or a.state<>'pending' or a.revision<>revision then return jsonb_build_object('error','Appeal changed. Refresh the queue.');end if;
 select * into m from public.sdi_watch_media where id=a.media_id for update;
 if actor_id=a.creator or exists(select 1 from sdi_private.moderation_audit d where d.media_id=a.media_id and d.actor=actor_id) then
  return jsonb_build_object('error','Another uninvolved administrator must review this appeal.');end if;
 if action='accept' then
  if m.render_digest is distinct from a.render_digest or m.approved then return jsonb_build_object('error','The removed render changed; nothing to restore.');end if;
  if not exists(select 1 from sdi_private.removal_jobs where media_id=m.id and render_digest=a.render_digest and state in('pending','failed')) then
   return jsonb_build_object('error','The hosted copy is already removed. The creator can resubmit the render for review.');end if;
  update sdi_private.removal_jobs set state='withdrawn' where media_id=m.id and render_digest=a.render_digest and state in('pending','failed');
  update public.sdi_watch_media set approved=true where id=m.id;
  update sdi_private.feed_posts set visible=true where media_id=m.id;
 end if;
 update sdi_private.moderation_appeals set state=case action when 'accept' then 'accepted' else 'rejected' end,reviewer=actor_id,
  reply=trim(note),decided_at=clock_timestamp(),revision=moderation_appeals.revision+1 where id=a.id;
 insert into sdi_private.moderation_audit(report_id,actor,action,reason,media_id,render_digest)
 values(a.id,actor_id,'appeal_'||action,trim(note),m.id,coalesce(a.render_digest,m.render_digest,''));
 return jsonb_build_object('status','confirmed');
end $$;
revoke all on function sdi_private.moderation_appeal(text,uuid,text,uuid,bigint,text) from public,anon;
grant execute on function sdi_private.moderation_appeal(text,uuid,text,uuid,bigint,text) to authenticated;
create function public.sdi_moderation_appeal(action text,media uuid default null,explanation text default '',appeal uuid default null,
 revision bigint default null,note text default '') returns jsonb language sql security invoker set search_path='' as $$
 select sdi_private.moderation_appeal(action,media,explanation,appeal,revision,note)$$;
revoke all on function public.sdi_moderation_appeal(text,uuid,text,uuid,bigint,text) from public,anon;
grant execute on function public.sdi_moderation_appeal(text,uuid,text,uuid,bigint,text) to authenticated;
commit;

-- Rooms v2.1 (#232, #233). Server-side rebase of concurrent commands, undo
-- ownership, and bounded transfer of explicitly shared assets. Still no chat,
-- calls, camera, microphone, screen or background harvesting: an asset exists
-- here only because an editor chose that file, and it is a temporary transfer
-- copy. The sender's local original is never touched by anything below.
begin;
-- Optional entity a command edits ("frame:<id>", "layer:<id>", "audio:<id>").
-- Commands without a target are treated as touching the whole document.
alter table sdi_private.room_commands add column target text check(target is null or length(target) between 1 and 200);
alter table sdi_private.room_commands add column undoes uuid;
create unique index room_commands_one_undo on sdi_private.room_commands(room_id,undoes) where undoes is not null;

create or replace function sdi_private.room_command(action text,room uuid default null,op_id uuid default null,base_revision bigint default null,
 kind text default null,payload jsonb default null,after bigint default 0,page_size integer default 200) returns jsonb
language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare actor uuid:=auth.uid(); target public.sdi_rooms; n integer; existing bigint; items jsonb; overlap jsonb;
 entity text; undone sdi_private.room_commands; undo_ref uuid;
begin
 if actor is null or not sdi_private.account_active() then return jsonb_build_object('error','Sign in with a full account.'); end if;
 insert into sdi_private.room_command_budget values(actor,clock_timestamp(),1)
 on conflict(user_id) do update set
 attempts=case when room_command_budget.window_start<clock_timestamp()-interval '1 minute' then 1 else room_command_budget.attempts+1 end,
 window_start=case when room_command_budget.window_start<clock_timestamp()-interval '1 minute' then clock_timestamp() else room_command_budget.window_start end
 returning attempts into n;
 if n>300 then return jsonb_build_object('error','Too many edits per minute. Pause and resynchronize.'); end if;
 if action='since' then
  if not sdi_private.room_access(room) then return jsonb_build_object('error','Room is unavailable.'); end if;
  select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into items from (
   select revision,op_id,author,base_revision,kind,payload,target,undoes,created_at from sdi_private.room_commands
   where room_id=room and revision>coalesce(after,0) order by revision limit least(greatest(coalesce(page_size,200),1),500)
  ) item;
  return jsonb_build_object('commands',items,'head',(select command_revision from public.sdi_rooms where id=room));
 end if;
 if action<>'append' then return jsonb_build_object('error','Unsupported command operation.'); end if;
 if not sdi_private.room_can_edit(room) then return jsonb_build_object('error','You can view this project but not edit it.'); end if;
 if op_id is null or base_revision is null or base_revision<0 or kind is null or length(kind) not between 1 and 64 or payload is null
  or jsonb_typeof(payload)<>'object' or octet_length(payload::text)>65536
  or (payload ? 'target' and (jsonb_typeof(payload->'target')<>'string' or length(payload->>'target') not between 1 and 200)) then
  return jsonb_build_object('error','A command id, base revision, kind and bounded payload are required.'); end if;
 select * into target from public.sdi_rooms where id=room and not closed for update;
 if not found then return jsonb_build_object('error','Room is unavailable.'); end if;
 select revision into existing from sdi_private.room_commands where room_id=target.id and op_id=room_command.op_id;
 if existing is not null then return jsonb_build_object('status','duplicate','revision',existing,'head',target.command_revision); end if;
 if base_revision>target.command_revision then return jsonb_build_object('error','Base revision is ahead of the room. Resynchronize.'); end if;
 entity:=payload->>'target';
 -- Undo ownership: a creator may undo only their own command, once.
 if kind='undo' then
  if coalesce(payload->>'undo_op','') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then
   return jsonb_build_object('error','Undo needs the operation id it reverses.'); end if;
  undo_ref:=(payload->>'undo_op')::uuid;
  select * into undone from sdi_private.room_commands c where c.room_id=target.id and c.op_id=undo_ref;
  if not found then return jsonb_build_object('error','That edit is not in this room.'); end if;
  if undone.author<>actor then return jsonb_build_object('error','You can undo only your own edits.'); end if;
  if undone.kind='undo' then return jsonb_build_object('error','Redo is a new edit, not an undo of an undo.'); end if;
  if exists(select 1 from sdi_private.room_commands c where c.room_id=target.id and c.undoes=undo_ref) then
   return jsonb_build_object('error','That edit was already undone.'); end if;
  entity:=undone.target;
 end if;
 if base_revision<target.command_revision then
  select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into items from (
   select revision,op_id,author,base_revision,kind,payload,target,undoes,created_at from sdi_private.room_commands
   where room_id=target.id and revision>base_revision order by revision limit 200
  ) item;
  -- Rebase only when the edit names its entity, the gap is small enough to
  -- return in full, and no intervening command touched that entity (or the
  -- whole document). Anything else is an explicit conflict, never an overwrite.
  select coalesce(jsonb_agg(c.op_id order by c.revision),'[]'::jsonb) into overlap from sdi_private.room_commands c
   where c.room_id=target.id and c.revision>base_revision and (c.target is null or entity is null or c.target=entity);
  if entity is null or target.command_revision-base_revision>200 or jsonb_array_length(overlap)>0 then
   return jsonb_build_object('error','conflict','head',target.command_revision,'missing',items,'overlap',overlap);
  end if;
 end if;
 if target.command_revision>=100000 then return jsonb_build_object('error','This room reached its edit history limit. Start a new shared project.'); end if;
 insert into sdi_private.room_commands(room_id,revision,op_id,author,base_revision,kind,payload,target,undoes)
 values(target.id,target.command_revision+1,op_id,actor,base_revision,kind,payload,entity,case when kind='undo' then undo_ref end);
 update public.sdi_rooms set command_revision=command_revision+1 where id=target.id;
 if base_revision<target.command_revision then
  return jsonb_build_object('status','rebased','revision',target.command_revision+1,'head',target.command_revision+1,'missing',items);
 end if;
 return jsonb_build_object('status','applied','revision',target.command_revision+1);
end $$;

-- Bounded asset transfer (#233). Files move in 32 KiB chunks through this
-- operation boundary; the server recomputes the SHA-256 of the whole file
-- before anyone can download it, and every copy expires. Quotas: 8 MiB per
-- file, 64 MiB and 100 files live per room, 30 files per sender per day,
-- 600 transfer calls per minute per account.
create table sdi_private.room_assets (
 id uuid primary key default gen_random_uuid(),
 room_id uuid not null references public.sdi_rooms(id) on delete cascade,
 uploader uuid not null references auth.users(id) on delete cascade,
 project_ref text not null,
 name text not null check(length(name) between 1 and 120),
 mime text not null check(mime in('image/png','image/jpeg','audio/mp4','audio/mpeg','audio/wav','audio/x-caf')),
 byte_size integer not null check(byte_size between 1 and 8388608),
 chunk_count integer not null check(chunk_count between 1 and 256),
 sha256 text not null check(sha256 ~ '^[a-f0-9]{64}$'),
 license text not null check(license in('own-work','cc0','cc-by','licensed-library')),
 attribution text not null default '' check(length(attribution)<=500),
 state text not null default 'receiving' check(state in('receiving','available','deleted')),
 end_reason text check(end_reason in('rejected','withdrawn','expired','room_closed','membership_ended')),
 problem text check(length(problem)<=500),
 created_at timestamptz not null default clock_timestamp(),
 expires_at timestamptz not null,
 deleted_at timestamptz,
 delete_verified boolean not null default false,
 check((state='deleted')=(end_reason is not null)),
 check(license<>'cc-by' or length(trim(attribution))>0)
);
create unique index room_assets_one_live_copy on sdi_private.room_assets(room_id,sha256) where state<>'deleted';
create table sdi_private.room_asset_chunks (
 asset_id uuid not null references sdi_private.room_assets(id) on delete cascade,
 idx integer not null check(idx between 0 and 255),
 data bytea not null check(octet_length(data) between 1 and 32768),
 primary key(asset_id,idx)
);
create table sdi_private.room_asset_budget (
 user_id uuid primary key references auth.users(id) on delete cascade, window_start timestamptz not null, attempts integer not null
);
-- Cleanup evidence: how many chunks were removed and whether none remain.
create table sdi_private.room_asset_cleanup_audit (
 id uuid primary key default gen_random_uuid(), asset_id uuid not null, room_id uuid not null,
 reason text not null, chunks_removed integer not null, verified boolean not null,
 created_at timestamptz not null default clock_timestamp()
);
alter table sdi_private.room_assets enable row level security;
alter table sdi_private.room_asset_chunks enable row level security;
alter table sdi_private.room_asset_budget enable row level security;
alter table sdi_private.room_asset_cleanup_audit enable row level security;
revoke all on sdi_private.room_assets,sdi_private.room_asset_chunks,sdi_private.room_asset_budget,sdi_private.room_asset_cleanup_audit
 from public,anon,authenticated;

-- Whether a given user (not necessarily the caller) still belongs to an open room.
create function sdi_private.room_member_active(r uuid,u uuid) returns boolean
language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.sdi_rooms room where room.id=r and not room.closed and (room.owner_id=u or exists(
  select 1 from public.sdi_room_members m where m.room_id=r and m.user_id=u and m.owner_approved and m.member_accepted and not m.revoked)))
$$;
revoke all on function sdi_private.room_member_active(uuid,uuid) from public,anon,authenticated;

-- Delete a transfer copy's bytes and record verified evidence. Never touches
-- anything on a device.
create function sdi_private.room_asset_discard(asset uuid,reason text,note text default null) returns boolean
language plpgsql security definer set search_path='' as $$
declare removed integer; remaining boolean; a sdi_private.room_assets;
begin
 select * into a from sdi_private.room_assets where id=asset for update;
 if not found or a.state='deleted' then return false; end if;
 delete from sdi_private.room_asset_chunks where asset_id=asset;
 get diagnostics removed=row_count;
 remaining:=exists(select 1 from sdi_private.room_asset_chunks where asset_id=asset);
 update sdi_private.room_assets set state='deleted',end_reason=reason,problem=coalesce(note,problem),deleted_at=clock_timestamp(),
  delete_verified=not remaining where id=asset;
 insert into sdi_private.room_asset_cleanup_audit(asset_id,room_id,reason,chunks_removed,verified) values(asset,a.room_id,reason,removed,not remaining);
 return not remaining;
end $$;
revoke all on function sdi_private.room_asset_discard(uuid,text,text) from public,anon,authenticated;

create function sdi_private.room_asset(action text,room uuid default null,asset uuid default null,name text default null,
 mime text default null,byte_size bigint default null,sha256 text default null,license text default null,attribution text default '',
 chunk_index integer default null,data text default null) returns jsonb
language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare actor uuid:=auth.uid(); target public.sdi_rooms; a sdi_private.room_assets; n integer; items jsonb; raw bytea;
 expected integer; chunk_size constant integer:=32768; created uuid; whole bytea; chunks integer;
begin
 if actor is null or not sdi_private.account_active() or not exists(select 1 from auth.users where id=actor and not is_anonymous) then
  return jsonb_build_object('error','Sign in with a full account.'); end if;
 insert into sdi_private.room_asset_budget values(actor,clock_timestamp(),1)
 on conflict(user_id) do update set
 attempts=case when room_asset_budget.window_start<clock_timestamp()-interval '1 minute' then 1 else room_asset_budget.attempts+1 end,
 window_start=case when room_asset_budget.window_start<clock_timestamp()-interval '1 minute' then clock_timestamp() else room_asset_budget.window_start end
 returning attempts into n;
 if n>600 then return jsonb_build_object('error','Too many transfer requests. Wait a minute.'); end if;
 if room is null or not sdi_private.room_access(room) then return jsonb_build_object('error','Room is unavailable.'); end if;
 select * into target from public.sdi_rooms where id=room and not closed;
 if action='list' then
  select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into items from (
   select x.id as asset_id,x.name,x.mime,x.byte_size,x.chunk_count,x.sha256,x.license,x.attribution,x.state,x.expires_at,x.created_at,
    x.uploader=actor as mine,(select count(*) from sdi_private.room_asset_chunks c where c.asset_id=x.id) as received
   from sdi_private.room_assets x where x.room_id=target.id and x.expires_at>clock_timestamp()
    and (x.state='available' or (x.state='receiving' and x.uploader=actor))
    and sdi_private.room_member_active(target.id,x.uploader)
   order by x.created_at desc,x.id limit 100
  ) item;
  return jsonb_build_object('assets',items,'chunk_size',chunk_size);
 end if;
 if action='declare' then
  if target.project_ref is null then return jsonb_build_object('error','Share a project in this room before sending assets.'); end if;
  if not sdi_private.room_can_edit(target.id) then return jsonb_build_object('error','Only editors can share assets in this room.'); end if;
  if name is null or length(trim(name)) not between 1 and 120 or mime is null
   or mime not in('image/png','image/jpeg','audio/mp4','audio/mpeg','audio/wav','audio/x-caf')
   or byte_size is null or byte_size not between 1 and 8388608 or sha256 is null or sha256 !~ '^[a-f0-9]{64}$'
   or license is null or license not in('own-work','cc0','cc-by','licensed-library') or attribution is null or length(attribution)>500
   or (license='cc-by' and length(trim(attribution))=0) then
   return jsonb_build_object('error','A named PNG, JPEG or audio file up to 8 MB, its SHA-256 and its licence are required.'); end if;
  select * into a from sdi_private.room_assets x where x.room_id=target.id and x.sha256=room_asset.sha256 and x.state<>'deleted' for update;
  if found then
   if a.expires_at>clock_timestamp() and sdi_private.room_member_active(target.id,a.uploader) then
    if a.state='receiving' and a.uploader<>actor then return jsonb_build_object('error','Another member is already sending this file.'); end if;
    return jsonb_build_object('status','existing','asset_id',a.id,'state',a.state,'chunk_size',chunk_size,'chunk_count',a.chunk_count,'expires_at',a.expires_at);
   end if;
   perform sdi_private.room_asset_discard(a.id,case when sdi_private.room_member_active(target.id,a.uploader) then 'expired' else 'membership_ended' end);
  end if;
  if (select count(*) from sdi_private.room_assets x where x.uploader=actor and x.created_at>clock_timestamp()-interval '1 day')>=30 then
   return jsonb_build_object('error','Daily asset transfer limit reached.'); end if;
  if (select count(*) from sdi_private.room_assets x where x.room_id=target.id and x.state<>'deleted')>=100
   or (select coalesce(sum(x.byte_size),0) from sdi_private.room_assets x where x.room_id=target.id and x.state<>'deleted')+byte_size>67108864 then
   return jsonb_build_object('error','This room reached its transfer quota. Withdraw older assets first.'); end if;
  chunks:=((byte_size+chunk_size-1)/chunk_size)::integer;
  insert into sdi_private.room_assets(room_id,uploader,project_ref,name,mime,byte_size,chunk_count,sha256,license,attribution,expires_at)
  values(target.id,actor,target.project_ref,trim(name),mime,byte_size,chunks,sha256,license,trim(attribution),clock_timestamp()+interval '1 hour')
  returning id into created;
  return jsonb_build_object('status','declared','asset_id',created,'state','receiving','chunk_size',chunk_size,'chunk_count',chunks,
   'expires_at',(select expires_at from sdi_private.room_assets where id=created));
 end if;
 select * into a from sdi_private.room_assets x where x.id=asset and x.room_id=target.id for update;
 if not found or a.state='deleted' or a.expires_at<=clock_timestamp() then return jsonb_build_object('error','Asset is unavailable.'); end if;
 if action='status' then
  if a.uploader<>actor and a.state<>'available' then return jsonb_build_object('error','Asset is unavailable.'); end if;
  return jsonb_build_object('asset_id',a.id,'state',a.state,'chunk_count',a.chunk_count,'expires_at',a.expires_at,
   'received',(select coalesce(jsonb_agg(c.idx order by c.idx),'[]'::jsonb) from sdi_private.room_asset_chunks c where c.asset_id=a.id));
 elsif action='put' then
  if a.uploader<>actor or a.state<>'receiving' then return jsonb_build_object('error','Asset is unavailable.'); end if;
  if not sdi_private.room_can_edit(target.id) then return jsonb_build_object('error','Only editors can share assets in this room.'); end if;
  if chunk_index is null or chunk_index<0 or chunk_index>=a.chunk_count or data is null or length(data)>45000 then
   return jsonb_build_object('error','Chunk index or size is invalid.'); end if;
  begin raw:=decode(data,'base64'); exception when others then return jsonb_build_object('error','Chunk is not valid base64.'); end;
  expected:=case when chunk_index=a.chunk_count-1 then a.byte_size-chunk_index*chunk_size else chunk_size end;
  if octet_length(raw)<>expected then return jsonb_build_object('error','Chunk length does not match the declared file size.'); end if;
  insert into sdi_private.room_asset_chunks(asset_id,idx,data) values(a.id,chunk_index,raw)
  on conflict(asset_id,idx) do update set data=excluded.data;
  return jsonb_build_object('status','stored','received',(select count(*) from sdi_private.room_asset_chunks c where c.asset_id=a.id));
 elsif action='finalize' then
  if a.uploader<>actor or a.state<>'receiving' then return jsonb_build_object('error','Asset is unavailable.'); end if;
  if (select count(*) from sdi_private.room_asset_chunks c where c.asset_id=a.id)<>a.chunk_count then
   return jsonb_build_object('error','incomplete','received',(select coalesce(jsonb_agg(c.idx order by c.idx),'[]'::jsonb) from sdi_private.room_asset_chunks c where c.asset_id=a.id));
  end if;
  select string_agg(c.data,''::bytea order by c.idx) into whole from sdi_private.room_asset_chunks c where c.asset_id=a.id;
  if octet_length(whole)<>a.byte_size or encode(extensions.digest(whole,'sha256'),'hex')<>a.sha256 then
   perform sdi_private.room_asset_discard(a.id,'rejected','Received bytes did not match the declared SHA-256; the copy was discarded.');
   return jsonb_build_object('error','The transferred file was corrupt and has been discarded. Send it again.');
  end if;
  update sdi_private.room_assets set state='available',expires_at=clock_timestamp()+interval '72 hours' where id=a.id;
  return jsonb_build_object('status','available','asset_id',a.id,'expires_at',(select expires_at from sdi_private.room_assets where id=a.id));
 elsif action='get' then
  if a.state<>'available' or not sdi_private.room_member_active(target.id,a.uploader) then return jsonb_build_object('error','Asset is unavailable.'); end if;
  if chunk_index is null or chunk_index<0 or chunk_index>=a.chunk_count then return jsonb_build_object('error','Chunk index is invalid.'); end if;
  return jsonb_build_object('asset_id',a.id,'chunk_index',chunk_index,'chunk_count',a.chunk_count,'sha256',a.sha256,
   'data',(select encode(c.data,'base64') from sdi_private.room_asset_chunks c where c.asset_id=a.id and c.idx=chunk_index));
 elsif action='withdraw' then
  if a.uploader<>actor and target.owner_id<>actor then return jsonb_build_object('error','Only the sender or the room owner can withdraw an asset.'); end if;
  return jsonb_build_object('status','withdrawn','verified',sdi_private.room_asset_discard(a.id,'withdrawn'));
 end if;
 return jsonb_build_object('error','Unsupported asset operation.');
end $$;
revoke all on function sdi_private.room_asset(text,uuid,uuid,text,text,bigint,text,text,text,integer,text) from public,anon;
grant execute on function sdi_private.room_asset(text,uuid,uuid,text,text,bigint,text,text,text,integer,text) to authenticated;
create function public.sdi_room_asset(action text,room uuid default null,asset uuid default null,name text default null,
 mime text default null,byte_size bigint default null,sha256 text default null,license text default null,attribution text default '',
 chunk_index integer default null,data text default null) returns jsonb language sql security invoker set search_path='' as $$
 select sdi_private.room_asset(action,room,asset,name,mime,byte_size,sha256,license,attribution,chunk_index,data)$$;
revoke all on function public.sdi_room_asset(text,uuid,uuid,text,text,bigint,text,text,text,integer,text) from public,anon;
grant execute on function public.sdi_room_asset(text,uuid,uuid,text,text,bigint,text,text,text,integer,text) to authenticated;

-- Scheduled cleanup (service role only): expired copies, closed rooms and
-- senders whose membership ended. Returns verified counts for the run log.
create function sdi_private.room_asset_sweep(max_items integer default 200) returns jsonb
language plpgsql security definer set search_path='' as $$
declare item record; done integer:=0; verified integer:=0;
begin
 for item in
  select x.id,case when room.closed then 'room_closed'
   when not sdi_private.room_member_active(x.room_id,x.uploader) then 'membership_ended' else 'expired' end as reason
  from sdi_private.room_assets x join public.sdi_rooms room on room.id=x.room_id
  where x.state<>'deleted' and (x.expires_at<=clock_timestamp() or room.closed or not sdi_private.room_member_active(x.room_id,x.uploader))
  order by x.expires_at limit least(greatest(coalesce(max_items,200),1),1000)
 loop
  done:=done+1;
  if sdi_private.room_asset_discard(item.id,item.reason) then verified:=verified+1; end if;
 end loop;
 return jsonb_build_object('discarded',done,'verified',verified,
  'unverified_total',(select count(*) from sdi_private.room_assets where state='deleted' and not delete_verified));
end $$;
revoke all on function sdi_private.room_asset_sweep(integer) from public,anon,authenticated;
grant execute on function sdi_private.room_asset_sweep(integer) to service_role;
create function public.sdi_room_asset_sweep(max_items integer default 200) returns jsonb
language sql security invoker set search_path='' as $$select sdi_private.room_asset_sweep(max_items)$$;
revoke all on function public.sdi_room_asset_sweep(integer) from public,anon,authenticated;
grant execute on function public.sdi_room_asset_sweep(integer) to service_role;
commit;

-- ===== challenges.sql (sha256 98ab811c7c89c120) =====
-- Unapplied candidate. Install after rooms-v2.sql (needs war-room.sql, feed-integrity.sql,
-- admin-approval.sql and admin-users.sql). Challenges reuse the War Room rules: only
-- the creator's own approved rendition with an immutable digest may be entered, one
-- entry per creator, one mutable favorite vote per nonparticipant, server times decide
-- Upcoming/Active/Voting/Completed. reward_text is a configured real reward description
-- or empty; nothing here creates coins, prizes or money.
begin;
create table sdi_private.challenges (
 id uuid primary key default gen_random_uuid(), title text not null check(length(title) between 1 and 100),
 brief text not null default '' check(length(brief)<=2000), reward_text text not null default '' check(length(reward_text)<=500),
 created_by uuid not null references auth.users(id), state text not null default 'draft' check(state in('draft','scheduled','cancelled')),
 starts_at timestamptz, submissions_close_at timestamptz, voting_ends_at timestamptz,
 revision bigint not null default 1, created_at timestamptz not null default clock_timestamp(),
 check(starts_at is null or (submissions_close_at>starts_at and voting_ends_at>submissions_close_at))
);
create table sdi_private.challenge_entries (
 id uuid primary key default gen_random_uuid(), challenge_id uuid not null references sdi_private.challenges(id),
 creator uuid not null references auth.users(id) on delete cascade, media_id uuid not null references public.sdi_watch_media(id),
 render_digest text not null, withdrawn boolean not null default false, created_at timestamptz not null default clock_timestamp(),
 unique(challenge_id,creator)
);
create table sdi_private.challenge_votes (
 challenge_id uuid not null references sdi_private.challenges(id), voter uuid not null references auth.users(id) on delete cascade,
 entry_id uuid not null references sdi_private.challenge_entries(id) on delete cascade, created_at timestamptz not null default clock_timestamp(),
 primary key(challenge_id,voter)
);
create table sdi_private.challenge_results (
 challenge_id uuid primary key references sdi_private.challenges(id), finalized_at timestamptz not null default clock_timestamp(),
 tally jsonb not null, winner_entry uuid references sdi_private.challenge_entries(id),
 outcome text not null check(outcome in('winner','tie','no_entries'))
);
create table sdi_private.challenge_audit (
 id uuid primary key default gen_random_uuid(), challenge_id uuid not null references sdi_private.challenges(id),
 actor uuid not null references auth.users(id), action text not null, reason text not null check(length(reason)<=2000),
 created_at timestamptz not null default clock_timestamp()
);
create table sdi_private.challenge_budget (
 user_id uuid primary key references auth.users(id) on delete cascade, starts_at timestamptz not null, attempts integer not null
);
alter table sdi_private.challenges enable row level security;
alter table sdi_private.challenge_entries enable row level security;
alter table sdi_private.challenge_votes enable row level security;
alter table sdi_private.challenge_results enable row level security;
alter table sdi_private.challenge_audit enable row level security;
alter table sdi_private.challenge_budget enable row level security;
revoke all on sdi_private.challenges,sdi_private.challenge_entries,sdi_private.challenge_votes,sdi_private.challenge_results,sdi_private.challenge_audit,sdi_private.challenge_budget from public,anon,authenticated;
create function sdi_private.challenge_phase(c sdi_private.challenges) returns text language sql stable set search_path='' as $$
 select case when c.state='cancelled' then 'cancelled' when c.state='draft' or c.starts_at is null then 'draft'
  when clock_timestamp()<c.starts_at then 'upcoming' when clock_timestamp()<c.submissions_close_at then 'active'
  when clock_timestamp()<c.voting_ends_at then 'voting' else 'completed' end
$$;
revoke all on function sdi_private.challenge_phase(sdi_private.challenges) from public,anon;
grant execute on function sdi_private.challenge_phase(sdi_private.challenges) to authenticated,service_role;
-- An entry counts only while its exact approved rendition is still available.
create function sdi_private.challenge_entry_live(e sdi_private.challenge_entries) returns boolean language sql stable security definer set search_path='' as $$
 select not e.withdrawn and not sdi_private.creator_restricted(e.creator) and exists(select 1 from public.sdi_watch_media m
  where m.id=e.media_id and m.approved and m.owner_id=e.creator and m.render_digest=e.render_digest and (m.expires_at is null or m.expires_at>clock_timestamp()))
$$;
revoke all on function sdi_private.challenge_entry_live(sdi_private.challenge_entries) from public,anon;
grant execute on function sdi_private.challenge_entry_live(sdi_private.challenge_entries) to authenticated,service_role;

create function sdi_private.challenge_action(action text,challenge uuid default null,media uuid default null,entry uuid default null,
 title text default null,brief text default '',reward text default '',starts_at timestamptz default null,closes_at timestamptz default null,
 ends_at timestamptz default null,revision bigint default null,reason text default '') returns jsonb
language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare actor uuid:=auth.uid(); n integer; c sdi_private.challenges; e sdi_private.challenge_entries; items jsonb; phase text; created uuid;
begin
 if actor is null or not sdi_private.account_active() or not exists(select 1 from auth.users where id=actor and not is_anonymous) then
  return jsonb_build_object('error','Sign in with a full account.'); end if;
 insert into sdi_private.challenge_budget values(actor,clock_timestamp(),1)
 on conflict(user_id) do update set
 attempts=case when challenge_budget.starts_at<clock_timestamp()-interval '1 minute' then 1 else challenge_budget.attempts+1 end,
 starts_at=case when challenge_budget.starts_at<clock_timestamp()-interval '1 minute' then clock_timestamp() else challenge_budget.starts_at end
 returning attempts into n;
 if n>60 then return jsonb_build_object('error','Too many requests. Wait a minute.'); end if;
 if action='list' then
  select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into items from (
   select ch.id,ch.title,ch.brief,ch.reward_text,ch.starts_at,ch.submissions_close_at,ch.voting_ends_at,ch.revision,sdi_private.challenge_phase(ch) as phase,
    (select count(*) from sdi_private.challenge_entries en where en.challenge_id=ch.id and sdi_private.challenge_entry_live(en)) as entry_count,
    exists(select 1 from sdi_private.challenge_entries en where en.challenge_id=ch.id and en.creator=actor and not en.withdrawn) as my_entry,
    res.outcome,res.winner_entry
   from sdi_private.challenges ch left join sdi_private.challenge_results res on res.challenge_id=ch.id
   where ch.state='scheduled' and ch.voting_ends_at>clock_timestamp()-interval '30 days'
   order by ch.starts_at limit 100
  ) item;
  return jsonb_build_object('challenges',items,'server_time',clock_timestamp());
 end if;
 if action='entries' then
  select * into c from sdi_private.challenges where id=challenge and state='scheduled';
  if not found then return jsonb_build_object('error','Challenge unavailable.'); end if;
  phase:=sdi_private.challenge_phase(c);
  select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into items from (
   select en.id,en.creator,m.title,m.url,en.created_at,
    case when phase in('voting','completed') then (select count(*) from sdi_private.challenge_votes v where v.entry_id=en.id) end as votes,
    exists(select 1 from sdi_private.challenge_votes v where v.entry_id=en.id and v.voter=actor) as my_vote
   from sdi_private.challenge_entries en join public.sdi_watch_media m on m.id=en.media_id
   where en.challenge_id=c.id and sdi_private.challenge_entry_live(en)
   and not exists(select 1 from sdi_private.feed_blocks b where (b.actor=actor and b.creator=en.creator) or (b.actor=en.creator and b.creator=actor))
   order by en.created_at limit 200
  ) item;
  return jsonb_build_object('phase',phase,'entries',items);
 end if;
 if action in('submit','withdraw','vote') then
  if action='withdraw' then
   select * into e from sdi_private.challenge_entries where id=entry and creator=actor for update;
   if not found then return jsonb_build_object('error','Entry unavailable.'); end if;
   challenge:=e.challenge_id;
  end if;
  select * into c from sdi_private.challenges where id=challenge and state='scheduled' for update;
  if not found then return jsonb_build_object('error','Challenge unavailable.'); end if;
  phase:=sdi_private.challenge_phase(c);
  if action='submit' then
   if phase<>'active' then return jsonb_build_object('error','Submissions are not open.'); end if;
   if not exists(select 1 from public.sdi_watch_media m where m.id=media and m.owner_id=actor and m.approved and m.render_digest is not null
    and (m.expires_at is null or m.expires_at>c.voting_ends_at)) then return jsonb_build_object('error','Select your approved rendered video available through voting.'); end if;
   select * into e from sdi_private.challenge_entries where challenge_id=c.id and creator=actor for update;
   if found and not e.withdrawn then return jsonb_build_object('error','One entry per creator. Withdraw it to change your entry.'); end if;
   if found then
    update sdi_private.challenge_entries set media_id=media,render_digest=(select render_digest from public.sdi_watch_media where id=media),withdrawn=false,created_at=clock_timestamp() where id=e.id;
   else
    insert into sdi_private.challenge_entries(challenge_id,creator,media_id,render_digest)
    select c.id,actor,m.id,m.render_digest from public.sdi_watch_media m where m.id=media;
   end if;
   return jsonb_build_object('status','entered');
  elsif action='withdraw' then
   if phase='completed' then return jsonb_build_object('error','This challenge is complete.'); end if;
   update sdi_private.challenge_entries set withdrawn=true where id=e.id;
   delete from sdi_private.challenge_votes where entry_id=e.id;
   return jsonb_build_object('status','withdrawn');
  else
   if phase<>'voting' then return jsonb_build_object('error','Voting is not open.'); end if;
   select * into e from sdi_private.challenge_entries where id=entry and challenge_id=c.id;
   if not found or not sdi_private.challenge_entry_live(e) then return jsonb_build_object('error','Entry unavailable.'); end if;
   if e.creator=actor or exists(select 1 from sdi_private.challenge_entries own where own.challenge_id=c.id and own.creator=actor and not own.withdrawn) then
    return jsonb_build_object('error','Participants cannot vote in their own challenge.'); end if;
   insert into sdi_private.challenge_votes(challenge_id,voter,entry_id) values(c.id,actor,e.id)
   on conflict(challenge_id,voter) do update set entry_id=excluded.entry_id,created_at=clock_timestamp();
   return jsonb_build_object('status','confirmed');
  end if;
 end if;
 -- Administrative lifecycle. Challenges are scheduled by moderators with MFA.
 if not sdi_private.admin_can('moderation') then return jsonb_build_object('error','Challenge administration requires current moderation permission and MFA.'); end if;
 if action='create' then
  if title is null or length(trim(title)) not between 1 and 100 or brief is null or length(brief)>2000 or reward is null or length(reward)>500 then
   return jsonb_build_object('error','A title, bounded brief and configured reward text are required.'); end if;
  insert into sdi_private.challenges(title,brief,reward_text,created_by) values(trim(title),brief,reward,actor) returning id into created;
  insert into sdi_private.challenge_audit(challenge_id,actor,action,reason) values(created,actor,'create','');
  return jsonb_build_object('status','created','challenge_id',created,'revision',1);
 end if;
 select * into c from sdi_private.challenges where id=challenge for update;
 if not found or revision is distinct from c.revision then return jsonb_build_object('error','Challenge changed. Refresh before acting.'); end if;
 if action='schedule' then
  if c.state='cancelled' or sdi_private.challenge_phase(c) in('voting','completed') then return jsonb_build_object('error','This challenge can no longer be rescheduled.'); end if;
  if starts_at is null or closes_at is null or ends_at is null or starts_at<clock_timestamp()-interval '5 minutes'
   or closes_at<starts_at+interval '1 hour' or ends_at<closes_at+interval '1 hour' or ends_at>starts_at+interval '60 days' then
   return jsonb_build_object('error','Provide future start, at least one hour of submissions, at least one hour of voting and at most sixty days overall.'); end if;
  update sdi_private.challenges set state='scheduled',starts_at=challenge_action.starts_at,submissions_close_at=closes_at,voting_ends_at=ends_at,revision=revision+1 where id=c.id;
 elsif action='cancel' then
  if reason is null or length(trim(reason)) not between 1 and 2000 then return jsonb_build_object('error','A cancellation reason is required.'); end if;
  update sdi_private.challenges set state='cancelled',revision=revision+1 where id=c.id;
 elsif action='remove_entry' then
  if entry is null or reason is null or length(trim(reason)) not between 1 and 2000 then return jsonb_build_object('error','Select an entry and give a reason.'); end if;
  update sdi_private.challenge_entries set withdrawn=true where id=entry and challenge_id=c.id;
  if not found then return jsonb_build_object('error','Entry unavailable.'); end if;
  delete from sdi_private.challenge_votes where entry_id=entry;
 else return jsonb_build_object('error','Unsupported challenge operation.'); end if;
 insert into sdi_private.challenge_audit(challenge_id,actor,action,reason) values(c.id,actor,action,coalesce(trim(reason),''));
 return jsonb_build_object('status','confirmed','revision',c.revision+1);
end $$;
