-- ===== billing.sql (sha256 f144dd3ff58a3263) =====
-- Unapplied candidate. Install after achievements.sql (needs admin-approval.sql and
-- admin-users.sql). Canonical entitlements come only from signed provider events
-- (Stripe webhooks, App Store Server Notifications) verified by server-side edge
-- functions (see backend/billing/README.md). No price is stored here: the owner's
-- approved offers are two monthly tiers at USD 4.99 and USD 9.99; annual periods
-- require explicit owner configuration (owner_configured_at) before any product row
-- can be approved. Clients never write subscription status or tier.
begin;
create table sdi_private.billing_products (
 product_id text primary key check(length(product_id) between 1 and 200), provider text not null check(provider in('apple','stripe')),
 tier text not null check(tier in('creator','pro')), period text not null check(period in('monthly','annual')),
 approved boolean not null default false, owner_configured_at timestamptz, note text not null default '' check(length(note)<=500),
 check(period='monthly' or owner_configured_at is not null or not approved)
);
create table sdi_private.provider_events (
 id uuid primary key default gen_random_uuid(), provider text not null check(provider in('apple','stripe')),
 event_id text not null check(length(event_id) between 1 and 200), event_type text not null check(length(event_type) between 1 and 120),
 occurred_at timestamptz not null, received_at timestamptz not null default clock_timestamp(), payload jsonb not null,
 processed_at timestamptz, outcome text not null default 'received' check(outcome in('received','applied','ignored','error')),
 note text not null default '' check(length(note)<=500), unique(provider,event_id)
);
create table sdi_private.subscriptions (
 id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete set null,
 provider text not null check(provider in('apple','stripe')), provider_subscription_id text not null check(length(provider_subscription_id) between 1 and 200),
 product_id text not null references sdi_private.billing_products(product_id),
 status text not null check(status in('active','trialing','grace','past_due','cancelled','expired','revoked','refunded')),
 paid_through timestamptz not null, cancel_at_period_end boolean not null default false,
 last_event_at timestamptz not null, updated_at timestamptz not null default clock_timestamp(),
 unique(provider,provider_subscription_id)
);
-- Provider-reported money movements. Amounts are copied from signed provider
-- events in minor units; they are records, never an available balance.
create table sdi_private.finance_ledger (
 id uuid primary key default gen_random_uuid(), provider text not null check(provider in('apple','stripe','manual')),
 provider_ref text not null check(length(provider_ref) between 1 and 200),
 kind text not null check(kind in('charge','refund','fee','payout','adjustment','expense')),
 amount_minor bigint not null, currency text not null check(currency ~ '^[A-Z]{3}$'), occurred_at timestamptz not null,
 event_id uuid references sdi_private.provider_events(id), subscription_id uuid references sdi_private.subscriptions(id),
 note text not null default '' check(length(note)<=500), created_at timestamptz not null default clock_timestamp(),
 unique(provider,provider_ref,kind)
);
create table sdi_private.finance_audit (
 id uuid primary key default gen_random_uuid(), actor uuid not null references auth.users(id), action text not null,
 reason text not null check(length(reason) between 1 and 2000), created_at timestamptz not null default clock_timestamp()
);
alter table sdi_private.billing_products enable row level security;
alter table sdi_private.provider_events enable row level security;
alter table sdi_private.subscriptions enable row level security;
alter table sdi_private.finance_ledger enable row level security;
alter table sdi_private.finance_audit enable row level security;
revoke all on sdi_private.billing_products,sdi_private.provider_events,sdi_private.subscriptions,sdi_private.finance_ledger,sdi_private.finance_audit from public,anon,authenticated;
create index subscriptions_user on sdi_private.subscriptions(user_id,paid_through desc);
-- Entitlement: the best current paid tier. 'pro' outranks 'creator'. Grace and
-- past_due keep access until paid_through; nothing else grants anything.
create view sdi_private.entitlements as
 select s.user_id,p.tier,s.paid_through,s.status,s.provider,s.cancel_at_period_end
 from sdi_private.subscriptions s join sdi_private.billing_products p on p.product_id=s.product_id
 where s.user_id is not null and s.status in('active','trialing','grace','past_due') and s.paid_through>clock_timestamp();
revoke all on sdi_private.entitlements from public,anon,authenticated;
create function sdi_private.my_entitlement() returns jsonb language plpgsql security definer set search_path='' as $$
declare e record;
begin
 if not sdi_private.account_active() then return jsonb_build_object('error','Sign in to view your plan.'); end if;
 select * into e from sdi_private.entitlements where user_id=auth.uid()
  order by case tier when 'pro' then 0 else 1 end,paid_through desc limit 1;
 if not found then return jsonb_build_object('tier','free','status','none','paid_through',null,'provider',null); end if;
 return jsonb_build_object('tier',e.tier,'status',e.status,'paid_through',e.paid_through,'provider',e.provider,'cancel_at_period_end',e.cancel_at_period_end);
end $$;
revoke all on function sdi_private.my_entitlement() from public,anon;
grant execute on function sdi_private.my_entitlement() to authenticated;
create function public.sdi_my_entitlement() returns jsonb language sql security invoker set search_path='' as $$select sdi_private.my_entitlement()$$;
revoke all on function public.sdi_my_entitlement() from public,anon;
grant execute on function public.sdi_my_entitlement() to authenticated;

-- Service-only ingestion of one verified provider event. The edge function has
-- already verified the signature and mapped the provider payload to this canonical
-- shape. Duplicate event ids are recorded once; out-of-order events never move a
-- subscription backwards; unknown or unapproved products are ignored, not granted.
create function sdi_private.billing_apply_event(provider text,event_id text,event_type text,occurred_at timestamptz,payload jsonb,
 user_id uuid default null,provider_subscription_id text default null,product_id text default null,status text default null,
 paid_through timestamptz default null,cancel_at_period_end boolean default false,ledger jsonb default '[]') returns jsonb
language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare ev uuid; existing sdi_private.subscriptions; sub uuid; entry jsonb; result text:='applied'; reason text:='';
begin
 if provider is null or provider not in('apple','stripe') or event_id is null or event_type is null or occurred_at is null or payload is null then
  return jsonb_build_object('error','Provider, event id, type, time and payload are required.'); end if;
 insert into sdi_private.provider_events(provider,event_id,event_type,occurred_at,payload) values(provider,event_id,event_type,occurred_at,payload)
 on conflict(provider,event_id) do nothing returning id into ev;
 if ev is null then return jsonb_build_object('duplicate',true); end if;
 if provider_subscription_id is not null then
  if product_id is null or not exists(select 1 from sdi_private.billing_products p where p.product_id=billing_apply_event.product_id and p.provider=billing_apply_event.provider and p.approved) then
   result:='ignored'; reason:='Product is not an approved offer.';
  elsif status is null or status not in('active','trialing','grace','past_due','cancelled','expired','revoked','refunded') or paid_through is null then
   result:='ignored'; reason:='Subscription status or paid-through date missing.';
  else
   select * into existing from sdi_private.subscriptions s where s.provider=billing_apply_event.provider and s.provider_subscription_id=billing_apply_event.provider_subscription_id for update;
   if found and existing.last_event_at>occurred_at then
    result:='ignored'; reason:='Older than the last applied event.';
   else
    insert into sdi_private.subscriptions(user_id,provider,provider_subscription_id,product_id,status,paid_through,cancel_at_period_end,last_event_at)
    values(user_id,provider,provider_subscription_id,product_id,status,paid_through,coalesce(cancel_at_period_end,false),occurred_at)
    on conflict(provider,provider_subscription_id) do update set user_id=coalesce(excluded.user_id,subscriptions.user_id),product_id=excluded.product_id,
     status=excluded.status,paid_through=excluded.paid_through,cancel_at_period_end=excluded.cancel_at_period_end,last_event_at=excluded.last_event_at,updated_at=clock_timestamp()
    returning id into sub;
   end if;
  end if;
 end if;
 for entry in select * from jsonb_array_elements(coalesce(ledger,'[]'::jsonb)) loop
  if entry->>'kind' not in('charge','refund','fee','payout','adjustment') or (entry->>'amount_minor') !~ '^-?[0-9]{1,15}$' or (entry->>'currency') !~ '^[A-Z]{3}$'
   or length(coalesce(entry->>'ref',''))=0 then
   result:='error'; reason:='Ledger entry rejected: '||left(entry::text,200); exit;
  end if;
  insert into sdi_private.finance_ledger(provider,provider_ref,kind,amount_minor,currency,occurred_at,event_id,subscription_id)
  values(provider,entry->>'ref',entry->>'kind',(entry->>'amount_minor')::bigint,entry->>'currency',occurred_at,ev,sub)
  on conflict(provider,provider_ref,kind) do nothing;
 end loop;
 update sdi_private.provider_events set processed_at=clock_timestamp(),outcome=result,note=left(reason,500) where id=ev;
 return jsonb_build_object('event',ev,'outcome',result,'note',reason,'subscription',sub);
end $$;
-- Reconciliation: expire lapsed subscriptions after a 16-day grace window and
-- report counts. Edge functions also call this after replaying missed events.
create function sdi_private.billing_reconcile() returns jsonb language plpgsql security definer set search_path='' as $$
declare expired integer;
begin
 update sdi_private.subscriptions set status='expired',updated_at=clock_timestamp()
 where status in('active','trialing','grace','past_due') and paid_through<clock_timestamp()-interval '16 days';
 get diagnostics expired=row_count;
 return jsonb_build_object('expired_now',expired,
  'entitled',(select count(distinct user_id) from sdi_private.entitlements),
  'lapsing_in_grace',(select count(*) from sdi_private.subscriptions where status in('active','trialing','grace','past_due') and paid_through<=clock_timestamp()),
  'unprocessed_events',(select count(*) from sdi_private.provider_events where processed_at is null),
  'event_errors',(select count(*) from sdi_private.provider_events where outcome='error'),
  'measured_at',clock_timestamp());
end $$;
revoke all on function sdi_private.billing_apply_event(text,text,text,timestamptz,jsonb,uuid,text,text,text,timestamptz,boolean,jsonb),sdi_private.billing_reconcile() from public,anon,authenticated;
grant execute on function sdi_private.billing_apply_event(text,text,text,timestamptz,jsonb,uuid,text,text,text,timestamptz,boolean,jsonb),sdi_private.billing_reconcile() to service_role;
create function public.sdi_billing_apply_event(provider text,event_id text,event_type text,occurred_at timestamptz,payload jsonb,
 user_id uuid default null,provider_subscription_id text default null,product_id text default null,status text default null,
 paid_through timestamptz default null,cancel_at_period_end boolean default false,ledger jsonb default '[]') returns jsonb
language sql security invoker set search_path='' as $$select sdi_private.billing_apply_event(provider,event_id,event_type,occurred_at,payload,user_id,provider_subscription_id,product_id,status,paid_through,cancel_at_period_end,ledger)$$;
create function public.sdi_billing_reconcile() returns jsonb language sql security invoker set search_path='' as $$select sdi_private.billing_reconcile()$$;
revoke all on function public.sdi_billing_apply_event(text,text,text,timestamptz,jsonb,uuid,text,text,text,timestamptz,boolean,jsonb),public.sdi_billing_reconcile() from public,anon,authenticated;
grant execute on function public.sdi_billing_apply_event(text,text,text,timestamptz,jsonb,uuid,text,text,text,timestamptz,boolean,jsonb),public.sdi_billing_reconcile() to service_role;

-- Finance-capability administrators read provider-backed records; product
-- approval is the only mutation and is audited. No balances are computed.
create function sdi_private.finance_admin(action text,page integer default 0,product text default null,provider text default null,
 tier text default null,period text default null,approved boolean default null,reason text default '') returns jsonb
language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare items jsonb;
begin
 if not sdi_private.admin_can('finance') or not sdi_private.account_active() then return jsonb_build_object('error','Current finance permission and MFA required.'); end if;
 if page is null or page not between 0 and 199 then return jsonb_build_object('error','Invalid page.'); end if;
 if action='products' then
  select coalesce(jsonb_agg(row_to_json(p) order by p.provider,p.tier,p.period),'[]'::jsonb) into items from sdi_private.billing_products p;
  return jsonb_build_object('products',items,'approved_offers','Two monthly tiers (USD 4.99, USD 9.99). Annual periods require owner configuration.');
 elsif action='subscriptions' then
  select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into items from (
   select s.id,s.user_id,s.provider,s.product_id,s.status,s.paid_through,s.cancel_at_period_end,s.last_event_at from sdi_private.subscriptions s
   order by s.updated_at desc,s.id limit 50 offset page*50) item;
  return jsonb_build_object('subscriptions',items);
 elsif action='ledger' then
  select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into items from (
   select l.id,l.provider,l.provider_ref,l.kind,l.amount_minor,l.currency,l.occurred_at,l.note from sdi_private.finance_ledger l
   order by l.occurred_at desc,l.id limit 50 offset page*50) item;
  return jsonb_build_object('ledger',items,'label','Provider-reported records in minor units; not an available balance.');
 elsif action='events' then
  select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into items from (
   select e.id,e.provider,e.event_type,e.occurred_at,e.received_at,e.processed_at,e.outcome,e.note from sdi_private.provider_events e
   order by e.received_at desc,e.id limit 50 offset page*50) item;
  return jsonb_build_object('events',items);
 elsif action='summary' then
  select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into items from (
   select l.provider,l.currency,l.kind,sum(l.amount_minor) as amount_minor,count(*) as entries from sdi_private.finance_ledger l
   group by l.provider,l.currency,l.kind order by l.provider,l.currency,l.kind) item;
  return jsonb_build_object('totals',items,'label','Sums of provider-reported entries; estimates and cash are not shown here.',
   'entitled_accounts',(select count(distinct user_id) from sdi_private.entitlements));
 elsif action='configure_annual' then
  -- The owner's explicit annual decision (amounts live in the provider dashboards).
  if not exists(select 1 from sdi_private.admin_roles where user_id=auth.uid() and enabled and owner) then return jsonb_build_object('error','Owner permission required.'); end if;
  if product is null or reason is null or length(trim(reason)) not between 1 and 2000 then return jsonb_build_object('error','Product id and reason required.'); end if;
  update sdi_private.billing_products p set owner_configured_at=clock_timestamp() where p.product_id=trim(product) and p.period='annual';
  if not found then return jsonb_build_object('error','No annual product with that id.'); end if;
  insert into sdi_private.finance_audit(actor,action,reason) values(auth.uid(),'configure_annual '||trim(product),trim(finance_admin.reason));
  return jsonb_build_object('status','confirmed');
 elsif action='set_product' then
  if not exists(select 1 from sdi_private.admin_roles where user_id=auth.uid() and enabled and owner) then return jsonb_build_object('error','Owner permission required.'); end if;
  if product is null or length(trim(product)) not between 1 and 200 or provider not in('apple','stripe') or tier not in('creator','pro') or period not in('monthly','annual')
   or approved is null or reason is null or length(trim(reason)) not between 1 and 2000 then return jsonb_build_object('error','Product id, provider, tier, period, approval and reason required.'); end if;
  if period='annual' and approved and not exists(select 1 from sdi_private.billing_products p where p.product_id=trim(product) and p.owner_configured_at is not null) then
   return jsonb_build_object('error','Annual offers need explicit owner configuration before approval.'); end if;
  insert into sdi_private.billing_products(product_id,provider,tier,period,approved,owner_configured_at)
  values(trim(product),provider,tier,period,approved,case when period='annual' then null else clock_timestamp() end)
  on conflict(product_id) do update set provider=excluded.provider,tier=excluded.tier,period=excluded.period,approved=excluded.approved;
  insert into sdi_private.finance_audit(actor,action,reason) values(auth.uid(),'set_product '||trim(product)||' approved='||approved,trim(finance_admin.reason));
  return jsonb_build_object('status','confirmed');
 end if;
 return jsonb_build_object('error','Unsupported finance operation.');
end $$;
revoke all on function sdi_private.finance_admin(text,integer,text,text,text,text,boolean,text) from public,anon;
grant execute on function sdi_private.finance_admin(text,integer,text,text,text,text,boolean,text) to authenticated;
create function public.sdi_finance_admin(action text,page integer default 0,product text default null,provider text default null,
 tier text default null,period text default null,approved boolean default null,reason text default '') returns jsonb
language sql security invoker set search_path='' as $$select sdi_private.finance_admin(action,page,product,provider,tier,period,approved,reason)$$;
revoke all on function public.sdi_finance_admin(text,integer,text,text,text,text,boolean,text) from public,anon;
grant execute on function public.sdi_finance_admin(text,integer,text,text,text,text,boolean,text) to authenticated;
commit;

-- ===== agent-controls.sql (sha256 8fb2ae5ab7e32a17) =====
-- Unapplied candidate. Install after billing.sql (needs admin-approval.sql, admin-users.sql;
-- the registry list calls count_if_exists from admin-hardening.sql at run time).
-- Owner controls for automated agents (Spatter daily drafts, moderation sweeps,
-- support triage, finance reconciliation, marketing proposals): registry, pause,
-- global emergency stop, per-agent caps and permissions, versioned instructions
-- with rollback, and a run log with heartbeats. Agents call the service functions
-- before and after each run; a refused run must not do any work. Spending caps
-- are configuration in minor currency units, not charges; nothing here spends.
begin;
create table sdi_private.agents (
 key text primary key check(key ~ '^[a-z0-9_]{1,40}$'), title text not null check(length(title) between 1 and 100),
 paused boolean not null default true, permissions text[] not null default array['read'] check(permissions <@ array['read','write','propose']),
 daily_run_cap integer not null default 24 check(daily_run_cap between 0 and 1440), per_run_item_cap integer not null default 10 check(per_run_item_cap between 0 and 10000),
 monthly_cost_cap_minor bigint not null default 0 check(monthly_cost_cap_minor>=0), active_instruction_version integer,
 -- Optional per-run (per-job) cost cap; null means only the monthly cap applies.
 per_run_cost_cap_minor bigint check(per_run_cost_cap_minor>=0),
 revision bigint not null default 1, updated_at timestamptz not null default clock_timestamp()
);
create table sdi_private.agent_global (
 singleton boolean primary key default true check(singleton), emergency_stop boolean not null default false,
 reason text not null default '', updated_by uuid references auth.users(id), updated_at timestamptz not null default clock_timestamp()
);
insert into sdi_private.agent_global(singleton) values(true);
create table sdi_private.agent_instructions (
 id uuid primary key default gen_random_uuid(), agent_key text not null references sdi_private.agents(key) on delete cascade,
 version integer not null check(version>0), body text not null check(length(body) between 1 and 20000),
 author uuid not null references auth.users(id), created_at timestamptz not null default clock_timestamp(), unique(agent_key,version)
);
create table sdi_private.agent_runs (
 id uuid primary key default gen_random_uuid(), agent_key text not null references sdi_private.agents(key),
 instruction_version integer, source_ref text not null default '' check(length(source_ref)<=200),
 started_at timestamptz not null default clock_timestamp(), heartbeat_at timestamptz not null default clock_timestamp(), finished_at timestamptz,
 state text not null default 'running' check(state in('running','succeeded','failed','stopped')),
 items integer not null default 0 check(items>=0), cost_minor bigint not null default 0 check(cost_minor>=0), error text not null default '' check(length(error)<=2000)
);
create table sdi_private.agent_audit (
 id uuid primary key default gen_random_uuid(), actor uuid not null references auth.users(id), agent_key text,
 action text not null, reason text not null check(length(reason) between 1 and 2000), created_at timestamptz not null default clock_timestamp()
);
alter table sdi_private.agents enable row level security;
alter table sdi_private.agent_global enable row level security;
alter table sdi_private.agent_instructions enable row level security;
alter table sdi_private.agent_runs enable row level security;
alter table sdi_private.agent_audit enable row level security;
revoke all on sdi_private.agents,sdi_private.agent_global,sdi_private.agent_instructions,sdi_private.agent_runs,sdi_private.agent_audit from public,anon,authenticated;
create index agent_runs_recent on sdi_private.agent_runs(agent_key,started_at desc);
-- Registry rows start paused; the owner enables each agent deliberately.
insert into sdi_private.agents(key,title) values
 ('spatter_daily_video','Spatter daily draft generation'),('moderation_sweep','Moderation queue summaries'),
 ('support_triage','Support request triage'),('finance_reconcile','Billing reconciliation'),('marketing_proposals','Marketing proposals (approval only)');

create function sdi_private.agent_admin(action text,agent text default null,revision bigint default null,payload jsonb default '{}',reason text default '') returns jsonb
language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare a sdi_private.agents; items jsonb; is_owner boolean; next_version integer; target_version integer;
 filter_state text; filter_query text; page integer; more boolean;
begin
 if not sdi_private.admin_can('overview') or not sdi_private.account_active() then return jsonb_build_object('error','Current administrator MFA session required.'); end if;
 select owner into is_owner from sdi_private.admin_roles where user_id=auth.uid() and enabled;
 if action='list' then
  select coalesce(jsonb_agg(row_to_json(item) order by item.key),'[]'::jsonb) into items from (
   select ag.key,ag.title,ag.paused,ag.permissions,ag.daily_run_cap,ag.per_run_item_cap,ag.monthly_cost_cap_minor,ag.per_run_cost_cap_minor,
    ag.active_instruction_version,ag.revision,
    (select count(*) from sdi_private.agent_runs r where r.agent_key=ag.key and r.state='running') as running,
    (select max(r.finished_at) from sdi_private.agent_runs r where r.agent_key=ag.key) as last_finished,
    (select max(r.started_at) from sdi_private.agent_runs r where r.agent_key=ag.key) as last_started,
    (select r.error from sdi_private.agent_runs r where r.agent_key=ag.key and r.state='failed' and r.error<>''
      order by r.started_at desc limit 1) as last_error,
    -- Queue depth: proposals awaiting the owner (agent-proposals.sql installs later).
    sdi_private.count_if_exists('sdi_private.agent_proposals',format('agent_key=%L and state=%L',ag.key,'pending')) as pending_proposals,
    (select count(*) from sdi_private.agent_runs r where r.agent_key=ag.key and r.state='failed' and r.started_at>clock_timestamp()-interval '7 days') as failures_7d,
    (select coalesce(sum(r.cost_minor),0) from sdi_private.agent_runs r where r.agent_key=ag.key and r.started_at>=date_trunc('month',clock_timestamp())) as cost_month_minor,
    (select count(*) from sdi_private.agent_runs r where r.agent_key=ag.key and r.started_at>=date_trunc('day',clock_timestamp())) as runs_today
   from sdi_private.agents ag) item;
  return jsonb_build_object('agents',items,'emergency_stop',(select emergency_stop from sdi_private.agent_global),'emergency_reason',(select reason from sdi_private.agent_global));
 elsif action in('runs','audit') then
  -- Searchable, paged history: optional state (runs) and a substring query.
  filter_state:=nullif(payload->>'state',''); filter_query:=coalesce(payload->>'query','');
  if coalesce(payload->>'page','0') !~ '^[0-9]{1,3}$' or (payload->>'page')::integer>199 or length(filter_query)>100
   or (filter_state is not null and filter_state not in('running','succeeded','failed','stopped')) then
   return jsonb_build_object('error','Invalid history filter.'); end if;
  page:=coalesce((payload->>'page')::integer,0);
  if action='runs' then
   select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into items from (
    select r.id,r.agent_key,r.instruction_version,r.source_ref,r.started_at,r.heartbeat_at,r.finished_at,r.state,r.items,r.cost_minor,r.error
    from sdi_private.agent_runs r where (agent is null or r.agent_key=agent) and (filter_state is null or r.state=filter_state)
     and (filter_query='' or position(lower(filter_query) in lower(r.source_ref||' '||r.error))>0)
    order by r.started_at desc,r.id limit 51 offset page*50) item;
   more:=jsonb_array_length(items)>50;
   return jsonb_build_object('runs',case when more then items-50 else items end,'has_more',more,'page',page);
  end if;
  select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into items from (
   select au.id,au.actor,au.agent_key,au.action,au.reason,au.created_at
   from sdi_private.agent_audit au where (agent is null or au.agent_key=agent)
    and (filter_query='' or position(lower(filter_query) in lower(au.action||' '||au.reason))>0)
   order by au.created_at desc,au.id limit 51 offset page*50) item;
  more:=jsonb_array_length(items)>50;
  return jsonb_build_object('audit',case when more then items-50 else items end,'has_more',more,'page',page);
 elsif action='instructions' then
  select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into items from (
   select i.version,i.body,i.author,i.created_at from sdi_private.agent_instructions i where i.agent_key=agent order by i.version desc limit 50) item;
  return jsonb_build_object('instructions',items,'active',(select active_instruction_version from sdi_private.agents where key=agent));
 end if;
 if not coalesce(is_owner,false) then return jsonb_build_object('error','Owner permission required for agent changes.'); end if;
 if reason is null or length(trim(reason)) not between 1 and 2000 then return jsonb_build_object('error','A reason is required.'); end if;
 if action='emergency_stop' then
  if payload->>'enabled' is null then return jsonb_build_object('error','Specify enabled true or false.'); end if;
  update sdi_private.agent_global set emergency_stop=(payload->>'enabled')::boolean,reason=trim(agent_admin.reason),updated_by=auth.uid(),updated_at=clock_timestamp();
  if (payload->>'enabled')::boolean then
   update sdi_private.agent_runs set state='stopped',finished_at=clock_timestamp(),error='Emergency stop.' where state='running';
  end if;
  insert into sdi_private.agent_audit(actor,action,reason) values(auth.uid(),'emergency_stop '||(payload->>'enabled'),trim(agent_admin.reason));
  return jsonb_build_object('status','confirmed');
 end if;
 select * into a from sdi_private.agents where key=agent for update;
 if not found or revision is distinct from a.revision then return jsonb_build_object('error','Agent changed. Refresh before saving.'); end if;
 if action='pause' then update sdi_private.agents set paused=true where key=a.key;
  update sdi_private.agent_runs set state='stopped',finished_at=clock_timestamp(),error='Paused by owner.' where agent_key=a.key and state='running';
 elsif action='resume' then
  if (select emergency_stop from sdi_private.agent_global) then return jsonb_build_object('error','Clear the emergency stop first.'); end if;
  if a.active_instruction_version is null then return jsonb_build_object('error','Publish instructions before resuming this agent.'); end if;
  update sdi_private.agents set paused=false where key=a.key;
 elsif action='set_caps' then
  if (payload->>'daily_run_cap') !~ '^[0-9]{1,4}$' or (payload->>'per_run_item_cap') !~ '^[0-9]{1,5}$' or (payload->>'monthly_cost_cap_minor') !~ '^[0-9]{1,12}$' then
   return jsonb_build_object('error','Provide numeric daily run, per-run item and monthly cost caps.'); end if;
  if coalesce(payload->>'per_run_cost_cap_minor','') !~ '^([0-9]{1,12})?$' then
   return jsonb_build_object('error','The per-run cost cap must be empty or a whole number of minor units.'); end if;
  update sdi_private.agents set daily_run_cap=(payload->>'daily_run_cap')::integer,per_run_item_cap=(payload->>'per_run_item_cap')::integer,
   monthly_cost_cap_minor=(payload->>'monthly_cost_cap_minor')::bigint,
   per_run_cost_cap_minor=nullif(coalesce(payload->>'per_run_cost_cap_minor',''),'')::bigint where key=a.key;
 elsif action='set_permissions' then
  if jsonb_typeof(payload->'permissions')<>'array' or not (select coalesce(array_agg(v),'{}') from jsonb_array_elements_text(payload->'permissions') v) <@ array['read','write','propose'] then
   return jsonb_build_object('error','Permissions must be a subset of read, write, propose.'); end if;
  update sdi_private.agents set permissions=(select coalesce(array_agg(distinct v order by v),'{}') from jsonb_array_elements_text(payload->'permissions') v) where key=a.key;
 elsif action='publish_instructions' then
  if length(coalesce(payload->>'body',''))not between 1 and 20000 then return jsonb_build_object('error','Instruction text of at most 20000 characters is required.'); end if;
  select coalesce(max(version),0)+1 into next_version from sdi_private.agent_instructions where agent_key=a.key;
  insert into sdi_private.agent_instructions(agent_key,version,body,author) values(a.key,next_version,payload->>'body',auth.uid());
  update sdi_private.agents set active_instruction_version=next_version where key=a.key;
 elsif action='rollback_instructions' then
  target_version:=(payload->>'version')::integer;
  if not exists(select 1 from sdi_private.agent_instructions where agent_key=a.key and version=target_version) then return jsonb_build_object('error','Unknown instruction version.'); end if;
  update sdi_private.agents set active_instruction_version=target_version where key=a.key;
 else return jsonb_build_object('error','Unsupported agent operation.'); end if;
 update sdi_private.agents set revision=revision+1,updated_at=clock_timestamp() where key=a.key;
 insert into sdi_private.agent_audit(actor,agent_key,action,reason) values(auth.uid(),a.key,agent_admin.action,trim(agent_admin.reason));
 return jsonb_build_object('status','confirmed','revision',a.revision+1);
end $$;
revoke all on function sdi_private.agent_admin(text,text,bigint,jsonb,text) from public,anon;
grant execute on function sdi_private.agent_admin(text,text,bigint,jsonb,text) to authenticated;
create function public.sdi_agent_admin(action text,agent text default null,revision bigint default null,payload jsonb default '{}',reason text default '') returns jsonb
language sql security invoker set search_path='' as $$select sdi_private.agent_admin(action,agent,revision,payload,reason)$$;
revoke all on function public.sdi_agent_admin(text,text,bigint,jsonb,text) from public,anon;
grant execute on function public.sdi_agent_admin(text,text,bigint,jsonb,text) to authenticated;

-- Service contract: begin → (heartbeat)* → finish. A refusal carries the reason.
create function sdi_private.agent_run_begin(agent text,source_ref text default '') returns jsonb language plpgsql security definer set search_path='' as $$
declare a sdi_private.agents; run uuid; spent bigint; body text;
begin
 select * into a from sdi_private.agents where key=agent for update;
 if not found then return jsonb_build_object('allowed',false,'reason','Unknown agent.'); end if;
 if (select emergency_stop from sdi_private.agent_global) then return jsonb_build_object('allowed',false,'reason','Emergency stop is active.'); end if;
 if a.paused then return jsonb_build_object('allowed',false,'reason','Agent is paused.'); end if;
 if a.active_instruction_version is null then return jsonb_build_object('allowed',false,'reason','No published instructions.'); end if;
 update sdi_private.agent_runs set state='failed',finished_at=clock_timestamp(),error='Heartbeat lost.' where agent_key=a.key and state='running' and heartbeat_at<clock_timestamp()-interval '15 minutes';
 if exists(select 1 from sdi_private.agent_runs where agent_key=a.key and state='running') then return jsonb_build_object('allowed',false,'reason','A run is already in progress.'); end if;
 if (select count(*) from sdi_private.agent_runs where agent_key=a.key and started_at>=date_trunc('day',clock_timestamp()))>=a.daily_run_cap then
  return jsonb_build_object('allowed',false,'reason','Daily run cap reached.'); end if;
 select coalesce(sum(cost_minor),0) into spent from sdi_private.agent_runs where agent_key=a.key and started_at>=date_trunc('month',clock_timestamp());
 if spent>=a.monthly_cost_cap_minor then return jsonb_build_object('allowed',false,'reason','Monthly cost cap reached.'); end if;
 select i.body into body from sdi_private.agent_instructions i where i.agent_key=a.key and i.version=a.active_instruction_version;
 insert into sdi_private.agent_runs(agent_key,instruction_version,source_ref) values(a.key,a.active_instruction_version,left(coalesce(source_ref,''),200)) returning id into run;
 return jsonb_build_object('allowed',true,'run',run,'instructions',body,'instruction_version',a.active_instruction_version,
  'permissions',to_jsonb(a.permissions),'per_run_item_cap',a.per_run_item_cap,'remaining_cost_minor',a.monthly_cost_cap_minor-spent,
  'run_cost_cap_minor',least(a.monthly_cost_cap_minor-spent,coalesce(a.per_run_cost_cap_minor,a.monthly_cost_cap_minor-spent)));
end $$;
create function sdi_private.agent_run_heartbeat(run uuid) returns boolean language plpgsql security definer set search_path='' as $$
begin
 if (select emergency_stop from sdi_private.agent_global) then return false; end if;
 update sdi_private.agent_runs r set heartbeat_at=clock_timestamp() where r.id=run and r.state='running'
  and not exists(select 1 from sdi_private.agents a where a.key=r.agent_key and a.paused);
 return found;
end $$;
-- The reported cost is always recorded as reported. A run that overspent its
-- per-run cap (or pushed the month past the monthly cap) pauses the agent so the
-- owner reviews it before any further run; drafts and the record are kept.
create function sdi_private.agent_run_finish(run uuid,state text,items integer default 0,cost_minor bigint default 0,error text default '') returns boolean
language plpgsql security definer set search_path='' as $$
declare a sdi_private.agents; run_agent text; spent bigint;
begin
 if state not in('succeeded','failed','stopped') or items is null or items<0 or cost_minor is null or cost_minor<0 then return false; end if;
 update sdi_private.agent_runs r set state=agent_run_finish.state,items=agent_run_finish.items,cost_minor=agent_run_finish.cost_minor,
  error=left(coalesce(agent_run_finish.error,''),2000),finished_at=clock_timestamp() where r.id=run and r.state='running'
  returning r.agent_key into run_agent;
 if run_agent is null then return false; end if;
 select * into a from sdi_private.agents where agents.key=run_agent for update;
 select coalesce(sum(r.cost_minor),0) into spent from sdi_private.agent_runs r where r.agent_key=a.key and r.started_at>=date_trunc('month',clock_timestamp());
 if (a.per_run_cost_cap_minor is not null and cost_minor>a.per_run_cost_cap_minor) or spent>a.monthly_cost_cap_minor then
  update sdi_private.agents set paused=true,revision=revision+1,updated_at=clock_timestamp() where agents.key=a.key;
  update sdi_private.agent_runs r set error=left(case when r.error='' then '' else r.error||' ' end||'Cost cap exceeded; agent paused for owner review.',2000) where r.id=run;
 end if;
 return true;
end $$;

-- Bounded retention for the run log and the agent audit (#284): finished runs are
-- kept 180 days, audit rows 400 days. Service-only; the append-only audit guard in
-- admin-hardening.sql refuses any earlier deletion.
create function sdi_private.agent_log_retention() returns jsonb language plpgsql security definer set search_path='' as $$
declare runs_deleted bigint; audit_deleted bigint;
begin
 delete from sdi_private.agent_runs where state<>'running' and started_at<clock_timestamp()-interval '180 days';
 get diagnostics runs_deleted=row_count;
 delete from sdi_private.agent_audit where created_at<clock_timestamp()-interval '400 days';
 get diagnostics audit_deleted=row_count;
 return jsonb_build_object('runs_deleted',runs_deleted,'audit_deleted',audit_deleted);
end $$;
revoke all on function sdi_private.agent_log_retention() from public,anon,authenticated;
grant execute on function sdi_private.agent_log_retention() to service_role;
create function public.sdi_agent_log_retention() returns jsonb language sql security invoker set search_path='' as $$select sdi_private.agent_log_retention()$$;
revoke all on function public.sdi_agent_log_retention() from public,anon,authenticated;
grant execute on function public.sdi_agent_log_retention() to service_role;
revoke all on function sdi_private.agent_run_begin(text,text),sdi_private.agent_run_heartbeat(uuid),sdi_private.agent_run_finish(uuid,text,integer,bigint,text) from public,anon,authenticated;
grant execute on function sdi_private.agent_run_begin(text,text),sdi_private.agent_run_heartbeat(uuid),sdi_private.agent_run_finish(uuid,text,integer,bigint,text) to service_role;
create function public.sdi_agent_run_begin(agent text,source_ref text default '') returns jsonb language sql security invoker set search_path='' as $$select sdi_private.agent_run_begin(agent,source_ref)$$;
create function public.sdi_agent_run_heartbeat(run uuid) returns boolean language sql security invoker set search_path='' as $$select sdi_private.agent_run_heartbeat(run)$$;
create function public.sdi_agent_run_finish(run uuid,state text,items integer default 0,cost_minor bigint default 0,error text default '') returns boolean
language sql security invoker set search_path='' as $$select sdi_private.agent_run_finish(run,state,items,cost_minor,error)$$;
revoke all on function public.sdi_agent_run_begin(text,text),public.sdi_agent_run_heartbeat(uuid),public.sdi_agent_run_finish(uuid,text,integer,bigint,text) from public,anon,authenticated;
grant execute on function public.sdi_agent_run_begin(text,text),public.sdi_agent_run_heartbeat(uuid),public.sdi_agent_run_finish(uuid,text,integer,bigint,text) to service_role;
commit;

-- ===== admin-hardening.sql (sha256 f7353414077e1d88) =====
-- Unapplied candidate. Install after agent-controls.sql (needs admin-approval.sql,
-- admin-permissions.sql, admin-users.sql). Adds step-up (recent MFA) checks for
-- sensitive administration, per-administrator rate limits with a denial audit, a
-- service-only owner provisioning function that takes no password, worker heartbeats
-- and an authenticated health view that exposes queue state but no host details.
begin;
-- Step-up: the JWT 'amr' claims carry the time of each authentication method. A
-- sensitive action needs an MFA method verified within the window; the client
-- performs an MFA challenge/verify to refresh it. No client-supplied flag is trusted.
create function sdi_private.recently_authenticated(max_age interval default interval '15 minutes') returns boolean
language sql stable security definer set search_path='' as $$
 select auth.uid() is not null and exists(select 1 from jsonb_array_elements(coalesce(auth.jwt()->'amr','[]'::jsonb)) e
  where e->>'method' in('totp','webauthn','phone','mfa/totp','mfa/phone','mfa/webauthn')
  and (e->>'timestamp') ~ '^[0-9]{1,12}$' and to_timestamp((e->>'timestamp')::bigint)>clock_timestamp()-max_age)
$$;
revoke all on function sdi_private.recently_authenticated(interval) from public,anon;
grant execute on function sdi_private.recently_authenticated(interval) to authenticated;
create table sdi_private.admin_budget (
 user_id uuid primary key references auth.users(id) on delete cascade, window_start timestamptz not null, attempts integer not null
);
create table sdi_private.admin_access_audit (
 id uuid primary key default gen_random_uuid(), actor uuid, operation text not null, allowed boolean not null,
 detail text not null default '' check(length(detail)<=200), created_at timestamptz not null default clock_timestamp()
);
alter table sdi_private.admin_budget enable row level security;
alter table sdi_private.admin_access_audit enable row level security;
revoke all on sdi_private.admin_budget,sdi_private.admin_access_audit from public,anon,authenticated;
create index admin_access_audit_recent on sdi_private.admin_access_audit(created_at desc);
create function sdi_private.admin_rate_ok(limit_per_minute integer default 60) returns boolean language plpgsql security definer set search_path='' as $$
declare n integer;
begin
 if auth.uid() is null then return false; end if;
 insert into sdi_private.admin_budget values(auth.uid(),clock_timestamp(),1)
 on conflict(user_id) do update set
 attempts=case when admin_budget.window_start<clock_timestamp()-interval '1 minute' then 1 else admin_budget.attempts+1 end,
 window_start=case when admin_budget.window_start<clock_timestamp()-interval '1 minute' then clock_timestamp() else admin_budget.window_start end
 returning attempts into n;
 return n<=limit_per_minute;
end $$;
revoke all on function sdi_private.admin_rate_ok(integer) from public,anon;
grant execute on function sdi_private.admin_rate_ok(integer) to authenticated;
-- One gate for administrative RPCs: capability + MFA + live session, optional
-- step-up, rate limit, and an audit row for every denial. Returns null when allowed.
create function sdi_private.admin_gate(operation text,capability text,sensitive boolean default false,limit_per_minute integer default 60) returns jsonb
language plpgsql security definer set search_path='' as $$
declare problem text; code text;
begin
 if not sdi_private.admin_can(capability) or not sdi_private.account_active() then
  problem:='Current administrator permission and MFA session required.'; code:='forbidden';
 elsif sensitive and not sdi_private.recently_authenticated(interval '15 minutes') then
  problem:='Re-verify your second factor to continue.'; code:='step_up_required';
 elsif not sdi_private.admin_rate_ok(limit_per_minute) then
  problem:='Too many administrative requests. Wait a minute.'; code:='rate_limited';
 end if;
 if problem is null then return null; end if;
 insert into sdi_private.admin_access_audit(actor,operation,allowed,detail) values(auth.uid(),left(operation,100),false,code);
 return jsonb_build_object('error',problem,'code',code);
end $$;
revoke all on function sdi_private.admin_gate(text,text,boolean,integer) from public,anon;
grant execute on function sdi_private.admin_gate(text,text,boolean,integer) to authenticated;

-- Role changes are sensitive: step-up and a tighter rate limit now apply.
create or replace function sdi_private.admin_permissions(action text,subject uuid default null,capabilities text[] default '{}',
 enabled boolean default false,reason text default '',revision bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare role_record sdi_private.admin_roles; items jsonb; denial jsonb;
begin
 if not sdi_private.admin_authorized() or not sdi_private.account_active() then return jsonb_build_object('error','Current admin MFA session required.');end if;
 if action='mine' then
  select * into role_record from sdi_private.admin_roles where user_id=auth.uid();
  return jsonb_build_object('owner',role_record.owner,'capabilities',case when role_record.owner
   then array['users','reviews','moderation','publishing','overview','finance'] else role_record.permissions end,
   'step_up_current',sdi_private.recently_authenticated(interval '15 minutes'));
 end if;
 if not exists(select 1 from sdi_private.admin_roles where user_id=auth.uid() and owner and admin_roles.enabled) then
  return jsonb_build_object('error','Owner permission required.');end if;
 if action='list' then
  select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into items from (
   select user_id,owner,admin_roles.enabled,permissions,admin_roles.revision from sdi_private.admin_roles order by user_id limit 100
  ) item;
  return jsonb_build_object('roles',items);
 end if;
 denial:=sdi_private.admin_gate('admin_permissions.save','users',true,20);
 if denial is not null then return denial; end if;
 if action is null or action<>'save' or subject is null or subject=auth.uid() or capabilities is null or enabled is null
 or reason is null or length(trim(reason)) not between 1 and 2000
 or not capabilities <@ array['users','reviews','moderation','publishing','overview','finance'] or cardinality(capabilities)>6 then
  return jsonb_build_object('error','Valid subject, explicit permissions and reason required.');end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('sdi-admin-permissions',0));
 perform 1 from auth.users where id=subject for update;
 if not found then return jsonb_build_object('error','Account unavailable.');end if;
 select * into role_record from sdi_private.admin_roles where user_id=subject for update;
 if coalesce(role_record.revision,0) is distinct from revision then return jsonb_build_object('error','Role changed. Refresh before saving.');end if;
 if found and role_record.owner then return jsonb_build_object('error','Owner accounts require the separate recovery procedure.');end if;
 insert into sdi_private.admin_permission_audit(actor,subject,previous_permissions,new_permissions,previous_enabled,new_enabled,reason)
 values(auth.uid(),subject,coalesce(role_record.permissions,'{}'),capabilities,coalesce(role_record.enabled,false),enabled,trim(reason));
 insert into sdi_private.admin_roles(user_id,enabled,permissions) values(subject,enabled,capabilities)
 on conflict(user_id) do update set enabled=excluded.enabled,permissions=excluded.permissions,revision=admin_roles.revision+1;
 delete from auth.sessions where user_id=subject;
 insert into sdi_private.admin_access_audit(actor,operation,allowed,detail) values(auth.uid(),'admin_permissions.save',true,subject::text);
 return jsonb_build_object('status','confirmed');
end $$;

-- Owner provisioning: service role only, bootstrap only, no password anywhere.
-- The owner signs up through the normal identity providers, confirms email and
-- enrols a verified MFA factor first; this binds the display name and handle and
-- grants the owner role. Existing sessions are ended so the first owner session
-- is a fresh MFA sign-in. A second owner requires the separate recovery procedure.
create table sdi_private.admin_profiles (
 user_id uuid primary key references auth.users(id) on delete cascade, display_name text not null check(length(display_name) between 1 and 50),
 handle text not null unique check(handle ~ '^[A-Za-z0-9_]{3,30}$'), created_at timestamptz not null default clock_timestamp()
);
alter table sdi_private.admin_profiles enable row level security;
revoke all on sdi_private.admin_profiles from public,anon,authenticated;
create function sdi_private.provision_owner(subject uuid,display_name text,handle text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare u auth.users; existing_owner uuid;
begin
 if subject is null or display_name is null or length(trim(display_name)) not between 1 and 50 or handle is null or handle !~ '^[A-Za-z0-9_]{3,30}$' then
  return jsonb_build_object('error','Subject, display name (1-50) and handle (3-30 letters, digits, underscore) required.'); end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('sdi-admin-permissions',0));
 select * into u from auth.users where id=subject for update;
 if not found or u.is_anonymous or u.email_confirmed_at is null then return jsonb_build_object('error','The account must exist with a confirmed email.'); end if;
 if not exists(select 1 from auth.mfa_factors f where f.user_id=subject and f.status='verified') then
  return jsonb_build_object('error','Enrol and verify a second factor before owner provisioning.'); end if;
 select user_id into existing_owner from sdi_private.admin_roles where owner and enabled limit 1;
 if existing_owner is not null and existing_owner<>subject then return jsonb_build_object('error','An owner already exists; use the separate recovery procedure.'); end if;
 if existing_owner=subject then return jsonb_build_object('status','already_owner'); end if;
 insert into sdi_private.admin_roles(user_id,enabled,owner,permissions) values(subject,true,true,array['users','reviews','moderation','publishing','overview','finance'])
 on conflict(user_id) do update set enabled=true,owner=true,permissions=excluded.permissions,revision=admin_roles.revision+1;
 insert into sdi_private.admin_profiles(user_id,display_name,handle) values(subject,trim(display_name),handle)
 on conflict(user_id) do update set display_name=excluded.display_name,handle=excluded.handle;
 insert into sdi_private.admin_permission_audit(actor,subject,previous_permissions,new_permissions,previous_enabled,new_enabled,reason)
 values(subject,subject,'{}',array['users','reviews','moderation','publishing','overview','finance'],false,true,'Owner provisioned through the private server procedure.');
 delete from auth.sessions where user_id=subject;
 return jsonb_build_object('status','provisioned','handle',handle);
end $$;
revoke all on function sdi_private.provision_owner(uuid,text,text) from public,anon,authenticated;
grant execute on function sdi_private.provision_owner(uuid,text,text) to service_role;
create function public.sdi_provision_owner(subject uuid,display_name text,handle text) returns jsonb
language sql security invoker set search_path='' as $$select sdi_private.provision_owner(subject,display_name,handle)$$;
revoke all on function public.sdi_provision_owner(uuid,text,text) from public,anon,authenticated;
grant execute on function public.sdi_provision_owner(uuid,text,text) to service_role;

-- Workers report liveness; health shows age, never hostnames or credentials.
create table sdi_private.worker_heartbeats (
 worker text primary key check(worker ~ '^[a-z0-9_-]{1,40}$'), seen_at timestamptz not null default clock_timestamp(),
 note text not null default '' check(length(note)<=200)
);
alter table sdi_private.worker_heartbeats enable row level security;
revoke all on sdi_private.worker_heartbeats from public,anon,authenticated;
create function sdi_private.worker_heartbeat(worker text,note text default '') returns boolean language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
begin
 if worker is null or worker !~ '^[a-z0-9_-]{1,40}$' then return false; end if;
 insert into sdi_private.worker_heartbeats(worker,note) values(worker_heartbeat.worker,left(coalesce(worker_heartbeat.note,''),200))
 on conflict(worker) do update set seen_at=clock_timestamp(),note=excluded.note;
 return true;
end $$;
revoke all on function sdi_private.worker_heartbeat(text,text) from public,anon,authenticated;
grant execute on function sdi_private.worker_heartbeat(text,text) to service_role;
create function public.sdi_worker_heartbeat(worker text,note text default '') returns boolean language sql security invoker set search_path='' as $$select sdi_private.worker_heartbeat(worker,note)$$;
revoke all on function public.sdi_worker_heartbeat(text,text) from public,anon,authenticated;
grant execute on function public.sdi_worker_heartbeat(text,text) to service_role;
-- Later candidates add tables (support requests, deletion requests); count them
-- only when installed so health never errors on a partially installed set.
create function sdi_private.count_if_exists(relation text,predicate text default 'true') returns bigint language plpgsql security definer set search_path='' as $$
declare n bigint;
begin
 if to_regclass(relation) is null then return null; end if;
 execute format('select count(*) from %s where %s',relation,predicate) into n;
 return n;
end $$;
revoke all on function sdi_private.count_if_exists(text,text) from public,anon,authenticated;
create function sdi_private.admin_health() returns jsonb language plpgsql security definer set search_path='' as $$
declare denial jsonb; workers jsonb;
begin
 denial:=sdi_private.admin_gate('admin_health','overview',false,120);
 if denial is not null then return denial; end if;
 select coalesce(jsonb_agg(jsonb_build_object('worker',w.worker,'seen_at',w.seen_at,'note',w.note,'stale',w.seen_at<clock_timestamp()-interval '10 minutes') order by w.worker),'[]'::jsonb)
  into workers from sdi_private.worker_heartbeats w;
 return jsonb_build_object(
  'queues',jsonb_build_object(
   'publish_queued',(select count(*) from sdi_private.publish_jobs where state='queued'),
   'publish_leased',(select count(*) from sdi_private.publish_jobs where state in('leased','cancel_requested')),
   'publish_attention',(select count(*) from sdi_private.publish_jobs where state in('failed','reconcile','removal_pending')),
   'removal_jobs_open',(select count(*) from sdi_private.removal_jobs where state in('pending','running','failed')),
   'render_reviews_pending',(select count(*) from sdi_private.render_reviews where state='pending'),
   'feed_reports_pending',(select count(*) from sdi_private.feed_reports where state='pending'),
   'war_reports_pending',(select count(*) from sdi_private.war_reports where state='pending'),
   'war_appeals_pending',(select count(*) from sdi_private.war_appeals where state='pending'),
   'moderation_appeals_pending',(select count(*) from sdi_private.moderation_appeals where state='pending'),
   'room_reports_pending',(select count(*) from sdi_private.room_reports where state='pending'),
   'account_appeals_pending',(select count(*) from sdi_private.account_appeals where state='pending'),
   'support_open',sdi_private.count_if_exists('sdi_private.support_requests','status in (''open'',''in_progress'',''waiting_on_member'')'),
   'deletion_requests_due',sdi_private.count_if_exists('sdi_private.deletion_requests','state in (''pending'',''processing'',''blocked'')'),
   'agent_runs_running',(select count(*) from sdi_private.agent_runs where state='running'),
   'provider_events_unprocessed',(select count(*) from sdi_private.provider_events where processed_at is null)),
  'oldest_pending',jsonb_build_object(
   'publish_queued',(select min(created_at) from sdi_private.publish_jobs where state='queued'),
   'render_review',(select min(created_at) from sdi_private.render_reviews where state='pending'),
   'feed_report',(select min(created_at) from sdi_private.feed_reports where state='pending'),
   'removal_job',(select min(created_at) from sdi_private.removal_jobs where state in('pending','running','failed'))),
  'workers',workers,
  'emergency_stop',(select emergency_stop from sdi_private.agent_global),
  'admin_denials_24h',(select count(*) from sdi_private.admin_access_audit where not allowed and created_at>clock_timestamp()-interval '24 hours'),
  'measured_at',clock_timestamp());
end $$;
revoke all on function sdi_private.admin_health() from public,anon;
grant execute on function sdi_private.admin_health() to authenticated;
create function public.sdi_admin_health() returns jsonb language sql security invoker set search_path='' as $$select sdi_private.admin_health()$$;
revoke all on function public.sdi_admin_health() from public,anon;
grant execute on function public.sdi_admin_health() to authenticated;
-- Append-only audit (#257, #284, #285, #247): audit rows cannot be edited, and
-- they can be deleted only after the 400-day retention window (by a service
-- sweep). Applies to the access, agent, account, moderation and permission audits
-- and to the operations report log below.
-- Named audit_retention_hold so security-audit-integrity.sql (#256) can own the
-- generic append-only guard for every *_audit table. That guard governs updates
-- to *_audit tables (only foreign-key set-null is allowed); this hold refuses
-- updates elsewhere (ops_reports) and enforces the 400-day window, except inside
-- the account purge.
create function sdi_private.audit_retention_hold() returns trigger language plpgsql set search_path='' as $$
begin
 if tg_op='UPDATE' then
  if tg_table_name like '%\_audit' then return new; end if;
  raise exception 'Audit records are append-only (%).',tg_table_name using errcode='42501'; end if;
 if coalesce(current_setting('sdi.audit_purge',true),'')='on' then return old; end if;
 if old.created_at>clock_timestamp()-interval '400 days' then
  raise exception 'Audit records are kept for 400 days (%).',tg_table_name using errcode='42501'; end if;
 return old;
end $$;
revoke all on function sdi_private.audit_retention_hold() from public,anon,authenticated;
create trigger admin_access_audit_retention_hold before update or delete on sdi_private.admin_access_audit
 for each row execute function sdi_private.audit_retention_hold();
create trigger agent_audit_retention_hold before update or delete on sdi_private.agent_audit
 for each row execute function sdi_private.audit_retention_hold();
create trigger admin_user_audit_retention_hold before update or delete on sdi_private.admin_user_audit
 for each row execute function sdi_private.audit_retention_hold();
create trigger moderation_audit_retention_hold before update or delete on sdi_private.moderation_audit
 for each row execute function sdi_private.audit_retention_hold();
create trigger admin_permission_audit_retention_hold before update or delete on sdi_private.admin_permission_audit
 for each row execute function sdi_private.audit_retention_hold();

-- Backups, restore drills, releases, rollbacks and retention sweeps (#257). The
-- host's jobs report outcomes here through a service-only function; the record
-- holds a kind, an outcome, a version-shaped label and whole-number metrics. No
-- free text, host name, path, bucket, connection string or credential can be
-- stored, so the authenticated read below cannot leak topology. Nothing here
-- starts a backup, restore or deployment: control stays with the host.
create table sdi_private.ops_reports (
 id uuid primary key default gen_random_uuid(),
 kind text not null check(kind in('backup','restore_drill','release','rollback','retention_sweep')),
 outcome text not null check(outcome in('succeeded','failed')),
 label text not null default '' check(label='' or label ~ '^(v?[0-9]{1,6}(\.[0-9]{1,6}){0,3}([-+][0-9A-Za-z]{1,20}(\.[0-9A-Za-z]{1,20}){0,3})?|[0-9a-f]{7,40})$'),
 metrics jsonb not null default '{}' check(jsonb_typeof(metrics)='object' and length(metrics::text)<=1024),
 created_at timestamptz not null default clock_timestamp()
);
alter table sdi_private.ops_reports enable row level security;
revoke all on sdi_private.ops_reports from public,anon,authenticated;
create index ops_reports_recent on sdi_private.ops_reports(kind,outcome,created_at desc);
create trigger ops_reports_retention_hold before update or delete on sdi_private.ops_reports
 for each row execute function sdi_private.audit_retention_hold();
create function sdi_private.ops_report(kind text,outcome text,label text default '',metrics jsonb default '{}') returns jsonb
language plpgsql security definer set search_path='' as $$
#variable_conflict use_variable
declare entry record; n integer:=0; id uuid;
begin
 if kind is null or kind not in('backup','restore_drill','release','rollback','retention_sweep') or outcome is null or outcome not in('succeeded','failed') then
  return jsonb_build_object('error','Unknown report kind or outcome.'); end if;
 if label is null or not (label='' or label ~ '^(v?[0-9]{1,6}(\.[0-9]{1,6}){0,3}([-+][0-9A-Za-z]{1,20}(\.[0-9A-Za-z]{1,20}){0,3})?|[0-9a-f]{7,40})$') then
  return jsonb_build_object('error','Labels are a version number or a commit hash only.'); end if;
 if metrics is null or jsonb_typeof(metrics)<>'object' or length(metrics::text)>1024 then return jsonb_build_object('error','Metrics must be a small object.'); end if;
 for entry in select e.key,e.value from jsonb_each(metrics) e loop
  n:=n+1;
  if n>20 or entry.key !~ '^[a-z_]{1,40}$' or jsonb_typeof(entry.value)<>'number' or entry.value::text !~ '^[0-9]{1,15}$' then
   return jsonb_build_object('error','Metrics are named whole numbers only.'); end if;
 end loop;
 insert into sdi_private.ops_reports(kind,outcome,label,metrics) values(kind,outcome,label,metrics) returning ops_reports.id into id;
 return jsonb_build_object('status','recorded','id',id);
end $$;
revoke all on function sdi_private.ops_report(text,text,text,jsonb) from public,anon,authenticated;
grant execute on function sdi_private.ops_report(text,text,text,jsonb) to service_role;
create function public.sdi_ops_report(kind text,outcome text,label text default '',metrics jsonb default '{}') returns jsonb
language sql security invoker set search_path='' as $$select sdi_private.ops_report(kind,outcome,label,metrics)$$;
revoke all on function public.sdi_ops_report(text,text,text,jsonb) from public,anon,authenticated;
grant execute on function public.sdi_ops_report(text,text,text,jsonb) to service_role;

-- Read-only operations status for administrators with the overview capability.
-- Staleness: a backup is due daily (26 h), a restore drill monthly (35 days), a
-- retention sweep every two days. A missing report reads as stale, not healthy.
create function sdi_private.admin_operations() returns jsonb language plpgsql security definer set search_path='' as $$
declare denial jsonb; recent jsonb; last_backup timestamptz; last_drill timestamptz;
begin
 denial:=sdi_private.admin_gate('admin_operations','overview',false,120);
 if denial is not null then return denial; end if;
 select max(created_at) into last_backup from sdi_private.ops_reports where kind='backup' and outcome='succeeded';
 select max(created_at) into last_drill from sdi_private.ops_reports where kind='restore_drill' and outcome='succeeded';
 select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into recent from (
  select o.kind,o.outcome,o.label,o.metrics,o.created_at from sdi_private.ops_reports o order by o.created_at desc,o.id limit 20) item;
 return jsonb_build_object(
  'backup',jsonb_build_object('last_succeeded_at',last_backup,
   'last_failed_at',(select max(created_at) from sdi_private.ops_reports where kind='backup' and outcome='failed'),
   'stale',last_backup is null or last_backup<clock_timestamp()-interval '26 hours'),
  'restore_drill',jsonb_build_object('last_succeeded_at',last_drill,
   'last_failed_at',(select max(created_at) from sdi_private.ops_reports where kind='restore_drill' and outcome='failed'),
   'stale',last_drill is null or last_drill<clock_timestamp()-interval '35 days'),
  'release',(select jsonb_build_object('label',o.label,'at',o.created_at) from sdi_private.ops_reports o
   where o.kind='release' and o.outcome='succeeded' order by o.created_at desc limit 1),
  'rollback',(select jsonb_build_object('label',o.label,'at',o.created_at,'outcome',o.outcome) from sdi_private.ops_reports o
   where o.kind='rollback' order by o.created_at desc limit 1),
  'retention_sweep',jsonb_build_object(
   'last_succeeded_at',(select max(created_at) from sdi_private.ops_reports where kind='retention_sweep' and outcome='succeeded'),
   'last_failed_at',(select max(created_at) from sdi_private.ops_reports where kind='retention_sweep' and outcome='failed'),
   'stale',coalesce((select max(created_at) from sdi_private.ops_reports where kind='retention_sweep' and outcome='succeeded')<clock_timestamp()-interval '2 days',true)),
  'retention',jsonb_build_object(
   'render_artifacts_live',sdi_private.count_if_exists('sdi_private.render_artifacts','expires_at>clock_timestamp()'),
   'render_artifacts_expired',sdi_private.count_if_exists('sdi_private.render_artifacts','expires_at<=clock_timestamp()'),
   'deletion_requests_blocked',sdi_private.count_if_exists('sdi_private.deletion_requests','state=''blocked''')),
  'recent',recent,
  'note','Reported by host jobs as outcomes and counts only. Hosts, paths and credentials are never stored; backups, restores and deployments are controlled on the host, not here.',
  'measured_at',clock_timestamp());
end $$;
revoke all on function sdi_private.admin_operations() from public,anon;
grant execute on function sdi_private.admin_operations() to authenticated;
create function public.sdi_admin_operations() returns jsonb language sql security invoker set search_path='' as $$select sdi_private.admin_operations()$$;
revoke all on function public.sdi_admin_operations() from public,anon;
grant execute on function public.sdi_admin_operations() to authenticated;
commit;

-- ===== support-requests.sql (sha256 29a9f867308e84d1) =====
-- Unapplied candidate. Install after admin-hardening.sql (needs admin-users.sql and
-- pgcrypto in extensions). Customer support intake for #272: authenticated members
-- file bounded requests with a server receipt, idempotency key and five-per-day limit;
-- administrators with the users capability and MFA work the queue. This is support,
-- not messaging: no member-to-member delivery, no attachments in this candidate and
-- private projects are never uploaded. Bounded retention is recorded per request.
begin;
create table sdi_private.support_requests (
 id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade,
 category text not null check(category in('account','billing','studio','publishing','rights','safety','bug','other')),
 platform text not null check(platform in('ios','android','web','other')), app_version text not null default '' check(length(app_version)<=50),
 subject text not null check(length(subject) between 1 and 120), body text not null check(length(body) between 1 and 2000),
 status text not null default 'open' check(status in('open','in_progress','waiting_on_member','resolved','withdrawn','deleted')),
 receipt text not null unique check(receipt ~ '^SDI-[A-Z0-9]{10}$'), idempotency_key uuid not null,
 admin_note text not null default '' check(length(admin_note)<=2000), revision bigint not null default 1,
 retention_until timestamptz not null, created_at timestamptz not null default clock_timestamp(), updated_at timestamptz not null default clock_timestamp(),
 unique(user_id,idempotency_key)
);
create table sdi_private.support_audit (
 id uuid primary key default gen_random_uuid(), request_id uuid not null references sdi_private.support_requests(id) on delete cascade,
 actor uuid references auth.users(id) on delete set null, action text not null, previous_status text not null,
 note text not null default '' check(length(note)<=2000), created_at timestamptz not null default clock_timestamp()
);
alter table sdi_private.support_requests enable row level security;
alter table sdi_private.support_audit enable row level security;
revoke all on sdi_private.support_requests,sdi_private.support_audit from public,anon,authenticated;
create index support_requests_queue on sdi_private.support_requests(status,created_at,id);
create function sdi_private.support_action(action text,request uuid default null,category text default null,platform text default null,
 app_version text default '',subject text default null,body text default null,idempotency uuid default null,status text default null,
 note text default '',page integer default 0,revision bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare actor uuid:=auth.uid(); existing sdi_private.support_requests; items jsonb; denial jsonb; code text;
begin
 if action in('create','list_mine','withdraw','delete') then
  if actor is null or not sdi_private.account_active() or not exists(select 1 from auth.users where id=actor and not is_anonymous) then
   return jsonb_build_object('error','Sign in with a full account to contact support.'); end if;
  if action='create' then
   if idempotency is null or category is null or category not in('account','billing','studio','publishing','rights','safety','bug','other')
    or platform is null or platform not in('ios','android','web','other') or app_version is null or length(app_version)>50
    or subject is null or length(trim(subject)) not between 1 and 120 or body is null or length(trim(body)) not between 1 and 2000 then
    return jsonb_build_object('error','Choose a category and platform, then describe the issue in up to 2000 characters.'); end if;
   select * into existing from sdi_private.support_requests s where s.user_id=actor and s.idempotency_key=idempotency;
   if found then return jsonb_build_object('status','duplicate','request_id',existing.id,'receipt',existing.receipt,'request_status',existing.status); end if;
   if (select count(*) from sdi_private.support_requests s where s.user_id=actor and s.created_at>clock_timestamp()-interval '1 day')>=5 then
    return jsonb_build_object('error','Daily support request limit reached. Existing requests remain open.'); end if;
   code:='SDI-'||upper(left(translate(encode(extensions.gen_random_bytes(8),'base64'),'+/=01IO','ABCDEFG'),10));
   insert into sdi_private.support_requests(user_id,category,platform,app_version,subject,body,receipt,idempotency_key,retention_until)
   values(actor,category,platform,app_version,trim(subject),trim(body),code,idempotency,clock_timestamp()+interval '180 days') returning * into existing;
   insert into sdi_private.support_audit(request_id,actor,action,previous_status) values(existing.id,actor,'create','open');
   return jsonb_build_object('status','created','request_id',existing.id,'receipt',existing.receipt,'request_status','open');
  elsif action='list_mine' then
   select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into items from (
    select s.id,s.receipt,s.category,s.platform,s.app_version,s.subject,s.body,s.status,s.revision,s.created_at,s.updated_at
    from sdi_private.support_requests s where s.user_id=actor and s.status<>'deleted' order by s.created_at desc,s.id limit 50) item;
   return jsonb_build_object('requests',items);
  end if;
  select * into existing from sdi_private.support_requests s where s.id=request and s.user_id=actor for update;
  if not found or existing.status='deleted' then return jsonb_build_object('error','Request unavailable.'); end if;
  if action='withdraw' then
   if existing.status not in('open','in_progress','waiting_on_member') then return jsonb_build_object('error','This request is already closed.'); end if;
   update sdi_private.support_requests set status='withdrawn',revision=revision+1,updated_at=clock_timestamp(),retention_until=clock_timestamp()+interval '30 days' where id=existing.id;
  else
   -- Member deletion scrubs content immediately; the stub row keeps the daily
   -- rate accounting and receipt until its short retention passes.
   update sdi_private.support_requests set status='deleted',subject='[deleted by member]',body='[deleted by member]',app_version='',admin_note='',
    revision=revision+1,updated_at=clock_timestamp(),retention_until=clock_timestamp()+interval '30 days' where id=existing.id;
  end if;
  insert into sdi_private.support_audit(request_id,actor,action,previous_status) values(existing.id,actor,action,existing.status);
  return jsonb_build_object('status','confirmed');
 end if;
 denial:=sdi_private.admin_gate('support_action.'||coalesce(action,'?'),'users',false,120);
 if denial is not null then return denial; end if;
 if action='list' then
  if page is null or page not between 0 and 199 then return jsonb_build_object('error','Invalid page.'); end if;
  select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into items from (
   select s.id,s.user_id,s.receipt,s.category,s.platform,s.app_version,s.subject,s.body,s.status,s.admin_note,s.revision,s.created_at,s.updated_at
   from sdi_private.support_requests s where s.status<>'deleted' and (support_action.status is null or s.status=support_action.status)
   order by case s.status when 'open' then 0 when 'waiting_on_member' then 1 when 'in_progress' then 2 else 3 end,s.created_at,s.id limit 50 offset page*50) item;
  return jsonb_build_object('requests',items,'has_more',jsonb_array_length(items)=50);
 elsif action='update_status' then
  if request is null or revision is null or status is null or status not in('open','in_progress','waiting_on_member','resolved')
   or note is null or length(trim(note)) not between 1 and 2000 then return jsonb_build_object('error','Select a request, new status and note.'); end if;
  select * into existing from sdi_private.support_requests s where s.id=request for update;
  if not found or existing.status in('deleted','withdrawn') or existing.revision<>revision then return jsonb_build_object('error','Request changed or closed. Refresh the queue.'); end if;
  update sdi_private.support_requests set status=support_action.status,admin_note=trim(note),revision=revision+1,updated_at=clock_timestamp(),
   retention_until=case when support_action.status='resolved' then clock_timestamp()+interval '90 days' else retention_until end where id=existing.id;
  insert into sdi_private.support_audit(request_id,actor,action,previous_status,note) values(existing.id,actor,'status:'||status,existing.status,trim(note));
  insert into sdi_private.admin_access_audit(actor,operation,allowed,detail) values(actor,'support_action.update_status',true,existing.receipt);
  return jsonb_build_object('status','confirmed','revision',existing.revision+1);
 end if;
 return jsonb_build_object('error','Unsupported support operation.');
end $$;
revoke all on function sdi_private.support_action(text,uuid,text,text,text,text,text,uuid,text,text,integer,bigint) from public,anon;
grant execute on function sdi_private.support_action(text,uuid,text,text,text,text,text,uuid,text,text,integer,bigint) to authenticated;
create function public.sdi_support_action(action text,request uuid default null,category text default null,platform text default null,
 app_version text default '',subject text default null,body text default null,idempotency uuid default null,status text default null,
 note text default '',page integer default 0,revision bigint default null) returns jsonb language sql security invoker set search_path='' as $$
 select sdi_private.support_action(action,request,category,platform,app_version,subject,body,idempotency,status,note,page,revision)$$;
revoke all on function public.sdi_support_action(text,uuid,text,text,text,text,text,uuid,text,text,integer,bigint) from public,anon;
grant execute on function public.sdi_support_action(text,uuid,text,text,text,text,text,uuid,text,text,integer,bigint) to authenticated;
-- Retention sweep for the service scheduler: hard-delete expired rows.
create function sdi_private.support_retention() returns integer language plpgsql security definer set search_path='' as $$
declare n integer;
begin
 delete from sdi_private.support_requests where retention_until<=clock_timestamp() and status in('resolved','withdrawn','deleted');
 get diagnostics n=row_count; return n;
end $$;
revoke all on function sdi_private.support_retention() from public,anon,authenticated;
grant execute on function sdi_private.support_retention() to service_role;
create function public.sdi_support_retention() returns integer language sql security invoker set search_path='' as $$select sdi_private.support_retention()$$;
revoke all on function public.sdi_support_retention() from public,anon,authenticated;
grant execute on function public.sdi_support_retention() to service_role;
commit;

-- ===== account-lifecycle.sql (sha256 f453d3953e54a768) =====
-- Unapplied candidate. Install last (after support-requests.sql). Member data export,
-- deletion requests with a cooling-off period, the service worker contract that
-- prepares and later purges an account, and member notices. On-device projects and
-- originals are never stored server-side, so they are neither exported nor deleted
-- here; the export says so. Provider subscriptions are not cancelled by this code:
-- the member cancels through the App Store or the Stripe portal and the notice says so.
begin;
create table sdi_private.member_notices (
 id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade,
 kind text not null check(kind ~ '^[a-z_]{1,40}$'), message text not null check(length(message) between 1 and 500),
 created_at timestamptz not null default clock_timestamp(), read_at timestamptz
);
create table sdi_private.account_export_log (
 id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade,
 created_at timestamptz not null default clock_timestamp()
);
create table sdi_private.deletion_requests (
 id uuid primary key default gen_random_uuid(), user_id uuid unique references auth.users(id) on delete set null,
 state text not null default 'pending' check(state in('pending','processing','blocked','completed','cancelled')),
 requested_at timestamptz not null default clock_timestamp(), scheduled_for timestamptz not null,
 purge_after timestamptz, blocked_reason text not null default '' check(length(blocked_reason)<=500),
 completed_at timestamptz, revision bigint not null default 1
);
-- Pseudonymous consent proof kept after an account is purged (#262). The period
-- is owner configuration (candidate default 1095 days, pending the owner's legal
-- review); consent_retention_sweep deletes rows once retain_until passes.
create table sdi_private.retention_settings (
 singleton boolean primary key default true check(singleton),
 consent_proof_days integer not null default 1095 check(consent_proof_days between 0 and 3650),
 updated_at timestamptz not null default clock_timestamp()
);
insert into sdi_private.retention_settings(singleton) values(true);
create table sdi_private.consent_retention (
 id uuid primary key default gen_random_uuid(), subject_digest text not null check(subject_digest ~ '^[a-f0-9]{64}$'),
 policy text not null, version text not null, source text not null, accepted_at timestamptz not null, withdrawn_at timestamptz not null,
 retained_at timestamptz not null default clock_timestamp(), retain_until timestamptz not null
);
alter table sdi_private.retention_settings enable row level security;
alter table sdi_private.consent_retention enable row level security;
revoke all on sdi_private.retention_settings,sdi_private.consent_retention from public,anon,authenticated;
create index consent_retention_due on sdi_private.consent_retention(retain_until);
alter table sdi_private.member_notices enable row level security;
alter table sdi_private.account_export_log enable row level security;
alter table sdi_private.deletion_requests enable row level security;
revoke all on sdi_private.member_notices,sdi_private.account_export_log,sdi_private.deletion_requests from public,anon,authenticated;
create index member_notices_inbox on sdi_private.member_notices(user_id,read_at,created_at desc);
-- Retained moderation evidence must survive the deletion of the member who filed
-- it: these references become nullable and clear on delete instead of blocking.
alter table sdi_private.war_reports drop constraint war_reports_reporter_fkey, alter column reporter drop not null,
 add constraint war_reports_reporter_fkey foreign key(reporter) references auth.users(id) on delete set null;
alter table sdi_private.war_appeals drop constraint war_appeals_appellant_fkey, alter column appellant drop not null,
 add constraint war_appeals_appellant_fkey foreign key(appellant) references auth.users(id) on delete set null;
alter table sdi_private.moderation_appeals drop constraint moderation_appeals_creator_fkey, alter column creator drop not null,
 add constraint moderation_appeals_creator_fkey foreign key(creator) references auth.users(id) on delete set null;
alter table sdi_private.room_reports drop constraint room_reports_reporter_fkey, alter column reporter drop not null,
 add constraint room_reports_reporter_fkey foreign key(reporter) references auth.users(id) on delete set null;
alter table sdi_private.room_commands drop constraint room_commands_author_fkey, alter column author drop not null,
 add constraint room_commands_author_fkey foreign key(author) references auth.users(id) on delete set null;
alter table sdi_private.challenge_results drop constraint challenge_results_winner_entry_fkey,
 add constraint challenge_results_winner_entry_fkey foreign key(winner_entry) references sdi_private.challenge_entries(id) on delete set null;

create function sdi_private.notify_member(subject uuid,kind text,message text) returns void language sql security definer set search_path='' as $$
 insert into sdi_private.member_notices(user_id,kind,message) select subject,kind,left(message,500) where subject is not null
$$;
revoke all on function sdi_private.notify_member(uuid,text,text) from public,anon,authenticated;
grant execute on function sdi_private.notify_member(uuid,text,text) to service_role;
create function sdi_private.member_notices(action text,notice uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=auth.uid(); items jsonb;
begin
 if actor is null or not exists(select 1 from auth.sessions where user_id=actor and id::text=auth.jwt()->>'session_id') then
  return jsonb_build_object('error','A current signed-in account is required.'); end if;
 if action='mark_read' then update sdi_private.member_notices set read_at=coalesce(read_at,clock_timestamp()) where id=notice and user_id=actor;
 elsif action='mark_all_read' then update sdi_private.member_notices set read_at=clock_timestamp() where user_id=actor and read_at is null;
 elsif action<>'list' then return jsonb_build_object('error','Unsupported notice operation.'); end if;
 select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into items from (
  select id,kind,message,created_at,read_at from sdi_private.member_notices where user_id=actor order by read_at is not null,created_at desc,id limit 50) item;
 return jsonb_build_object('notices',items,'unread',(select count(*) from sdi_private.member_notices where user_id=actor and read_at is null));
end $$;
revoke all on function sdi_private.member_notices(text,uuid) from public,anon;
grant execute on function sdi_private.member_notices(text,uuid) to authenticated;
create function public.sdi_member_notices(action text,notice uuid default null) returns jsonb language sql security invoker set search_path='' as $$select sdi_private.member_notices(action,notice)$$;
revoke all on function public.sdi_member_notices(text,uuid) from public,anon;
grant execute on function public.sdi_member_notices(text,uuid) to authenticated;

-- Export of the member's own server records. Internal reasons, reporter identities
-- and other members' data are excluded. Three exports per day.
create function sdi_private.account_export() returns jsonb language plpgsql security definer set search_path='' as $$
declare me uuid:=auth.uid(); support jsonb:='[]'::jsonb; consents jsonb:='[]'::jsonb; prefs jsonb; devices jsonb:='[]'::jsonb;
begin
 if me is null or not exists(select 1 from auth.users where id=me and not is_anonymous)
 or not exists(select 1 from auth.sessions where user_id=me and id::text=auth.jwt()->>'session_id') then
  return jsonb_build_object('error','A current signed-in account is required.'); end if;
 if (select count(*) from sdi_private.account_export_log where user_id=me and created_at>clock_timestamp()-interval '1 day')>=3 then
  return jsonb_build_object('error','Three exports per day. Try again later.'); end if;
 insert into sdi_private.account_export_log(user_id) values(me);
 if to_regclass('sdi_private.support_requests') is not null then
  execute 'select coalesce(jsonb_agg(row_to_json(s)),''[]''::jsonb) from (select receipt,category,platform,subject,body,status,created_at from sdi_private.support_requests where user_id=$1 order by created_at) s' into support using me;
 end if;
 -- Installed later (consent-versions.sql, notifications.sql); read when present.
 -- Device push tokens are never exported, only which devices are registered.
 if to_regclass('sdi_private.consent_records') is not null then
  execute 'select coalesce(jsonb_agg(row_to_json(c)),''[]''::jsonb) from (select policy,version,source,accepted_at,withdrawn_at from sdi_private.consent_records where user_id=$1 order by accepted_at) c' into consents using me;
 end if;
 if to_regclass('sdi_private.notification_preferences') is not null then
  execute 'select row_to_json(p)::jsonb from (select push_product,push_marketing,email_product,email_marketing,daily_cap from sdi_private.notification_preferences where user_id=$1) p' into prefs using me;
 end if;
 if to_regclass('sdi_private.device_tokens') is not null then
  execute 'select coalesce(jsonb_agg(row_to_json(d)),''[]''::jsonb) from (select platform,environment,created_at,last_seen_at,revoked_at from sdi_private.device_tokens where user_id=$1 order by created_at) d' into devices using me;
 end if;
 return jsonb_build_object(
  'generated_at',clock_timestamp(),
  'note','Editable projects and originals stay on your device and are not stored or exported by the service. Internal moderation reasons and other members'' identities are not included.',
  'account',(select jsonb_build_object('id',u.id,'email',u.email,'username',u.raw_user_meta_data->>'username','created_at',u.created_at,'last_sign_in_at',u.last_sign_in_at,
    'sign_in_methods',(select coalesce(jsonb_agg(distinct i.provider),'[]'::jsonb) from auth.identities i where i.user_id=u.id)) from auth.users u where u.id=me),
  'account_state',coalesce((select jsonb_build_object('state',c.state,'since',c.updated_at) from sdi_private.account_controls c where c.user_id=me),'{"state":"active"}'::jsonb),
  'account_appeals',(select coalesce(jsonb_agg(row_to_json(a)),'[]'::jsonb) from (select explanation,state,reply,created_at,decided_at from sdi_private.account_appeals where subject=me order by created_at) a),
  'feed_posts',(select coalesce(jsonb_agg(row_to_json(p)),'[]'::jsonb) from (select p.id,p.caption,p.published_at,p.visible,p.featured,p.allow_export,m.title,m.url,m.render_digest,m.approved
    from sdi_private.feed_posts p join public.sdi_watch_media m on m.id=p.media_id where p.creator=me order by p.published_at) p),
  'feed_likes',(select coalesce(jsonb_agg(row_to_json(l)),'[]'::jsonb) from (select post,created_at from sdi_private.feed_likes where feed_likes.actor=me order by created_at) l),
  'feed_follows',(select coalesce(jsonb_agg(f.creator),'[]'::jsonb) from sdi_private.feed_follows f where f.actor=me),
  'feed_blocks',(select coalesce(jsonb_agg(b.creator),'[]'::jsonb) from sdi_private.feed_blocks b where b.actor=me),
  'feed_reports',(select coalesce(jsonb_agg(row_to_json(r)),'[]'::jsonb) from (select post,reason,state,created_at from sdi_private.feed_reports where feed_reports.actor=me order by created_at) r),
  'war_matches',(select coalesce(jsonb_agg(row_to_json(w)),'[]'::jsonb) from (select w.id,case when w.creator=me then 'creator' else 'opponent' end as role,w.status,w.created_at,w.ends_at,res.outcome,res.left_votes,res.right_votes
    from sdi_private.war_matches w left join sdi_private.war_results res on res.match_id=w.id where me in(w.creator,w.opponent) order by w.created_at) w),
  'war_votes',(select coalesce(jsonb_agg(row_to_json(v)),'[]'::jsonb) from (select match_id,choice from sdi_private.war_votes where voter=me) v),
  'challenge_entries',(select coalesce(jsonb_agg(row_to_json(e)),'[]'::jsonb) from (select challenge_id,media_id,render_digest,withdrawn,created_at from sdi_private.challenge_entries where creator=me) e),
  'challenge_votes',(select coalesce(jsonb_agg(row_to_json(v)),'[]'::jsonb) from (select challenge_id,entry_id,created_at from sdi_private.challenge_votes where voter=me) v),
  'rooms_owned',(select coalesce(jsonb_agg(row_to_json(r)),'[]'::jsonb) from (select id,title,closed,project_ref,project_title,permissions,created_at from public.sdi_rooms where owner_id=me) r),
  'room_memberships',(select coalesce(jsonb_agg(row_to_json(m)),'[]'::jsonb) from (select room_id,role,owner_approved,member_accepted,revoked from public.sdi_room_members where user_id=me) m),
  'render_reviews',(select coalesce(jsonb_agg(row_to_json(r)),'[]'::jsonb) from (select id,title,render_digest,state,version,consent_version,destinations,allow_export,created_at from sdi_private.render_reviews where creator=me order by created_at) r),
  'publish_jobs',(select coalesce(jsonb_agg(row_to_json(j)),'[]'::jsonb) from (select id,review_id,destination,state,result_url,created_at,updated_at from sdi_private.publish_jobs where creator=me order by created_at) j),
  'subscriptions',(select coalesce(jsonb_agg(row_to_json(s)),'[]'::jsonb) from (select provider,product_id,status,paid_through,cancel_at_period_end from sdi_private.subscriptions where user_id=me) s),
  'badges',(select coalesce(jsonb_agg(row_to_json(b)),'[]'::jsonb) from (select badge_key,title,earned_at,revoked from sdi_private.earned_badges where user_id=me) b),
  'record_preferences',(select row_to_json(p) from (select show_records,show_badges from sdi_private.record_preferences where user_id=me) p),
  'support_requests',support,
  'consents',consents,
  'notification_preferences',prefs,
  'push_devices',devices,
  'notices',(select coalesce(jsonb_agg(row_to_json(n)),'[]'::jsonb) from (select kind,message,created_at,read_at from sdi_private.member_notices where user_id=me order by created_at) n),
  'deletion_request',(select row_to_json(d) from (select state,requested_at,scheduled_for,completed_at from sdi_private.deletion_requests where user_id=me) d));
end $$;
revoke all on function sdi_private.account_export() from public,anon;
grant execute on function sdi_private.account_export() to authenticated;

create function sdi_private.account_lifecycle(action text,revision bigint default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=auth.uid(); d sdi_private.deletion_requests;
begin
 if actor is null or not exists(select 1 from auth.users where id=actor and not is_anonymous)
 or not exists(select 1 from auth.sessions where user_id=actor and id::text=auth.jwt()->>'session_id') then
  return jsonb_build_object('error','A current signed-in account is required.'); end if;
 if action='export' then return sdi_private.account_export(); end if;
 select * into d from sdi_private.deletion_requests where user_id=actor for update;
 if action='status' then
  return jsonb_build_object('deletion',case when d.id is null then null else jsonb_build_object('state',d.state,'requested_at',d.requested_at,'scheduled_for',d.scheduled_for,'revision',d.revision) end,
   'exports_remaining_today',3-(select count(*) from sdi_private.account_export_log where user_id=actor and created_at>clock_timestamp()-interval '1 day'),
   'note','Deletion removes server records after a seven-day cooling-off period. Projects on your devices are untouched. Cancel any subscription through the App Store or billing portal; deletion does not cancel it.');
 elsif action='request_deletion' then
  if exists(select 1 from sdi_private.admin_roles where user_id=actor and enabled) then return jsonb_build_object('error','Administrator accounts use the separate owner procedure.'); end if;
  if d.id is not null and d.state in('pending','processing','blocked') then return jsonb_build_object('status',d.state,'scheduled_for',d.scheduled_for); end if;
  if d.id is null then
   insert into sdi_private.deletion_requests(user_id,scheduled_for) values(actor,clock_timestamp()+interval '7 days') returning * into d;
  else
   update sdi_private.deletion_requests set state='pending',requested_at=clock_timestamp(),scheduled_for=clock_timestamp()+interval '7 days',purge_after=null,
    blocked_reason='',completed_at=null,revision=deletion_requests.revision+1 where id=d.id returning * into d;
  end if;
  perform sdi_private.notify_member(actor,'deletion_requested','Account deletion is scheduled for '||to_char(d.scheduled_for,'YYYY-MM-DD HH24:MI')||' UTC. Sign in and cancel before then to keep the account. Subscriptions must be cancelled with the store or billing portal.');
  return jsonb_build_object('status','pending','scheduled_for',d.scheduled_for,'revision',d.revision);
 elsif action='cancel_deletion' then
  if d.id is null or d.state<>'pending' then return jsonb_build_object('error','No pending deletion request can be cancelled.'); end if;
  if revision is distinct from d.revision then return jsonb_build_object('error','Request changed. Refresh before cancelling.'); end if;
  update sdi_private.deletion_requests set state='cancelled',revision=deletion_requests.revision+1 where id=d.id;
  perform sdi_private.notify_member(actor,'deletion_cancelled','Account deletion was cancelled. Nothing was removed.');
  return jsonb_build_object('status','cancelled');
 end if;
 return jsonb_build_object('error','Unsupported account operation.');
end $$;
revoke all on function sdi_private.account_lifecycle(text,bigint) from public,anon;
grant execute on function sdi_private.account_lifecycle(text,bigint) to authenticated;
create function public.sdi_account_lifecycle(action text,revision bigint default null) returns jsonb language sql security invoker set search_path='' as $$select sdi_private.account_lifecycle(action,revision)$$;
revoke all on function public.sdi_account_lifecycle(text,bigint) from public,anon;
grant execute on function public.sdi_account_lifecycle(text,bigint) to authenticated;

-- Worker contract (service role, call periodically): processes at most one request.
-- Phase 1 'prepared': end sessions, suspend, withdraw publishing consent, unapprove
-- media and queue removals, hide posts, withdraw matches/entries, close rooms, scrub
-- support text; the request waits purge_after (30 days) for removals and intake
-- retirement. Phase 2 'purged': once nothing external remains, delete server rows in
-- dependency order and the auth user. Blockers never cause a partial purge.
create function sdi_private.account_deletion_run() returns jsonb language plpgsql security definer set search_path='' as $$
declare d sdi_private.deletion_requests; u uuid; blockers text[]:='{}';
begin
 select * into d from sdi_private.deletion_requests where state='pending' and scheduled_for<=clock_timestamp() and user_id is not null
  order by scheduled_for for update skip locked limit 1;
 if found then
  u:=d.user_id;
  delete from auth.sessions where user_id=u;
  insert into sdi_private.account_controls(user_id,state,reason) values(u,'suspended','Account deletion in progress.')
  on conflict(user_id) do update set state='suspended',reason='Account deletion in progress.',updated_at=clock_timestamp();
  update sdi_private.render_reviews set consent_version='',destinations='{}',state='pending' where creator=u;
  insert into sdi_private.removal_jobs(media_id,render_digest,reason) select id,render_digest,'Account deletion.' from public.sdi_watch_media where owner_id=u and render_digest is not null and approved
  on conflict(media_id,render_digest) do nothing;
  update public.sdi_watch_media set approved=false where owner_id=u;
  update sdi_private.feed_posts set visible=false,featured=false where creator=u;
  update sdi_private.war_matches set status='withdrawn' where u in(creator,opponent) and status in('pending','active');
  update sdi_private.challenge_entries set withdrawn=true where creator=u;
  delete from sdi_private.challenge_votes where voter=u or entry_id in(select id from sdi_private.challenge_entries where creator=u);
  update public.sdi_rooms set closed=true where owner_id=u;
  update sdi_private.room_invites set revoked=true where room_id in(select id from public.sdi_rooms where owner_id=u);
  update public.sdi_room_members set revoked=true,owner_approved=false,member_accepted=false where user_id=u;
  if to_regclass('sdi_private.support_requests') is not null then
   execute 'update sdi_private.support_requests set status=''deleted'',subject=''[deleted by member]'',body=''[deleted by member]'',app_version='''',admin_note='''',retention_until=clock_timestamp()+interval ''30 days'' where user_id=$1' using u;
  end if;
  -- Consent and delivery stop at phase one, not at the purge (#262).
  if to_regclass('sdi_private.consent_records') is not null then
   execute 'update sdi_private.consent_records set withdrawn_at=clock_timestamp() where user_id=$1 and withdrawn_at is null' using u;
  end if;
  if to_regclass('sdi_private.device_tokens') is not null then
   execute 'update sdi_private.device_tokens set revoked_at=clock_timestamp() where user_id=$1 and revoked_at is null' using u;
  end if;
  if to_regclass('sdi_private.notification_preferences') is not null then
   execute 'update sdi_private.notification_preferences set push_product=false,push_marketing=false,email_product=false,email_marketing=false,updated_at=clock_timestamp() where user_id=$1' using u;
  end if;
  update sdi_private.deletion_requests set state='processing',purge_after=clock_timestamp()+interval '30 days',revision=deletion_requests.revision+1 where id=d.id;
  return jsonb_build_object('action','prepared','request',d.id,'purge_after',clock_timestamp()+interval '30 days');
 end if;
 select * into d from sdi_private.deletion_requests where state='processing' and purge_after<=clock_timestamp() and user_id is not null
  order by purge_after for update skip locked limit 1;
 if not found then return jsonb_build_object('action','idle'); end if;
 u:=d.user_id;
 if exists(select 1 from sdi_private.publish_jobs where creator=u and state in('queued','leased','cancel_requested','reconcile','removal_pending')) then blockers:=array_append(blockers,'publishing jobs not settled'); end if;
 if exists(select 1 from sdi_private.removal_jobs r join public.sdi_watch_media m on m.id=r.media_id where m.owner_id=u and r.state in('pending','running','failed')) then blockers:=array_append(blockers,'hosted copies not yet removed'); end if;
 if exists(select 1 from sdi_private.upload_registrations ur join sdi_private.render_reviews rr on rr.id=ur.review_id where rr.creator=u and ur.retirement_authorized_at is null) then blockers:=array_append(blockers,'intake renders not yet retired'); end if;
 if cardinality(blockers)>0 then
  -- Keep waiting for 30 more days, then surface the request for an administrator.
  update sdi_private.deletion_requests set state=case when purge_after<clock_timestamp()-interval '30 days' then 'blocked' else state end,
   blocked_reason=left(array_to_string(blockers,'; '),500),revision=deletion_requests.revision+1 where id=d.id;
  return jsonb_build_object('action',case when d.purge_after<clock_timestamp()-interval '30 days' then 'blocked' else 'waiting' end,'request',d.id,'reasons',to_jsonb(blockers));
 end if;
 -- Expire remaining private artifacts; the intake host deletes files after retire.
 update sdi_private.render_artifacts a set expires_at=least(a.expires_at,clock_timestamp()) from sdi_private.render_reviews r where r.id=a.review_id and r.creator=u;
 -- Audit tables are append-only (security-audit-integrity.sql); only this purge,
 -- inside this transaction, may remove the departing member's audit rows.
 perform pg_catalog.set_config('sdi.audit_purge','on',true);
 -- Consent proof outlives the account as a pseudonymous record (#262): no identity
 -- columns, only a digest of the former account id, kept until retain_until.
 if to_regclass('sdi_private.consent_records') is not null then
  execute 'insert into sdi_private.consent_retention(subject_digest,policy,version,source,accepted_at,withdrawn_at,retain_until)
   select encode(extensions.digest(c.user_id::text,''sha256''),''hex''),c.policy,c.version,c.source,c.accepted_at,coalesce(c.withdrawn_at,clock_timestamp()),
    clock_timestamp()+make_interval(days=>(select s.consent_proof_days from sdi_private.retention_settings s))
   from sdi_private.consent_records c where c.user_id=$1' using u;
 end if;
 -- Dependency-ordered purge. Public renditions are anonymised, not deleted, because
 -- completed matchups and evidence reference them; their hosted copies are gone.
 delete from sdi_private.feed_curation_audit where post in(select id from sdi_private.feed_posts where creator=u);
 delete from sdi_private.publishing_audit where job_id in(select id from sdi_private.publish_jobs where creator=u);
 delete from sdi_private.publish_jobs where creator=u;
 delete from sdi_private.preview_permits where review_id in(select id from sdi_private.render_reviews where creator=u);
 delete from sdi_private.upload_registrations where review_id in(select id from sdi_private.render_reviews where creator=u);
 delete from sdi_private.render_artifacts where review_id in(select id from sdi_private.render_reviews where creator=u);
 delete from sdi_private.render_decisions where review_id in(select id from sdi_private.render_reviews where creator=u);
 update public.sdi_watch_media set owner_id=null,approved=false,review_id=null,title='Removed',url='https://removed.invalid/'||id::text where owner_id=u;
 delete from sdi_private.war_appeals where decision_id in(select a.id from sdi_private.war_moderation_audit a join sdi_private.war_matches w on w.id=a.match_id where u in(w.creator,w.opponent));
 delete from sdi_private.war_moderation_audit where match_id in(select id from sdi_private.war_matches where u in(creator,opponent));
 delete from sdi_private.war_reports where match_id in(select id from sdi_private.war_matches where u in(creator,opponent));
 delete from sdi_private.war_results where match_id in(select id from sdi_private.war_matches where u in(creator,opponent));
 delete from sdi_private.room_moderation_audit where room_id in(select id from public.sdi_rooms where owner_id=u);
 delete from sdi_private.room_reports where room_id in(select id from public.sdi_rooms where owner_id=u);
 delete from auth.users where id=u;
 perform pg_catalog.set_config('sdi.audit_purge','',true);
 update sdi_private.deletion_requests set state='completed',completed_at=clock_timestamp(),revision=deletion_requests.revision+1 where id=d.id;
 return jsonb_build_object('action','purged','request',d.id);
end $$;
revoke all on function sdi_private.account_deletion_run() from public,anon,authenticated;
grant execute on function sdi_private.account_deletion_run() to service_role;
create function public.sdi_account_deletion_run() returns jsonb language sql security invoker set search_path='' as $$select sdi_private.account_deletion_run()$$;
revoke all on function public.sdi_account_deletion_run() from public,anon,authenticated;
grant execute on function public.sdi_account_deletion_run() to service_role;

-- Service sweep: removes consent proof whose retention period has ended.
create function sdi_private.consent_retention_sweep() returns integer language plpgsql security definer set search_path='' as $$
declare n integer;
begin
 delete from sdi_private.consent_retention where retain_until<=clock_timestamp();
 get diagnostics n=row_count; return n;
end $$;
revoke all on function sdi_private.consent_retention_sweep() from public,anon,authenticated;
grant execute on function sdi_private.consent_retention_sweep() to service_role;
create function public.sdi_consent_retention_sweep() returns integer language sql security invoker set search_path='' as $$select sdi_private.consent_retention_sweep()$$;
revoke all on function public.sdi_consent_retention_sweep() from public,anon,authenticated;
grant execute on function public.sdi_consent_retention_sweep() to service_role;
commit;

-- ===== billing-finance.sql (sha256 bd6f5f508bb1dbd8) =====
-- Unapplied candidate. Install after account-lifecycle.sql (needs billing.sql,
-- admin-hardening.sql for admin_gate and agent-controls.sql for agent costs).
-- Finance ledger operations for #254/#255: manually recorded or imported expenses
-- and corrections with a source and a reconciliation flag, a reconciliation report
-- that names concrete discrepancies, period summaries that keep cash movements
-- (payouts) apart from recognized records (charges, refunds, fees) and expenses, a
-- CSV-ready export, and agent cost against the configured caps (#248/#263).
-- Every amount is a provider-reported or operator-entered record in minor units.
-- Nothing here computes an available balance, an estimate or a forecast, and
-- nothing spends. Reads need the finance capability with MFA; every mutation also
-- needs a recent MFA step-up and is written to finance_audit.
begin;
alter table sdi_private.finance_ledger add column source text not null default 'provider' check(source in('provider','manual','import'));
alter table sdi_private.finance_ledger add column reconciled boolean not null default false;
alter table sdi_private.finance_ledger add column recorded_by uuid references auth.users(id) on delete set null;
alter table sdi_private.finance_ledger add column corrects uuid references sdi_private.finance_ledger(id);
create index finance_ledger_period on sdi_private.finance_ledger(occurred_at desc,provider,currency,kind);

-- Convention: money in is positive, money out is negative. Charges and payouts are
-- positive, refunds, fees and expenses are negative. Expenses are entered as a
-- positive amount and stored negative so operators cannot invert them by mistake.
create function sdi_private.finance_record(action text,ref text default null,kind text default null,amount_minor bigint default null,
 currency text default null,occurred_at timestamptz default null,note text default '',reason text default '',entry uuid default null,
 rows jsonb default '[]') returns jsonb
language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare denial jsonb; original sdi_private.finance_ledger; inserted uuid; possible boolean; item jsonb; added integer:=0; duplicates integer:=0; rejected jsonb:='[]';
begin
 denial:=sdi_private.admin_gate('finance_record.'||coalesce(action,'?'),'finance',true,30);
 if denial is not null then return denial; end if;
 if reason is null or length(trim(reason)) not between 1 and 2000 then return jsonb_build_object('error','A reason of at most 2000 characters is required.'); end if;
 if action='expense' then
  if ref is null or length(trim(ref)) not between 1 and 200 or amount_minor is null or amount_minor<=0 or amount_minor>=10^15
   or currency is null or currency !~ '^[A-Z]{3}$' or occurred_at is null or occurred_at>clock_timestamp()+interval '1 day' or note is null or length(note)>500 then
   return jsonb_build_object('error','Provide a provider reference, a positive amount in minor units, an ISO currency and the date.'); end if;
  if exists(select 1 from sdi_private.finance_ledger l where l.provider='manual' and l.provider_ref=trim(ref) and l.kind='expense') then
   return jsonb_build_object('status','duplicate','ref',trim(ref)); end if;
  possible:=exists(select 1 from sdi_private.finance_ledger l where l.kind='expense' and l.currency=finance_record.currency and l.amount_minor=-finance_record.amount_minor
   and l.occurred_at::date=finance_record.occurred_at::date);
  insert into sdi_private.finance_ledger(provider,provider_ref,kind,amount_minor,currency,occurred_at,note,source,recorded_by)
  values('manual',trim(ref),'expense',-amount_minor,currency,occurred_at,coalesce(note,''),'manual',auth.uid()) returning id into inserted;
  insert into sdi_private.finance_audit(actor,action,reason) values(auth.uid(),'expense '||trim(ref)||' '||(-amount_minor)||' '||currency,trim(reason));
  return jsonb_build_object('status','recorded','entry',inserted,'possible_duplicate',possible);
 elsif action='import' then
  if jsonb_typeof(rows)<>'array' or jsonb_array_length(rows) not between 1 and 500 then return jsonb_build_object('error','Import 1 to 500 rows.'); end if;
  for item in select * from jsonb_array_elements(rows) loop
   if jsonb_typeof(item)<>'object' or length(coalesce(item->>'ref',''))not between 1 and 200 or coalesce(item->>'kind','') not in('expense','fee','adjustment')
    or coalesce(item->>'amount_minor','') !~ '^-?[0-9]{1,15}$' or coalesce(item->>'currency','') !~ '^[A-Z]{3}$'
    or (item->>'occurred_at') is null or length(coalesce(item->>'note',''))>500 then
    rejected:=rejected||jsonb_build_array(left(item::text,200)); continue; end if;
   begin
    insert into sdi_private.finance_ledger(provider,provider_ref,kind,amount_minor,currency,occurred_at,note,source,recorded_by)
    values('manual',item->>'ref',item->>'kind',(item->>'amount_minor')::bigint,item->>'currency',(item->>'occurred_at')::timestamptz,coalesce(item->>'note',''),'import',auth.uid())
    on conflict(provider,provider_ref,kind) do nothing;
    if found then added:=added+1; else duplicates:=duplicates+1; end if;
   exception when invalid_datetime_format or datetime_field_overflow then
    rejected:=rejected||jsonb_build_array(left(item::text,200));
   end;
  end loop;
  insert into sdi_private.finance_audit(actor,action,reason) values(auth.uid(),'import added='||added||' duplicates='||duplicates||' rejected='||jsonb_array_length(rejected),trim(reason));
  return jsonb_build_object('status','imported','added',added,'duplicates',duplicates,'rejected',rejected);
 elsif action='correct' then
  if entry is null or amount_minor is null or amount_minor=0 or abs(amount_minor)>=10^15 or note is null or length(trim(note)) not between 1 and 500 then
   return jsonb_build_object('error','Select the entry, the signed correction amount and a note.'); end if;
  select * into original from sdi_private.finance_ledger where id=entry;
  if not found then return jsonb_build_object('error','Entry unavailable.'); end if;
  insert into sdi_private.finance_ledger(provider,provider_ref,kind,amount_minor,currency,occurred_at,note,source,recorded_by,corrects)
  values('manual','correction:'||original.id::text,'adjustment',amount_minor,original.currency,clock_timestamp(),trim(note),'manual',auth.uid(),original.id)
  on conflict(provider,provider_ref,kind) do nothing returning id into inserted;
  if inserted is null then return jsonb_build_object('status','duplicate','entry',original.id); end if;
  insert into sdi_private.finance_audit(actor,action,reason) values(auth.uid(),'correct '||original.id||' by '||amount_minor||' '||original.currency,trim(reason));
  return jsonb_build_object('status','recorded','entry',inserted);
 elsif action='reconcile' then
  if entry is null then return jsonb_build_object('error','Select the entry.'); end if;
  update sdi_private.finance_ledger set reconciled=true where id=entry;
  if not found then return jsonb_build_object('error','Entry unavailable.'); end if;
  insert into sdi_private.finance_audit(actor,action,reason) values(auth.uid(),'reconcile '||entry,trim(reason));
  return jsonb_build_object('status','confirmed');
 end if;
 return jsonb_build_object('error','Unsupported finance operation.');
end $$;
revoke all on function sdi_private.finance_record(text,text,text,bigint,text,timestamptz,text,text,uuid,jsonb) from public,anon;
grant execute on function sdi_private.finance_record(text,text,text,bigint,text,timestamptz,text,text,uuid,jsonb) to authenticated;
create function public.sdi_finance_record(action text,ref text default null,kind text default null,amount_minor bigint default null,
 currency text default null,occurred_at timestamptz default null,note text default '',reason text default '',entry uuid default null,
 rows jsonb default '[]') returns jsonb language sql security invoker set search_path='' as $$
 select sdi_private.finance_record(action,ref,kind,amount_minor,currency,occurred_at,note,reason,entry,rows)$$;
revoke all on function public.sdi_finance_record(text,text,text,bigint,text,timestamptz,text,text,uuid,jsonb) from public,anon;
grant execute on function public.sdi_finance_record(text,text,text,bigint,text,timestamptz,text,text,uuid,jsonb) to authenticated;

create function sdi_private.finance_report(action text,period_start timestamptz default null,period_end timestamptz default null,
 provider text default null,currency text default null,page integer default 0) returns jsonb
language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare denial jsonb; p0 timestamptz; p1 timestamptz; items jsonb; discrepancies jsonb:='[]'; label constant text:=
 'Provider-reported and operator-recorded entries in minor units. Not an available balance; no estimate or forecast is included. Apple proceeds appear only when imported from App Store Connect reports.';
begin
 denial:=sdi_private.admin_gate('finance_report.'||coalesce(action,'?'),'finance',false,60);
 if denial is not null then return denial; end if;
 p1:=coalesce(period_end,clock_timestamp()); p0:=coalesce(period_start,p1-interval '90 days');
 if p1<=p0 or p1-p0>interval '400 days' then return jsonb_build_object('error','Choose a period of at most 400 days.'); end if;
 if page is null or page not between 0 and 49 then return jsonb_build_object('error','Invalid page.'); end if;
 if finance_report.provider is not null and finance_report.provider not in('apple','stripe','manual') then return jsonb_build_object('error','Unknown provider.'); end if;
 if action='reconciliation' then
  select coalesce(jsonb_agg(row_to_json(t) order by t.provider,t.currency,t.kind),'[]'::jsonb) into items from (
   select l.provider,l.currency,l.kind,l.source,sum(l.amount_minor) as amount_minor,count(*) as entries,count(*) filter(where not l.reconciled) as unreconciled
   from sdi_private.finance_ledger l where l.occurred_at>=p0 and l.occurred_at<p1 and (finance_report.provider is null or l.provider=finance_report.provider) and (finance_report.currency is null or l.currency=finance_report.currency)
   group by l.provider,l.currency,l.kind,l.source) t;
  -- 1. Stripe subscriptions updated in the period without any charge record linked to them.
  discrepancies:=discrepancies||coalesce((select jsonb_agg(jsonb_build_object('kind','subscription_without_charge','subscription',s.id,'provider',s.provider,'status',s.status,'paid_through',s.paid_through))
   from sdi_private.subscriptions s where s.provider='stripe' and s.status in('active','trialing','grace','past_due') and s.last_event_at>=p0 and s.last_event_at<p1
   and not exists(select 1 from sdi_private.finance_ledger l where l.subscription_id=s.id and l.kind='charge')),'[]'::jsonb);
  -- 2. Charges that no subscription explains.
  discrepancies:=discrepancies||coalesce((select jsonb_agg(jsonb_build_object('kind','charge_without_subscription','entry',l.id,'provider',l.provider,'ref',l.provider_ref,'amount_minor',l.amount_minor,'currency',l.currency))
   from sdi_private.finance_ledger l where l.kind='charge' and l.subscription_id is null and l.occurred_at>=p0 and l.occurred_at<p1),'[]'::jsonb);
  -- 3. Refunds larger than the charges recorded for the same subscription.
  discrepancies:=discrepancies||coalesce((select jsonb_agg(jsonb_build_object('kind','refund_exceeds_charges','subscription',t.subscription_id,'charged',t.charged,'refunded',t.refunded,'currency',t.currency))
   from (select l.subscription_id,l.currency,sum(l.amount_minor) filter(where l.kind='charge') as charged,-sum(l.amount_minor) filter(where l.kind='refund') as refunded
    from sdi_private.finance_ledger l where l.subscription_id is not null and l.occurred_at<p1 group by l.subscription_id,l.currency) t
   where coalesce(t.refunded,0)>coalesce(t.charged,0)),'[]'::jsonb);
  -- 4. Provider events that errored or were never processed.
  discrepancies:=discrepancies||coalesce((select jsonb_agg(jsonb_build_object('kind',case when e.outcome='error' then 'event_error' else 'event_unprocessed' end,'event',e.id,'provider',e.provider,'event_type',e.event_type,'note',e.note,'received_at',e.received_at))
   from sdi_private.provider_events e where e.received_at>=p0 and e.received_at<p1 and (e.outcome='error' or (e.processed_at is null and e.received_at<clock_timestamp()-interval '1 hour'))),'[]'::jsonb);
  -- 5. Same provider, kind, amount, currency and day under different references.
  discrepancies:=discrepancies||coalesce((select jsonb_agg(jsonb_build_object('kind','possible_duplicate','provider',t.provider,'ledger_kind',t.kind,'amount_minor',t.amount_minor,'currency',t.currency,'day',t.day,'refs',t.refs))
   from (select l.provider,l.kind,l.amount_minor,l.currency,l.occurred_at::date as day,jsonb_agg(l.provider_ref order by l.provider_ref) as refs
    from sdi_private.finance_ledger l where l.occurred_at>=p0 and l.occurred_at<p1 and l.kind<>'adjustment' group by 1,2,3,4,5 having count(distinct l.provider_ref)>1) t),'[]'::jsonb);
  -- 6. Manual or imported rows nobody reconciled within 30 days.
  discrepancies:=discrepancies||coalesce((select jsonb_agg(jsonb_build_object('kind','manual_unreconciled','entry',l.id,'ref',l.provider_ref,'ledger_kind',l.kind,'amount_minor',l.amount_minor,'currency',l.currency,'occurred_at',l.occurred_at))
   from sdi_private.finance_ledger l where l.source in('manual','import') and not l.reconciled and l.occurred_at>=p0 and l.occurred_at<p1 and l.created_at<clock_timestamp()-interval '30 days'),'[]'::jsonb);
  return jsonb_build_object('period_start',p0,'period_end',p1,'totals',items,'discrepancies',discrepancies,'discrepancy_count',jsonb_array_length(discrepancies),
   'subscriptions',(select coalesce(jsonb_object_agg(t.status,t.n),'{}'::jsonb) from (select s.status,count(*) as n from sdi_private.subscriptions s group by s.status) t),
   'cancelling_at_period_end',(select count(*) from sdi_private.subscriptions s where s.cancel_at_period_end and s.status in('active','trialing','grace','past_due')),
   'lapsed_within_grace',(select count(*) from sdi_private.subscriptions s where s.status in('active','trialing','grace','past_due') and s.paid_through<=clock_timestamp() and s.paid_through>clock_timestamp()-interval '16 days'),
   'entitled_accounts',(select count(distinct user_id) from sdi_private.entitlements),'label',label);
 elsif action='period_summary' then
  select coalesce(jsonb_agg(row_to_json(t) order by t.month,t.provider,t.currency,t.bucket),'[]'::jsonb) into items from (
   select date_trunc('month',l.occurred_at)::date as month,l.provider,l.currency,
    case l.kind when 'payout' then 'cash_movement' when 'expense' then 'expense' else 'recognized_record' end as bucket,l.kind,
    sum(l.amount_minor) as amount_minor,count(*) as entries
   from sdi_private.finance_ledger l where l.occurred_at>=p0 and l.occurred_at<p1 and (finance_report.provider is null or l.provider=finance_report.provider) and (finance_report.currency is null or l.currency=finance_report.currency)
   group by 1,2,3,4,5) t;
  return jsonb_build_object('period_start',p0,'period_end',p1,'rows',items,'buckets',jsonb_build_array('recognized_record','cash_movement','expense'),'label',label);
 elsif action='export' then
  select coalesce(jsonb_agg(row_to_json(t)),'[]'::jsonb) into items from (
   select l.id,l.occurred_at,l.provider,l.provider_ref,l.kind,l.amount_minor,l.currency,l.source,l.reconciled,l.subscription_id,l.event_id,l.corrects,l.note
   from sdi_private.finance_ledger l where l.occurred_at>=p0 and l.occurred_at<p1 and (finance_report.provider is null or l.provider=finance_report.provider) and (finance_report.currency is null or l.currency=finance_report.currency)
   order by l.occurred_at,l.id limit 1000 offset page*1000) t;
  return jsonb_build_object('period_start',p0,'period_end',p1,'columns',jsonb_build_array('id','occurred_at','provider','provider_ref','kind','amount_minor','currency','source','reconciled','subscription_id','event_id','corrects','note'),
   'rows',items,'has_more',jsonb_array_length(items)=1000,'label',label);
 elsif action='agent_costs' then
  select coalesce(jsonb_agg(row_to_json(t) order by t.key),'[]'::jsonb) into items from (
   select a.key,a.title,a.monthly_cost_cap_minor,a.paused,
    (select coalesce(sum(r.cost_minor),0) from sdi_private.agent_runs r where r.agent_key=a.key and r.started_at>=date_trunc('month',clock_timestamp())) as cost_month_minor,
    (select count(*) from sdi_private.agent_runs r where r.agent_key=a.key and r.state='failed' and r.started_at>=date_trunc('month',clock_timestamp())) as failed_month
   from sdi_private.agents a) t;
  return jsonb_build_object('agents',items,'label','Costs are the amounts agents reported per run in minor units against configured caps; caps are configuration, not spending.');
 end if;
 return jsonb_build_object('error','Unsupported finance report.');
end $$;
revoke all on function sdi_private.finance_report(text,timestamptz,timestamptz,text,text,integer) from public,anon;
grant execute on function sdi_private.finance_report(text,timestamptz,timestamptz,text,text,integer) to authenticated;
create function public.sdi_finance_report(action text,period_start timestamptz default null,period_end timestamptz default null,
 provider text default null,currency text default null,page integer default 0) returns jsonb language sql security invoker set search_path='' as $$
 select sdi_private.finance_report(action,period_start,period_end,provider,currency,page)$$;
revoke all on function public.sdi_finance_report(text,timestamptz,timestamptz,text,text,integer) from public,anon;
grant execute on function public.sdi_finance_report(text,timestamptz,timestamptz,text,text,integer) to authenticated;
commit;

-- ===== consent-versions.sql (sha256 fc93df4b84c9e442) =====
-- Unapplied candidate. Install after billing-finance.sql (needs admin-hardening.sql,
-- creator-reviews.sql and publishing-withdrawal.sql). Consent-version registry for
-- #174, #261, #273 and #262: the owner publishes policy versions (terms, privacy,
-- publishing permission, marketing permission, content/age policy); members accept
-- exactly the current version from a named surface; publishing and marketing consent
-- are separate and separately withdrawable; a publishing withdrawal clears the
-- consent on every render of that creator, which the existing trigger turns into
-- job cancellation, removal or reconciliation. The intake service verifies the
-- submitted consent version with consent_verify before registering a render. The
-- content policy carries its age rule as metadata the owner sets (min_age); the
-- member records an attestation, the server never guesses an age.
begin;
create table sdi_private.policy_versions (
 policy text not null check(policy in('terms','privacy','publishing','marketing','content')),
 version text not null check(version ~ '^[a-z0-9][a-z0-9.-]{0,99}$'),
 summary text not null check(length(summary) between 1 and 2000),
 metadata jsonb not null default '{}' check(jsonb_typeof(metadata)='object'),
 effective_at timestamptz not null, created_by uuid references auth.users(id) on delete set null,
 created_at timestamptz not null default clock_timestamp(), primary key(policy,version)
);
create table sdi_private.consent_records (
 id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade,
 policy text not null, version text not null, source text not null check(source in('ios','android','web')),
 attestation jsonb not null default '{}' check(jsonb_typeof(attestation)='object'),
 accepted_at timestamptz not null default clock_timestamp(), withdrawn_at timestamptz,
 foreign key(policy,version) references sdi_private.policy_versions(policy,version), unique(user_id,policy,version)
);
create table sdi_private.consent_audit (
 id uuid primary key default gen_random_uuid(), actor uuid references auth.users(id) on delete set null, action text not null,
 policy text, version text, reason text not null default '', created_at timestamptz not null default clock_timestamp()
);
alter table sdi_private.policy_versions enable row level security;
alter table sdi_private.consent_records enable row level security;
alter table sdi_private.consent_audit enable row level security;
revoke all on sdi_private.policy_versions,sdi_private.consent_records,sdi_private.consent_audit from public,anon,authenticated;
create index consent_records_user on sdi_private.consent_records(user_id,policy);

create function sdi_private.policy_current(policy text) returns text language sql stable security definer set search_path='' as $$
 select v.version from sdi_private.policy_versions v where v.policy=policy_current.policy and v.effective_at<=clock_timestamp()
 order by v.effective_at desc,v.created_at desc limit 1
$$;
-- True when the subject holds an unwithdrawn acceptance of the given version (or of
-- the current version when none is given). A content policy with min_age also needs
-- the recorded attestation.
create function sdi_private.consent_current(subject uuid,policy text,version text default null) returns boolean
language sql stable security definer set search_path='' as $$
 select exists(select 1 from sdi_private.consent_records c join sdi_private.policy_versions v on v.policy=c.policy and v.version=c.version
  where c.user_id=subject and c.policy=consent_current.policy and c.withdrawn_at is null
  and c.version=coalesce(consent_current.version,sdi_private.policy_current(consent_current.policy))
  and (v.metadata->>'min_age' is null or (c.attestation->>'age_ok')='true'))
$$;
revoke all on function sdi_private.policy_current(text),sdi_private.consent_current(uuid,text,text) from public,anon,authenticated;

create function sdi_private.consent_action(action text,policy text default null,version text default null,source text default null,
 attestation jsonb default '{}',summary text default null,metadata jsonb default '{}',effective_at timestamptz default null,reason text default '')
returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare actor uuid:=auth.uid(); items jsonb; current_version text; denial jsonb; affected integer;
begin
 if action='current' then
  select coalesce(jsonb_agg(jsonb_build_object('policy',t.policy,'version',t.version,'summary',t.summary,'metadata',t.metadata,'effective_at',t.effective_at) order by t.policy),'[]'::jsonb)
   into items from (select distinct on (v.policy) v.* from sdi_private.policy_versions v where v.effective_at<=clock_timestamp() order by v.policy,v.effective_at desc,v.created_at desc) t;
  return jsonb_build_object('policies',items);
 end if;
 if action in('mine','accept','withdraw') then
  if actor is null or not sdi_private.account_active() or not exists(select 1 from auth.users where id=actor and not is_anonymous) then
   return jsonb_build_object('error','Sign in with a full account.'); end if;
  if action='mine' then
   select coalesce(jsonb_agg(jsonb_build_object('policy',c.policy,'version',c.version,'source',c.source,'accepted_at',c.accepted_at,'withdrawn_at',c.withdrawn_at,
    'current',c.version=sdi_private.policy_current(c.policy) and c.withdrawn_at is null) order by c.policy,c.accepted_at desc),'[]'::jsonb) into items
    from sdi_private.consent_records c where c.user_id=actor;
   return jsonb_build_object('consents',items,'publishing_current',sdi_private.consent_current(actor,'publishing'),'marketing_current',sdi_private.consent_current(actor,'marketing'));
  end if;
  if policy is null or policy not in('terms','privacy','publishing','marketing','content') then return jsonb_build_object('error','Unknown policy.'); end if;
  if action='accept' then
   current_version:=sdi_private.policy_current(policy);
   if current_version is null then return jsonb_build_object('error','This policy has not been published yet.'); end if;
   if version is distinct from current_version then return jsonb_build_object('error','Policy version changed. Review the current version before accepting.','current',current_version); end if;
   if source is null or source not in('ios','android','web') then return jsonb_build_object('error','Record the surface where consent was given.'); end if;
   if exists(select 1 from sdi_private.policy_versions v where v.policy=consent_action.policy and v.version=current_version and v.metadata->>'min_age' is not null)
    and (attestation->>'age_ok') is distinct from 'true' then
    return jsonb_build_object('error','Confirm you meet the minimum age in the content policy.'); end if;
   insert into sdi_private.consent_records(user_id,policy,version,source,attestation) values(actor,policy,current_version,source,coalesce(attestation,'{}'))
   on conflict(user_id,policy,version) do update set withdrawn_at=null,accepted_at=clock_timestamp(),source=excluded.source,attestation=excluded.attestation;
   insert into sdi_private.consent_audit(actor,action,policy,version) values(actor,'accept',policy,current_version);
   return jsonb_build_object('status','accepted','policy',policy,'version',current_version);
  end if;
  -- withdraw
  if policy not in('publishing','marketing') then return jsonb_build_object('error','Only publishing and marketing permissions can be withdrawn here; terms, privacy and content policies end with account deletion.'); end if;
  update sdi_private.consent_records set withdrawn_at=clock_timestamp() where user_id=actor and policy=consent_action.policy and withdrawn_at is null;
  get diagnostics affected=row_count;
  if policy='publishing' then
   -- Every render of this creator loses its consent; the publishing triggers cancel
   -- or withdraw jobs that have not published and send live copies to removal.
   update sdi_private.render_reviews set consent_version='',destinations=array[]::text[],state='pending' where creator=actor and length(consent_version)>0;
  end if;
  insert into sdi_private.consent_audit(actor,action,policy) values(actor,'withdraw',policy);
  return jsonb_build_object('status','withdrawn','policy',policy,'records',affected);
 end if;
 if action in('publish','list','audit') then
  denial:=sdi_private.admin_gate('consent_action.'||action,'users',action='publish',30);
  if denial is not null then return denial; end if;
  if action='list' then
   select coalesce(jsonb_agg(row_to_json(v) order by v.policy,v.effective_at desc),'[]'::jsonb) into items from sdi_private.policy_versions v;
   return jsonb_build_object('versions',items,'acceptances',(select coalesce(jsonb_object_agg(t.k,t.n),'{}'::jsonb) from (select c.policy||':'||c.version as k,count(*) as n from sdi_private.consent_records c where c.withdrawn_at is null group by 1) t));
  elsif action='audit' then
   select coalesce(jsonb_agg(row_to_json(a) order by a.created_at desc),'[]'::jsonb) into items from (select * from sdi_private.consent_audit order by created_at desc limit 200) a;
   return jsonb_build_object('audit',items);
  end if;
  if not exists(select 1 from sdi_private.admin_roles where user_id=actor and enabled and owner) then return jsonb_build_object('error','Owner permission required to publish a policy version.'); end if;
  if policy is null or policy not in('terms','privacy','publishing','marketing','content') or version is null or version !~ '^[a-z0-9][a-z0-9.-]{0,99}$'
   or summary is null or length(trim(summary)) not between 1 and 2000 or metadata is null or jsonb_typeof(metadata)<>'object' or reason is null or length(trim(reason)) not between 1 and 2000 then
   return jsonb_build_object('error','Policy, version id, summary, metadata object and reason required.'); end if;
  if policy='content' and coalesce(metadata->>'min_age','') !~ '^[0-9]{1,2}$' then return jsonb_build_object('error','The content policy needs min_age in its metadata (an owner and legal decision).'); end if;
  insert into sdi_private.policy_versions(policy,version,summary,metadata,effective_at,created_by) values(policy,version,trim(summary),metadata,coalesce(effective_at,clock_timestamp()),actor)
  on conflict(policy,version) do nothing;
  if not found then return jsonb_build_object('error','That version id already exists; publish a new version instead of editing history.'); end if;
  insert into sdi_private.consent_audit(actor,action,policy,version,reason) values(actor,'publish',policy,version,trim(reason));
  return jsonb_build_object('status','published','policy',policy,'version',version);
 end if;
 return jsonb_build_object('error','Unsupported consent operation.');
end $$;
revoke all on function sdi_private.consent_action(text,text,text,text,jsonb,text,jsonb,timestamptz,text) from public,anon;
grant execute on function sdi_private.consent_action(text,text,text,text,jsonb,text,jsonb,timestamptz,text) to authenticated;
create function public.sdi_consent_action(action text,policy text default null,version text default null,source text default null,
 attestation jsonb default '{}',summary text default null,metadata jsonb default '{}',effective_at timestamptz default null,reason text default '')
returns jsonb language sql security invoker set search_path='' as $$select sdi_private.consent_action(action,policy,version,source,attestation,summary,metadata,effective_at,reason)$$;
revoke all on function public.sdi_consent_action(text,text,text,text,jsonb,text,jsonb,timestamptz,text) from public,anon;
grant execute on function public.sdi_consent_action(text,text,text,text,jsonb,text,jsonb,timestamptz,text) to authenticated;

-- Service check before a render is registered: the submitted publishing consent
-- version must be the creator's current, unwithdrawn acceptance, and when a content
-- policy is published the creator must also hold its current attested acceptance.
create function sdi_private.consent_verify(subject uuid,version text) returns jsonb language plpgsql security definer set search_path='' as $$
begin
 if subject is null or version is null then return jsonb_build_object('allowed',false,'reason','Creator and consent version required.'); end if;
 if sdi_private.policy_current('publishing') is null then return jsonb_build_object('allowed',false,'reason','No publishing policy is published.'); end if;
 if version<>sdi_private.policy_current('publishing') then return jsonb_build_object('allowed',false,'reason','Publishing terms changed. Confirm the current permissions before submitting.'); end if;
 if not sdi_private.consent_current(subject,'publishing',version) then return jsonb_build_object('allowed',false,'reason','Current publishing permission not recorded for this account.'); end if;
 if sdi_private.policy_current('content') is not null and not sdi_private.consent_current(subject,'content') then
  return jsonb_build_object('allowed',false,'reason','Current content policy acceptance and age confirmation required.'); end if;
 return jsonb_build_object('allowed',true,'publishing_version',version,'content_version',sdi_private.policy_current('content'),'marketing',sdi_private.consent_current(subject,'marketing'));
end $$;
revoke all on function sdi_private.consent_verify(uuid,text) from public,anon,authenticated;
grant execute on function sdi_private.consent_verify(uuid,text) to service_role;
create function public.sdi_consent_verify(subject uuid,version text) returns jsonb language sql security invoker set search_path='' as $$select sdi_private.consent_verify(subject,version)$$;
revoke all on function public.sdi_consent_verify(uuid,text) from public,anon,authenticated;
grant execute on function public.sdi_consent_verify(uuid,text) to service_role;
commit;

-- ===== notifications.sql (sha256 4cc2ee009f32999b) =====
-- Unapplied candidate. Install after consent-versions.sql (needs admin-hardening.sql,
-- billing.sql for the subscriber audience and pgcrypto in extensions).
-- Notification preferences, device registrations, admin-composed announcements and
-- email suppression for #290 and #276. Transactional (account/service) notices are
-- always allowed; product and marketing notices are off until the member opts in,
-- with a per-member daily cap. Administrators with the users capability compose,
-- schedule and cancel; the service fans out deliveries and reports results. No push
-- or email transport lives here: the service worker takes the claimed batch to the
-- configured APNs/FCM/SMTP adapter, and during development to a sink only.
begin;
create table sdi_private.notification_preferences (
 user_id uuid primary key references auth.users(id) on delete cascade,
 push_product boolean not null default false, push_marketing boolean not null default false,
 email_product boolean not null default false, email_marketing boolean not null default false,
 daily_cap integer not null default 2 check(daily_cap between 0 and 10), updated_at timestamptz not null default clock_timestamp()
);
create table sdi_private.device_tokens (
 id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade,
 platform text not null check(platform in('ios','android')), environment text not null check(environment in('sandbox','production')),
 device_token text not null check(length(device_token) between 32 and 4096), created_at timestamptz not null default clock_timestamp(),
 last_seen_at timestamptz not null default clock_timestamp(), revoked_at timestamptz, unique(device_token)
);
create table sdi_private.announcements (
 id uuid primary key default gen_random_uuid(), title text not null check(length(title) between 1 and 120), body text not null check(length(body) between 1 and 1000),
 category text not null check(category in('transactional','product','marketing')), audience text not null check(audience in('all','subscribers')),
 channels text[] not null check(channels<>'{}' and channels <@ array['push','in_app']), scheduled_for timestamptz,
 state text not null default 'draft' check(state in('draft','scheduled','sending','sent','cancelled')),
 created_by uuid not null references auth.users(id), revision bigint not null default 1,
 queued_count integer not null default 0, sent_count integer not null default 0, failed_count integer not null default 0, suppressed_count integer not null default 0,
 created_at timestamptz not null default clock_timestamp(), updated_at timestamptz not null default clock_timestamp()
);
create table sdi_private.announcement_deliveries (
 id uuid primary key default gen_random_uuid(), announcement_id uuid not null references sdi_private.announcements(id) on delete cascade,
 user_id uuid not null references auth.users(id) on delete cascade, channel text not null check(channel in('push','in_app')),
 device_id uuid references sdi_private.device_tokens(id) on delete set null,
 state text not null default 'queued' check(state in('queued','sent','failed','suppressed','read')), reason text not null default '' check(length(reason)<=200),
 claimed_at timestamptz, created_at timestamptz not null default clock_timestamp(), updated_at timestamptz not null default clock_timestamp(),
 unique nulls not distinct (announcement_id,user_id,channel,device_id)
);
create table sdi_private.announcement_audit (
 id uuid primary key default gen_random_uuid(), actor uuid not null references auth.users(id), announcement_id uuid, action text not null,
 reason text not null check(length(reason) between 1 and 2000), created_at timestamptz not null default clock_timestamp()
);
create table sdi_private.email_suppressions (
 email_hash text primary key check(email_hash ~ '^[a-f0-9]{64}$'), reason text not null check(reason in('unsubscribe','bounce','complaint','manual')),
 created_at timestamptz not null default clock_timestamp()
);
alter table sdi_private.notification_preferences enable row level security;
alter table sdi_private.device_tokens enable row level security;
alter table sdi_private.announcements enable row level security;
alter table sdi_private.announcement_deliveries enable row level security;
alter table sdi_private.announcement_audit enable row level security;
alter table sdi_private.email_suppressions enable row level security;
revoke all on sdi_private.notification_preferences,sdi_private.device_tokens,sdi_private.announcements,sdi_private.announcement_deliveries,
 sdi_private.announcement_audit,sdi_private.email_suppressions from public,anon,authenticated;
create index announcement_deliveries_user on sdi_private.announcement_deliveries(user_id,channel,created_at desc);
create index announcement_deliveries_claim on sdi_private.announcement_deliveries(announcement_id,state) where state='queued';

create function sdi_private.email_hash(address text) returns text language sql immutable security definer set search_path='' as $$
 select encode(extensions.digest(lower(trim(address)),'sha256'),'hex')
$$;
revoke all on function sdi_private.email_hash(text) from public,anon,authenticated;

-- Member surface: preferences, devices, in-app inbox.
create function sdi_private.notify_action(action text,payload jsonb default '{}') returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=auth.uid(); prefs sdi_private.notification_preferences; items jsonb; device uuid;
begin
 if actor is null or not sdi_private.account_active() or not exists(select 1 from auth.users where id=actor and not is_anonymous) then
  return jsonb_build_object('error','Sign in with a full account.'); end if;
 if payload is null or jsonb_typeof(payload)<>'object' then return jsonb_build_object('error','Invalid request.'); end if;
 insert into sdi_private.notification_preferences(user_id) values(actor) on conflict do nothing;
 select * into prefs from sdi_private.notification_preferences where user_id=actor;
 if action='preferences' then
  select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'platform',d.platform,'environment',d.environment,'created_at',d.created_at,'last_seen_at',d.last_seen_at) order by d.created_at),'[]'::jsonb)
   into items from sdi_private.device_tokens d where d.user_id=actor and d.revoked_at is null;
  return jsonb_build_object('push_product',prefs.push_product,'push_marketing',prefs.push_marketing,'email_product',prefs.email_product,'email_marketing',prefs.email_marketing,
   'daily_cap',prefs.daily_cap,'transactional','always on for account and service notices','devices',items);
 elsif action='set_preferences' then
  if (payload ? 'daily_cap') and (payload->>'daily_cap') !~ '^(10|[0-9])$' then return jsonb_build_object('error','Daily cap must be 0 to 10.'); end if;
  update sdi_private.notification_preferences set
   push_product=coalesce((payload->>'push_product')::boolean,push_product),push_marketing=coalesce((payload->>'push_marketing')::boolean,push_marketing),
   email_product=coalesce((payload->>'email_product')::boolean,email_product),email_marketing=coalesce((payload->>'email_marketing')::boolean,email_marketing),
   daily_cap=coalesce((payload->>'daily_cap')::integer,daily_cap),updated_at=clock_timestamp() where user_id=actor;
  return jsonb_build_object('status','confirmed');
 elsif action='register_device' then
  if coalesce(payload->>'platform','') not in('ios','android') or coalesce(payload->>'environment','') not in('sandbox','production')
   or length(coalesce(payload->>'token','')) not between 32 and 4096 then return jsonb_build_object('error','Platform, environment and device token required.'); end if;
  if (select count(*) from sdi_private.device_tokens d where d.user_id=actor and d.revoked_at is null and d.device_token<>payload->>'token')>=5 then
   return jsonb_build_object('error','Five devices are already registered. Remove one first.'); end if;
  insert into sdi_private.device_tokens(user_id,platform,environment,device_token) values(actor,payload->>'platform',payload->>'environment',payload->>'token')
  on conflict(device_token) do update set user_id=excluded.user_id,platform=excluded.platform,environment=excluded.environment,last_seen_at=clock_timestamp(),revoked_at=null
  returning id into device;
  return jsonb_build_object('status','confirmed','device',device);
 elsif action='revoke_device' then
  update sdi_private.device_tokens set revoked_at=clock_timestamp() where id=(payload->>'device')::uuid and user_id=actor and revoked_at is null;
  if not found then return jsonb_build_object('error','Device unavailable.'); end if;
  return jsonb_build_object('status','confirmed');
 elsif action='inbox' then
  select coalesce(jsonb_agg(jsonb_build_object('delivery',d.id,'title',a.title,'body',a.body,'category',a.category,'state',d.state,'delivered_at',d.updated_at) order by d.updated_at desc),'[]'::jsonb)
   into items from sdi_private.announcement_deliveries d join sdi_private.announcements a on a.id=d.announcement_id
   where d.user_id=actor and d.channel='in_app' and d.state in('sent','read') and a.state<>'cancelled' limit 50;
  return jsonb_build_object('notices',items,'unread',(select count(*) from sdi_private.announcement_deliveries d where d.user_id=actor and d.channel='in_app' and d.state='sent'));
 elsif action='mark_read' then
  update sdi_private.announcement_deliveries set state='read',updated_at=clock_timestamp() where id=(payload->>'delivery')::uuid and user_id=actor and channel='in_app' and state='sent';
  return jsonb_build_object('status',case when found then 'confirmed' else 'unchanged' end);
 end if;
 return jsonb_build_object('error','Unsupported notification operation.');
exception when invalid_text_representation then
 return jsonb_build_object('error','Invalid request.');
end $$;
revoke all on function sdi_private.notify_action(text,jsonb) from public,anon;
grant execute on function sdi_private.notify_action(text,jsonb) to authenticated;
create function public.sdi_notify_action(action text,payload jsonb default '{}') returns jsonb language sql security invoker set search_path='' as $$select sdi_private.notify_action(action,payload)$$;
revoke all on function public.sdi_notify_action(text,jsonb) from public,anon;
grant execute on function public.sdi_notify_action(text,jsonb) to authenticated;

-- Administrator surface: compose, schedule, cancel, results. Scheduling and
-- cancelling are sensitive (step-up); every change is audited with a reason.
create function sdi_private.announce_admin(action text,announcement uuid default null,revision bigint default null,payload jsonb default '{}',reason text default '')
returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare denial jsonb; a sdi_private.announcements; items jsonb; channel_list text[]; when_at timestamptz;
begin
 denial:=sdi_private.admin_gate('announce_admin.'||coalesce(action,'?'),'users',action in('schedule','cancel'),60);
 if denial is not null then return denial; end if;
 if action='list' then
  select coalesce(jsonb_agg(row_to_json(x) order by x.created_at desc),'[]'::jsonb) into items from (select * from sdi_private.announcements order by created_at desc limit 100) x;
  return jsonb_build_object('announcements',items);
 elsif action='results' then
  select coalesce(jsonb_agg(jsonb_build_object('state',t.state,'channel',t.channel,'count',t.n,'reasons',t.reasons)),'[]'::jsonb) into items from (
   select d.state,d.channel,count(*) as n,jsonb_agg(distinct d.reason) filter(where d.reason<>'') as reasons from sdi_private.announcement_deliveries d where d.announcement_id=announcement group by d.state,d.channel) t;
  return jsonb_build_object('results',items);
 end if;
 if reason is null or length(trim(reason)) not between 1 and 2000 then return jsonb_build_object('error','A reason is required.'); end if;
 if action='compose' then
  select coalesce(array_agg(v order by v),'{}') into channel_list from jsonb_array_elements_text(coalesce(payload->'channels','[]'::jsonb)) v;
  if length(coalesce(payload->>'title','')) not between 1 and 120 or length(coalesce(payload->>'body','')) not between 1 and 1000
   or coalesce(payload->>'category','') not in('transactional','product','marketing') or coalesce(payload->>'audience','') not in('all','subscribers')
   or channel_list='{}' or not channel_list <@ array['push','in_app'] then
   return jsonb_build_object('error','Title (120), body (1000), category, audience and channels required.'); end if;
  insert into sdi_private.announcements(title,body,category,audience,channels,created_by) values(payload->>'title',payload->>'body',payload->>'category',payload->>'audience',channel_list,auth.uid()) returning * into a;
  insert into sdi_private.announcement_audit(actor,announcement_id,action,reason) values(auth.uid(),a.id,'compose',trim(reason));
  return jsonb_build_object('status','draft','announcement',a.id,'revision',a.revision);
 end if;
 select * into a from sdi_private.announcements where id=announcement for update;
 if not found or revision is distinct from a.revision then return jsonb_build_object('error','Announcement changed. Refresh before saving.'); end if;
 if action='schedule' then
  if a.state<>'draft' then return jsonb_build_object('error','Only drafts can be scheduled.'); end if;
  when_at:=coalesce((payload->>'scheduled_for')::timestamptz,clock_timestamp());
  if when_at<clock_timestamp()-interval '1 minute' or when_at>clock_timestamp()+interval '90 days' then return jsonb_build_object('error','Schedule within the next 90 days.'); end if;
  update sdi_private.announcements set state='scheduled',scheduled_for=when_at,revision=revision+1,updated_at=clock_timestamp() where id=a.id;
 elsif action='cancel' then
  if a.state not in('scheduled','sending') then return jsonb_build_object('error','Only scheduled or sending announcements can be cancelled.'); end if;
  update sdi_private.announcements set state='cancelled',revision=revision+1,updated_at=clock_timestamp() where id=a.id;
  update sdi_private.announcement_deliveries set state='suppressed',reason='cancelled',updated_at=clock_timestamp() where announcement_id=a.id and state='queued';
 else return jsonb_build_object('error','Unsupported announcement operation.'); end if;
 insert into sdi_private.announcement_audit(actor,announcement_id,action,reason) values(auth.uid(),a.id,action,trim(reason));
 return jsonb_build_object('status','confirmed','revision',a.revision+1);
exception when invalid_datetime_format or datetime_field_overflow then
 return jsonb_build_object('error','Invalid schedule time.');
end $$;
revoke all on function sdi_private.announce_admin(text,uuid,bigint,jsonb,text) from public,anon;
grant execute on function sdi_private.announce_admin(text,uuid,bigint,jsonb,text) to authenticated;
create function public.sdi_announce_admin(action text,announcement uuid default null,revision bigint default null,payload jsonb default '{}',reason text default '')
returns jsonb language sql security invoker set search_path='' as $$select sdi_private.announce_admin(action,announcement,revision,payload,reason)$$;
revoke all on function public.sdi_announce_admin(text,uuid,bigint,jsonb,text) from public,anon;
grant execute on function public.sdi_announce_admin(text,uuid,bigint,jsonb,text) to authenticated;

-- Service: fan out one due announcement (idempotent) and hand the worker a bounded
-- batch of push deliveries. Preference, audience, account state and daily cap are
-- applied here; the worker only transports.
-- Recipients: full, active accounts; subscribers only when the audience says so.
create function sdi_private.announcement_audience(audience text) returns table(user_id uuid) language sql stable security definer set search_path='' as $$
 select u.id from auth.users u where not u.is_anonymous
 and not exists(select 1 from sdi_private.account_controls c where c.user_id=u.id and c.state<>'active')
 and (audience='all' or exists(select 1 from sdi_private.entitlements e where e.user_id=u.id))
$$;
revoke all on function sdi_private.announcement_audience(text) from public,anon,authenticated;
create function sdi_private.announcement_claim(batch integer default 500) returns jsonb language plpgsql security definer set search_path='' as $$
declare a sdi_private.announcements; items jsonb; n integer;
begin
 if batch is null or batch not between 1 and 1000 then return jsonb_build_object('error','Batch must be 1 to 1000.'); end if;
 select * into a from sdi_private.announcements where state='sending' order by updated_at for update skip locked limit 1;
 if not found then
  select * into a from sdi_private.announcements where state='scheduled' and scheduled_for<=clock_timestamp() order by scheduled_for for update skip locked limit 1;
  if not found then return jsonb_build_object('empty',true); end if;
  update sdi_private.announcements set state='sending',updated_at=clock_timestamp() where id=a.id;
  if 'in_app'=any(a.channels) then
   insert into sdi_private.announcement_deliveries(announcement_id,user_id,channel,state,updated_at)
   select a.id,r.user_id,'in_app','sent',clock_timestamp() from sdi_private.announcement_audience(a.audience) r on conflict do nothing;
  end if;
  if 'push'=any(a.channels) then
   insert into sdi_private.announcement_deliveries(announcement_id,user_id,channel,device_id,state,reason)
   select a.id,r.user_id,'push',d.id,
    case when a.category='product' and not coalesce(p.push_product,false) then 'suppressed'
         when a.category='marketing' and not coalesce(p.push_marketing,false) then 'suppressed'
         when a.category<>'transactional' and (select count(*) from sdi_private.announcement_deliveries x where x.user_id=r.user_id and x.channel='push' and x.state='sent' and x.created_at>=date_trunc('day',clock_timestamp()))>=coalesce(p.daily_cap,2) then 'suppressed'
         else 'queued' end,
    case when a.category='product' and not coalesce(p.push_product,false) then 'product notices off'
         when a.category='marketing' and not coalesce(p.push_marketing,false) then 'marketing notices off'
         when a.category<>'transactional' and (select count(*) from sdi_private.announcement_deliveries x where x.user_id=r.user_id and x.channel='push' and x.state='sent' and x.created_at>=date_trunc('day',clock_timestamp()))>=coalesce(p.daily_cap,2) then 'daily cap'
         else '' end
   from sdi_private.announcement_audience(a.audience) r join sdi_private.device_tokens d on d.user_id=r.user_id and d.revoked_at is null
   left join sdi_private.notification_preferences p on p.user_id=r.user_id on conflict do nothing;
  end if;
  update sdi_private.announcements set queued_count=(select count(*) from sdi_private.announcement_deliveries x where x.announcement_id=a.id and x.state='queued'),
   suppressed_count=(select count(*) from sdi_private.announcement_deliveries x where x.announcement_id=a.id and x.state='suppressed'),updated_at=clock_timestamp() where id=a.id;
 end if;
 with picked as (
  select d.id from sdi_private.announcement_deliveries d where d.announcement_id=a.id and d.channel='push' and d.state='queued'
  and (d.claimed_at is null or d.claimed_at<clock_timestamp()-interval '10 minutes') order by d.created_at limit batch for update skip locked),
 marked as (update sdi_private.announcement_deliveries d set claimed_at=clock_timestamp() from picked where d.id=picked.id returning d.id,d.device_id)
 select coalesce(jsonb_agg(jsonb_build_object('delivery',m.id,'platform',t.platform,'environment',t.environment,'token',t.device_token,'title',a.title,'body',a.body,'category',a.category)),'[]'::jsonb),count(*)
  into items,n from marked m join sdi_private.device_tokens t on t.id=m.device_id;
 if n=0 and not exists(select 1 from sdi_private.announcement_deliveries d where d.announcement_id=a.id and d.state='queued') then
  update sdi_private.announcements set state='sent',sent_count=(select count(*) from sdi_private.announcement_deliveries x where x.announcement_id=a.id and x.state in('sent','read')),
   failed_count=(select count(*) from sdi_private.announcement_deliveries x where x.announcement_id=a.id and x.state='failed'),updated_at=clock_timestamp() where id=a.id;
  return jsonb_build_object('announcement',a.id,'deliveries',items,'complete',true);
 end if;
 return jsonb_build_object('announcement',a.id,'deliveries',items,'complete',false);
end $$;
create function sdi_private.announcement_finish(results jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare item jsonb; ok integer:=0; failed integer:=0;
begin
 if results is null or jsonb_typeof(results)<>'array' or jsonb_array_length(results)>1000 then return jsonb_build_object('error','Results must be an array of at most 1000 items.'); end if;
 for item in select * from jsonb_array_elements(results) loop
  if (item->>'ok')::boolean then
   update sdi_private.announcement_deliveries set state='sent',updated_at=clock_timestamp() where id=(item->>'delivery')::uuid and state='queued';
   if found then ok:=ok+1; end if;
  else
   update sdi_private.announcement_deliveries set state='failed',reason=left(coalesce(item->>'reason',''),200),updated_at=clock_timestamp() where id=(item->>'delivery')::uuid and state='queued';
   if found then failed:=failed+1; end if;
   if item->>'reason' in('unregistered','invalid_token','BadDeviceToken','Unregistered') then
    update sdi_private.device_tokens t set revoked_at=clock_timestamp() from sdi_private.announcement_deliveries d where d.id=(item->>'delivery')::uuid and t.id=d.device_id;
   end if;
  end if;
 end loop;
 return jsonb_build_object('sent',ok,'failed',failed);
exception when invalid_text_representation then
 return jsonb_build_object('error','Malformed results.');
end $$;
-- Email: suppression by hash (unsubscribe, bounce, complaint) and the allowed
-- recipients for one category. Unsubscribe blocks product and marketing only;
-- bounce and complaint block every category. Service role only; the worker holds
-- the addresses transiently and never logs them.
create function sdi_private.email_suppress(address_hash text,reason text) returns boolean language plpgsql security definer set search_path='' as $$
begin
 if address_hash is null or address_hash !~ '^[a-f0-9]{64}$' or reason not in('unsubscribe','bounce','complaint','manual') then return false; end if;
 insert into sdi_private.email_suppressions(email_hash,reason) values(address_hash,reason)
 on conflict(email_hash) do update set reason=case when email_suppressions.reason in('bounce','complaint') then email_suppressions.reason else excluded.reason end;
 return true;
end $$;
create function sdi_private.email_recipients(category text,batch integer default 500,page integer default 0) returns jsonb language plpgsql security definer set search_path='' as $$
declare items jsonb;
begin
 if category not in('transactional','product','marketing') or batch not between 1 and 1000 or page not between 0 and 999 then return jsonb_build_object('error','Category, batch and page required.'); end if;
 select coalesce(jsonb_agg(jsonb_build_object('user_id',u.id,'email',u.email,'email_hash',sdi_private.email_hash(u.email))),'[]'::jsonb) into items from (
  select u.id,u.email from auth.users u left join sdi_private.notification_preferences p on p.user_id=u.id
  where not u.is_anonymous and u.email is not null and u.email_confirmed_at is not null
  and not exists(select 1 from sdi_private.account_controls c where c.user_id=u.id and c.state<>'active')
  and not exists(select 1 from sdi_private.email_suppressions s where s.email_hash=sdi_private.email_hash(u.email) and (s.reason in('bounce','complaint') or category<>'transactional'))
  and (category='transactional' or (category='product' and coalesce(p.email_product,false)) or (category='marketing' and coalesce(p.email_marketing,false)))
  order by u.created_at,u.id limit batch offset page*batch) u;
 return jsonb_build_object('category',category,'recipients',items,'has_more',jsonb_array_length(items)=batch);
end $$;
revoke all on function sdi_private.announcement_claim(integer),sdi_private.announcement_finish(jsonb),sdi_private.email_suppress(text,text),sdi_private.email_recipients(text,integer,integer) from public,anon,authenticated;
grant execute on function sdi_private.announcement_claim(integer),sdi_private.announcement_finish(jsonb),sdi_private.email_suppress(text,text),sdi_private.email_recipients(text,integer,integer) to service_role;
create function public.sdi_announcement_claim(batch integer default 500) returns jsonb language sql security invoker set search_path='' as $$select sdi_private.announcement_claim(batch)$$;
create function public.sdi_announcement_finish(results jsonb) returns jsonb language sql security invoker set search_path='' as $$select sdi_private.announcement_finish(results)$$;
create function public.sdi_email_suppress(address_hash text,reason text) returns boolean language sql security invoker set search_path='' as $$select sdi_private.email_suppress(address_hash,reason)$$;
create function public.sdi_email_recipients(category text,batch integer default 500,page integer default 0) returns jsonb language sql security invoker set search_path='' as $$select sdi_private.email_recipients(category,batch,page)$$;
revoke all on function public.sdi_announcement_claim(integer),public.sdi_announcement_finish(jsonb),public.sdi_email_suppress(text,text),public.sdi_email_recipients(text,integer,integer) from public,anon,authenticated;
grant execute on function public.sdi_announcement_claim(integer),public.sdi_announcement_finish(jsonb),public.sdi_email_suppress(text,text),public.sdi_email_recipients(text,integer,integer) to service_role;
commit;

-- ===== marketing-workspace.sql (sha256 d3badbef1f9a859f) =====
-- Unapplied candidate. Install after notifications.sql (needs consent-versions.sql,
-- publishing-jobs.sql, admin-hardening.sql, feed-publication.sql).
-- Approval-based marketing workspace for #274 and #283: campaigns, drafts per
-- destination, a versioned brand-voice guide, per-destination cadence settings and a
-- service claim/finish contract for the destination adapters. Every draft that
-- carries a video is bound to the exact approved render (review, version, digest):
-- approval requires release_allowed(..., 'social') and, for a member's render, the
-- creator's current marketing consent; owner approval is recorded with the digest and
-- a hash of the copy; any later edit, render revision, approval change or consent
-- withdrawal moves the draft back to draft or to invalidated. Cadence can only queue
-- drafts the owner already approved; it never approves. Nothing posts from here: the
-- adapters (backend/publishing/destinations.py) post only when configured and never
-- during development tests.
begin;
create table sdi_private.brand_voice_versions (
 version integer primary key check(version>0), body text not null check(length(body) between 1 and 20000),
 author uuid not null references auth.users(id), created_at timestamptz not null default clock_timestamp()
);
create table sdi_private.marketing_campaigns (
 id uuid primary key default gen_random_uuid(), title text not null check(length(title) between 1 and 120), goal text not null default '' check(length(goal)<=1000),
 state text not null default 'draft' check(state in('draft','active','archived')), created_by uuid not null references auth.users(id),
 revision bigint not null default 1, created_at timestamptz not null default clock_timestamp(), updated_at timestamptz not null default clock_timestamp()
);
create table sdi_private.marketing_drafts (
 id uuid primary key default gen_random_uuid(), campaign_id uuid not null references sdi_private.marketing_campaigns(id) on delete cascade,
 destination text not null check(destination in('discord','facebook','x','youtube','instagram','tiktok','email')),
 review_id uuid references sdi_private.render_reviews(id) on delete set null, review_version bigint, render_digest text check(render_digest ~ '^[a-f0-9]{64}$'),
 copy text not null check(length(copy) between 1 and 2000), scheduled_for timestamptz,
 state text not null default 'draft' check(state in('draft','approved','queued','leased','published','failed','cancelled','invalidated')),
 approved_by uuid references auth.users(id), approved_at timestamptz, approved_digest text, approved_copy_hash text, brand_voice_version integer,
 attempts integer not null default 0, lease uuid, lease_expires timestamptz, provider_ref text, result_url text, last_error text not null default '',
 created_by uuid not null references auth.users(id), revision bigint not null default 1,
 created_at timestamptz not null default clock_timestamp(), updated_at timestamptz not null default clock_timestamp(),
 check((review_id is null)=(render_digest is null))
);
create table sdi_private.marketing_cadence (
 destination text primary key check(destination in('discord','facebook','x','youtube','instagram','tiktok','email')),
 enabled boolean not null default false, cadence text not null default 'weekly' check(cadence in('daily','weekly')),
 hour_utc integer not null default 16 check(hour_utc between 0 and 23), weekday integer check(weekday between 0 and 6),
 last_run_at timestamptz, updated_by uuid references auth.users(id), updated_at timestamptz not null default clock_timestamp()
);
create table sdi_private.marketing_audit (
 id uuid primary key default gen_random_uuid(), actor uuid not null references auth.users(id), draft_id uuid, action text not null,
 reason text not null check(length(reason) between 1 and 2000), created_at timestamptz not null default clock_timestamp()
);
alter table sdi_private.brand_voice_versions enable row level security;
alter table sdi_private.marketing_campaigns enable row level security;
alter table sdi_private.marketing_drafts enable row level security;
alter table sdi_private.marketing_cadence enable row level security;
alter table sdi_private.marketing_audit enable row level security;
revoke all on sdi_private.brand_voice_versions,sdi_private.marketing_campaigns,sdi_private.marketing_drafts,sdi_private.marketing_cadence,sdi_private.marketing_audit from public,anon,authenticated;
create index marketing_drafts_queue on sdi_private.marketing_drafts(state,scheduled_for,created_at);
create index marketing_drafts_review on sdi_private.marketing_drafts(review_id);

-- A render revision or approval change invalidates approved, queued or leased drafts
-- bound to it (publishing's own triggers already handle its jobs).
create function sdi_private.marketing_invalidate_render() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if row(new.version,new.render_digest,new.state,new.rights_cleared,new.consent_version,new.destinations)
  is distinct from row(old.version,old.render_digest,old.state,old.rights_cleared,old.consent_version,old.destinations) then
  update sdi_private.marketing_drafts set state='invalidated',last_error='Render or its approval changed after marketing approval.',revision=revision+1,updated_at=clock_timestamp()
  where review_id=new.id and state in('approved','queued','leased') and not (new.state='approved' and new.rights_cleared and length(new.consent_version)>0
   and review_version=new.version and render_digest=new.render_digest and 'social'=any(new.destinations));
 end if;
 return new;
end $$;
revoke all on function sdi_private.marketing_invalidate_render() from public,anon,authenticated;
create trigger marketing_invalidate_render after update on sdi_private.render_reviews for each row execute function sdi_private.marketing_invalidate_render();
-- Withdrawing marketing consent invalidates drafts that use that creator's renders.
create function sdi_private.marketing_invalidate_consent() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if new.policy='marketing' and new.withdrawn_at is not null and old.withdrawn_at is null then
  update sdi_private.marketing_drafts d set state='invalidated',last_error='Creator withdrew marketing permission.',revision=revision+1,updated_at=clock_timestamp()
  from sdi_private.render_reviews r where r.id=d.review_id and r.creator=new.user_id and not r.spatter_generated and d.state in('approved','queued','leased');
 end if;
 return new;
end $$;
revoke all on function sdi_private.marketing_invalidate_consent() from public,anon,authenticated;
create trigger marketing_invalidate_consent after update on sdi_private.consent_records for each row execute function sdi_private.marketing_invalidate_consent();

create function sdi_private.marketing_release_ok(d sdi_private.marketing_drafts) returns text language plpgsql stable security definer set search_path='' as $$
declare r sdi_private.render_reviews;
begin
 if d.review_id is null then return null; end if;
 select * into r from sdi_private.render_reviews where id=d.review_id;
 if not found then return 'Render no longer exists.'; end if;
 if not sdi_private.release_allowed(d.review_id,d.review_version,d.render_digest,'social') then return 'This exact render lacks current approval, rights or consent for social release.'; end if;
 if not r.spatter_generated and not sdi_private.consent_current(r.creator,'marketing') then return 'The creator has not given current marketing permission.'; end if;
 return null;
end $$;
revoke all on function sdi_private.marketing_release_ok(sdi_private.marketing_drafts) from public,anon,authenticated;

create function sdi_private.marketing_action(action text,campaign uuid default null,draft uuid default null,revision bigint default null,payload jsonb default '{}',reason text default '')
returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare denial jsonb; c sdi_private.marketing_campaigns; d sdi_private.marketing_drafts; r sdi_private.render_reviews; items jsonb; problem text; is_owner boolean; next_version integer;
begin
 denial:=sdi_private.admin_gate('marketing.'||coalesce(action,'?'),'publishing',action in('approve','set_cadence','brand_voice'),60);
 if denial is not null then return denial; end if;
 select owner into is_owner from sdi_private.admin_roles where user_id=auth.uid() and enabled;
 if action='list' then
  select coalesce(jsonb_agg(row_to_json(x) order by x.updated_at desc),'[]'::jsonb) into items from (select * from sdi_private.marketing_campaigns order by updated_at desc limit 100) x;
  return jsonb_build_object('campaigns',items,
   'drafts',(select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'campaign_id',m.campaign_id,'destination',m.destination,'review_id',m.review_id,'render_digest',m.render_digest,'copy',m.copy,
     'scheduled_for',m.scheduled_for,'state',m.state,'approved_at',m.approved_at,'result_url',m.result_url,'provider_ref',m.provider_ref,'last_error',m.last_error,'attempts',m.attempts,'revision',m.revision,
     'release_problem',sdi_private.marketing_release_ok(m)) order by m.updated_at desc),'[]'::jsonb)
     from (select id from sdi_private.marketing_drafts order by updated_at desc limit 200) s join sdi_private.marketing_drafts m on m.id=s.id),
   'cadence',(select coalesce(jsonb_agg(row_to_json(k) order by k.destination),'[]'::jsonb) from sdi_private.marketing_cadence k),
   'brand_voice_version',(select max(version) from sdi_private.brand_voice_versions));
 elsif action='brand_voice_list' then
  select coalesce(jsonb_agg(row_to_json(v) order by v.version desc),'[]'::jsonb) into items from sdi_private.brand_voice_versions v;
  return jsonb_build_object('versions',items);
 end if;
 if reason is null or length(trim(reason)) not between 1 and 2000 then return jsonb_build_object('error','A reason is required.'); end if;
 if action in('approve','set_cadence','brand_voice') and not coalesce(is_owner,false) then return jsonb_build_object('error','Owner permission required.'); end if;
 if action='brand_voice' then
  if length(coalesce(payload->>'body','')) not between 1 and 20000 then return jsonb_build_object('error','Brand voice text of at most 20000 characters required.'); end if;
  select coalesce(max(version),0)+1 into next_version from sdi_private.brand_voice_versions;
  insert into sdi_private.brand_voice_versions(version,body,author) values(next_version,payload->>'body',auth.uid());
  insert into sdi_private.marketing_audit(actor,action,reason) values(auth.uid(),'brand_voice v'||next_version,trim(reason));
  return jsonb_build_object('status','confirmed','version',next_version);
 elsif action='set_cadence' then
  if coalesce(payload->>'destination','') not in('discord','facebook','x','youtube','instagram','tiktok','email') or (payload->>'enabled') is null
   or coalesce(payload->>'cadence','weekly') not in('daily','weekly') or coalesce(payload->>'hour_utc','16') !~ '^([0-9]|1[0-9]|2[0-3])$'
   or (payload ? 'weekday' and (payload->>'weekday') !~ '^[0-6]$') then return jsonb_build_object('error','Destination, enabled, cadence, hour_utc and weekday required.'); end if;
  insert into sdi_private.marketing_cadence(destination,enabled,cadence,hour_utc,weekday,updated_by) values(payload->>'destination',(payload->>'enabled')::boolean,coalesce(payload->>'cadence','weekly'),
   coalesce(payload->>'hour_utc','16')::integer,(payload->>'weekday')::integer,auth.uid())
  on conflict(destination) do update set enabled=excluded.enabled,cadence=excluded.cadence,hour_utc=excluded.hour_utc,weekday=excluded.weekday,updated_by=excluded.updated_by,updated_at=clock_timestamp();
  insert into sdi_private.marketing_audit(actor,action,reason) values(auth.uid(),'set_cadence '||(payload->>'destination')||' enabled='||(payload->>'enabled'),trim(reason));
  return jsonb_build_object('status','confirmed');
 elsif action='create_campaign' then
  if length(coalesce(payload->>'title','')) not between 1 and 120 or length(coalesce(payload->>'goal',''))>1000 then return jsonb_build_object('error','Campaign title required.'); end if;
  insert into sdi_private.marketing_campaigns(title,goal,created_by) values(payload->>'title',coalesce(payload->>'goal',''),auth.uid()) returning * into c;
  insert into sdi_private.marketing_audit(actor,action,reason) values(auth.uid(),'create_campaign '||c.id,trim(reason));
  return jsonb_build_object('status','confirmed','campaign',c.id,'revision',c.revision);
 elsif action='create_draft' then
  select * into c from sdi_private.marketing_campaigns where id=campaign;
  if not found or c.state='archived' then return jsonb_build_object('error','Campaign unavailable.'); end if;
  if coalesce(payload->>'destination','') not in('discord','facebook','x','youtube','instagram','tiktok','email') or length(coalesce(payload->>'copy','')) not between 1 and 2000 then
   return jsonb_build_object('error','Destination and copy of at most 2000 characters required.'); end if;
  if payload->>'review' is not null then
   select * into r from sdi_private.render_reviews where id=(payload->>'review')::uuid;
   if not found then return jsonb_build_object('error','Render unavailable.'); end if;
  end if;
  insert into sdi_private.marketing_drafts(campaign_id,destination,review_id,review_version,render_digest,copy,scheduled_for,created_by)
  values(c.id,payload->>'destination',r.id,r.version,r.render_digest,payload->>'copy',(payload->>'scheduled_for')::timestamptz,auth.uid()) returning * into d;
  insert into sdi_private.marketing_audit(actor,draft_id,action,reason) values(auth.uid(),d.id,'create_draft',trim(reason));
  return jsonb_build_object('status','draft','draft',d.id,'revision',d.revision,'release_problem',sdi_private.marketing_release_ok(d));
 end if;
 select * into d from sdi_private.marketing_drafts where id=draft for update;
 if not found or revision is distinct from d.revision then return jsonb_build_object('error','Draft changed. Refresh before saving.'); end if;
 if action='update_draft' then
  if d.state not in('draft','approved','failed','invalidated') then return jsonb_build_object('error','Queued or finished drafts cannot be edited.'); end if;
  if payload ? 'copy' and length(coalesce(payload->>'copy','')) not between 1 and 2000 then return jsonb_build_object('error','Copy of at most 2000 characters required.'); end if;
  if payload ? 'review' then
   if payload->>'review' is null then r:=null; else
    select * into r from sdi_private.render_reviews where id=(payload->>'review')::uuid;
    if not found then return jsonb_build_object('error','Render unavailable.'); end if;
   end if;
   update sdi_private.marketing_drafts set review_id=r.id,review_version=r.version,render_digest=r.render_digest where id=d.id;
  end if;
  -- Any edit clears approval: the owner approves exact copy and exact render.
  update sdi_private.marketing_drafts set copy=coalesce(payload->>'copy',copy),scheduled_for=case when payload ? 'scheduled_for' then (payload->>'scheduled_for')::timestamptz else scheduled_for end,
   state='draft',approved_by=null,approved_at=null,approved_digest=null,approved_copy_hash=null,last_error='',revision=revision+1,updated_at=clock_timestamp() where id=d.id;
 elsif action='approve' then
  if d.state<>'draft' then return jsonb_build_object('error','Only drafts can be approved.'); end if;
  problem:=sdi_private.marketing_release_ok(d);
  if problem is not null then return jsonb_build_object('error',problem); end if;
  update sdi_private.marketing_drafts set state='approved',approved_by=auth.uid(),approved_at=clock_timestamp(),approved_digest=render_digest,
   approved_copy_hash=encode(extensions.digest(copy,'sha256'),'hex'),brand_voice_version=(select max(version) from sdi_private.brand_voice_versions),
   revision=revision+1,updated_at=clock_timestamp() where id=d.id;
 elsif action='queue' then
  if d.state<>'approved' then return jsonb_build_object('error','Approve the draft first.'); end if;
  problem:=sdi_private.marketing_release_ok(d);
  if problem is not null then update sdi_private.marketing_drafts set state='invalidated',last_error=problem,revision=revision+1,updated_at=clock_timestamp() where id=d.id; return jsonb_build_object('error',problem); end if;
  update sdi_private.marketing_drafts set state='queued',attempts=0,revision=revision+1,updated_at=clock_timestamp() where id=d.id;
 elsif action='cancel' then
  if d.state in('published','cancelled') then return jsonb_build_object('status','unchanged','state',d.state); end if;
  update sdi_private.marketing_drafts set state='cancelled',lease=null,lease_expires=null,last_error=case when d.state='leased' then 'Cancelled while the adapter was posting; check the provider.' else last_error end,
   revision=revision+1,updated_at=clock_timestamp() where id=d.id;
 elsif action='retry' then
  if d.state<>'failed' or d.attempts>=5 then return jsonb_build_object('error','Only failed drafts with attempts left can be retried.'); end if;
  problem:=sdi_private.marketing_release_ok(d);
  if problem is not null then return jsonb_build_object('error',problem); end if;
  update sdi_private.marketing_drafts set state='queued',revision=revision+1,updated_at=clock_timestamp() where id=d.id;
 else return jsonb_build_object('error','Unsupported marketing operation.'); end if;
 insert into sdi_private.marketing_audit(actor,draft_id,action,reason) values(auth.uid(),d.id,action,trim(reason));
 return jsonb_build_object('status','confirmed','revision',d.revision+1);
exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow then
 return jsonb_build_object('error','Invalid identifier or time.');
end $$;
revoke all on function sdi_private.marketing_action(text,uuid,uuid,bigint,jsonb,text) from public,anon;
grant execute on function sdi_private.marketing_action(text,uuid,uuid,bigint,jsonb,text) to authenticated;
create function public.sdi_marketing_action(action text,campaign uuid default null,draft uuid default null,revision bigint default null,payload jsonb default '{}',reason text default '')
returns jsonb language sql security invoker set search_path='' as $$select sdi_private.marketing_action(action,campaign,draft,revision,payload,reason)$$;
revoke all on function public.sdi_marketing_action(text,uuid,uuid,bigint,jsonb,text) from public,anon;
grant execute on function public.sdi_marketing_action(text,uuid,uuid,bigint,jsonb,text) to authenticated;

-- Service: lease one due approved+queued draft after re-checking the binding;
-- finish with the provider's real result or a failure. Posting happens only in the
-- adapter, which refuses unconfigured destinations and dry-runs during development.
create function sdi_private.marketing_claim() returns jsonb language plpgsql security definer set search_path='' as $$
declare d sdi_private.marketing_drafts; problem text; media text; a sdi_private.render_artifacts;
begin
 update sdi_private.marketing_drafts set state='failed',last_error='Adapter lease expired; verify the provider before retrying.',lease=null,lease_expires=null,updated_at=clock_timestamp()
 where state='leased' and lease_expires<clock_timestamp();
 select * into d from sdi_private.marketing_drafts where state='queued' and (scheduled_for is null or scheduled_for<=clock_timestamp()) and attempts<5
  order by scheduled_for nulls first,created_at for update skip locked limit 1;
 if not found then return jsonb_build_object('empty',true); end if;
 problem:=sdi_private.marketing_release_ok(d);
 if problem is not null or d.approved_digest is distinct from d.render_digest or d.approved_copy_hash<>encode(extensions.digest(d.copy,'sha256'),'hex') then
  update sdi_private.marketing_drafts set state='invalidated',last_error=coalesce(problem,'Approved render or copy no longer matches.'),updated_at=clock_timestamp() where id=d.id;
  return jsonb_build_object('empty',true);
 end if;
 if d.review_id is not null then
  select url into media from public.sdi_watch_media where render_digest=d.render_digest and approved;
  select * into a from sdi_private.render_artifacts where review_id=d.review_id and version=d.review_version;
 end if;
 update sdi_private.marketing_drafts set state='leased',attempts=attempts+1,lease=gen_random_uuid(),lease_expires=clock_timestamp()+interval '5 minutes',updated_at=clock_timestamp() where id=d.id returning * into d;
 return jsonb_build_object('draft',d.id,'lease',d.lease,'destination',d.destination,'copy',d.copy,'digest',d.render_digest,'media_url',media,
  'object_key',a.object_key,'byte_count',a.byte_count,'title',a.title,'brand_voice_version',d.brand_voice_version,'attempt',d.attempts);
end $$;
create function sdi_private.marketing_finish(draft uuid,token uuid,result_url text default null,provider_ref text default null,failure text default null) returns boolean
language plpgsql security definer set search_path='' as $$
declare d sdi_private.marketing_drafts;
begin
 select * into d from sdi_private.marketing_drafts where id=draft and lease=token for update;
 if not found then return false; end if;
 if d.state='cancelled' then
  -- Cancelled during the post: record what the provider did so an operator can act.
  update sdi_private.marketing_drafts set provider_ref=coalesce(marketing_finish.provider_ref,d.provider_ref),result_url=coalesce(marketing_finish.result_url,d.result_url),
   last_error=case when failure is null and marketing_finish.result_url is not null then 'Posted before cancellation was observed; remove at the provider if required.' else last_error end,lease=null,lease_expires=null,updated_at=clock_timestamp() where id=d.id;
  return false;
 end if;
 if d.state<>'leased' then return false; end if;
 if failure is not null then
  update sdi_private.marketing_drafts set state='failed',last_error=left(failure,500),lease=null,lease_expires=null,updated_at=clock_timestamp() where id=d.id;
  return true;
 end if;
 if marketing_finish.result_url is null or marketing_finish.result_url !~ '^https://' or length(marketing_finish.result_url)>2048 then return false; end if;
 update sdi_private.marketing_drafts set state='published',result_url=marketing_finish.result_url,provider_ref=left(coalesce(marketing_finish.provider_ref,''),200),last_error='',lease=null,lease_expires=null,updated_at=clock_timestamp() where id=d.id;
 return true;
end $$;
-- Cadence sweep: for each enabled destination whose slot has passed, queue the
-- earliest approved draft that is due. Approval is never granted here.
create function sdi_private.marketing_cadence_due() returns jsonb language plpgsql security definer set search_path='' as $$
declare k sdi_private.marketing_cadence; d sdi_private.marketing_drafts; slot timestamptz; queued jsonb:='[]'; problem text;
begin
 for k in select * from sdi_private.marketing_cadence where enabled for update loop
  slot:=date_trunc('day',clock_timestamp())+make_interval(hours=>k.hour_utc);
  if slot>clock_timestamp() then slot:=slot-interval '1 day'; end if;
  if k.cadence='weekly' then
   slot:=slot-make_interval(days=>((extract(dow from slot)::integer-coalesce(k.weekday,1))+7)%7);
  end if;
  if k.last_run_at is not null and k.last_run_at>=slot then continue; end if;
  update sdi_private.marketing_cadence set last_run_at=clock_timestamp() where destination=k.destination;
  select * into d from sdi_private.marketing_drafts where destination=k.destination and state='approved' and (scheduled_for is null or scheduled_for<=clock_timestamp())
   order by scheduled_for nulls last,created_at for update skip locked limit 1;
  if not found then continue; end if;
  problem:=sdi_private.marketing_release_ok(d);
  if problem is not null then
   update sdi_private.marketing_drafts set state='invalidated',last_error=problem,revision=revision+1,updated_at=clock_timestamp() where id=d.id; continue; end if;
  update sdi_private.marketing_drafts set state='queued',attempts=0,revision=revision+1,updated_at=clock_timestamp() where id=d.id;
  queued:=queued||jsonb_build_object('draft',d.id,'destination',k.destination);
 end loop;
 return jsonb_build_object('queued',queued,'measured_at',clock_timestamp());
end $$;
revoke all on function sdi_private.marketing_claim(),sdi_private.marketing_finish(uuid,uuid,text,text,text),sdi_private.marketing_cadence_due() from public,anon,authenticated;
grant execute on function sdi_private.marketing_claim(),sdi_private.marketing_finish(uuid,uuid,text,text,text),sdi_private.marketing_cadence_due() to service_role;
create function public.sdi_marketing_claim() returns jsonb language sql security invoker set search_path='' as $$select sdi_private.marketing_claim()$$;
create function public.sdi_marketing_finish(draft uuid,token uuid,result_url text default null,provider_ref text default null,failure text default null) returns boolean
language sql security invoker set search_path='' as $$select sdi_private.marketing_finish(draft,token,result_url,provider_ref,failure)$$;
create function public.sdi_marketing_cadence_due() returns jsonb language sql security invoker set search_path='' as $$select sdi_private.marketing_cadence_due()$$;
revoke all on function public.sdi_marketing_claim(),public.sdi_marketing_finish(uuid,uuid,text,text,text),public.sdi_marketing_cadence_due() from public,anon,authenticated;
grant execute on function public.sdi_marketing_claim(),public.sdi_marketing_finish(uuid,uuid,text,text,text),public.sdi_marketing_cadence_due() to service_role;
commit;

-- ===== spatter-draft-jobs.sql (sha256 c46c55527c25a8f3) =====
-- Unapplied deployment candidate (#212, #214). Install after agent-controls.sql
-- and admin-approval.sql. Spatter's daily original-draft queue: one durable job
-- per calendar day, bounded retries and leases, private drafts only, and the
-- review row that binds the storyboard and the exact source-project digest.
-- Nothing here schedules a worker, approves capacity or publishes anything;
-- the owner enables the `spatter_daily_video` agent deliberately and approves
-- every render in the existing review queue.
begin;

-- Reviews carry the plan and the source digest (#214). Changing either
-- invalidates a prior approval exactly like a render-digest change.
alter table sdi_private.render_reviews
 add column storyboard jsonb,
 add column source_project_digest text check(source_project_digest is null or source_project_digest ~ '^[a-f0-9]{64}$');
create or replace function sdi_private.invalidate_render_approval() returns trigger language plpgsql set search_path='' as $$
begin
 if row(new.render_digest,new.source_revision,new.consent_version,new.rights_cleared,new.destinations,new.spatter_generated,new.creator,new.rights_summary,new.storyboard,new.source_project_digest)
 is distinct from row(old.render_digest,old.source_revision,old.consent_version,old.rights_cleared,old.destinations,old.spatter_generated,old.creator,old.rights_summary,old.storyboard,old.source_project_digest) then
  new.version=old.version+1; new.state='pending';
 end if;
 return new;
end $$;

create table sdi_private.spatter_draft_jobs (
 id uuid primary key default gen_random_uuid(),
 target_date date not null unique,                      -- one durable job per UTC day: restarted or double-scheduled workers cannot duplicate it
 state text not null default 'planned'
  check(state in('planned','claimed','rendering','review_pending','approved','rejected','failed','missed','cancelled')),
 attempts integer not null default 0 check(attempts between 0 and 3),
 planner_seed bigint not null,                          -- deterministic brief seed derived from target_date; replayable
 brief_version text not null check(length(brief_version) between 1 and 40),
 brief jsonb not null,                                   -- the exact local instruction(s) the planner emitted
 storyboard jsonb,
 quality_report jsonb,
 review_id uuid references sdi_private.render_reviews(id) on delete set null,
 artifact_sha256 text check(artifact_sha256 is null or artifact_sha256 ~ '^[a-f0-9]{64}$'),
 error text not null default '' check(length(error)<=2000),
 lease_owner text check(lease_owner is null or length(lease_owner) between 1 and 120),
 lease_expires_at timestamptz,
 agent_run uuid references sdi_private.agent_runs(id) on delete set null,
 created_at timestamptz not null default clock_timestamp(),
 updated_at timestamptz not null default clock_timestamp()
);
alter table sdi_private.spatter_draft_jobs enable row level security;
revoke all on sdi_private.spatter_draft_jobs from public,anon,authenticated;
create index spatter_draft_jobs_state on sdi_private.spatter_draft_jobs(state,target_date);

-- Days that passed without reaching review are recorded as missed, never
-- back-filled or hidden. Expired leases return the job to the claimable pool.
create function sdi_private.spatter_draft_sweep() returns integer language plpgsql security definer set search_path='' as $$
declare touched integer:=0; n integer;
begin
 update sdi_private.spatter_draft_jobs set state='missed',error=case when error='' then 'Target date passed without a review-ready draft.' else error end,
  lease_owner=null,lease_expires_at=null,updated_at=clock_timestamp()
  where state in('planned','claimed','rendering','failed') and target_date<(clock_timestamp() at time zone 'utc')::date;
 get diagnostics n=row_count; touched:=touched+n;
 update sdi_private.spatter_draft_jobs set state='planned',lease_owner=null,lease_expires_at=null,
  error='Lease expired before the render finished.',updated_at=clock_timestamp()
  where state in('claimed','rendering') and lease_expires_at<clock_timestamp();
 get diagnostics n=row_count; touched:=touched+n;
 -- Review outcomes are copied, never decided here.
 update sdi_private.spatter_draft_jobs j set state=r.state,updated_at=clock_timestamp()
  from sdi_private.render_reviews r where r.id=j.review_id and j.state='review_pending' and r.state in('approved','rejected');
 get diagnostics n=row_count; touched:=touched+n;
 return touched;
end $$;

-- Claim today's job (or create it) behind the owner's agent gate. Returns
-- {claimed:boolean, reason?, job?, attempt?, run?, brief?}. The planner seed and
-- brief are supplied by the worker and stored once; later claims reuse them.
create function sdi_private.spatter_draft_claim(p_date date,p_owner text,p_seed bigint,p_brief_version text,p_brief jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare j sdi_private.spatter_draft_jobs; gate jsonb; run uuid;
begin
 if p_date is null or p_owner is null or length(p_owner) not between 1 and 120 or p_brief is null or p_brief_version is null then
  return jsonb_build_object('claimed',false,'reason','Invalid claim request.'); end if;
 if p_date<(clock_timestamp() at time zone 'utc')::date then
  perform sdi_private.spatter_draft_sweep();
  return jsonb_build_object('claimed',false,'reason','The target date has passed; it is recorded as missed, not back-filled.'); end if;
 perform sdi_private.spatter_draft_sweep();
 insert into sdi_private.spatter_draft_jobs(target_date,planner_seed,brief_version,brief) values(p_date,p_seed,p_brief_version,p_brief)
  on conflict(target_date) do nothing;
 select * into j from sdi_private.spatter_draft_jobs where target_date=p_date for update;
 if j.state not in('planned','failed') then return jsonb_build_object('claimed',false,'reason','Job is '||j.state||'.','job',j.id); end if;
 if j.attempts>=3 then return jsonb_build_object('claimed',false,'reason','Retry limit reached (3 attempts).','job',j.id); end if;
 gate:=sdi_private.agent_run_begin('spatter_daily_video',p_date::text);
 if not (gate->>'allowed')::boolean then return jsonb_build_object('claimed',false,'reason',gate->>'reason','job',j.id); end if;
 run:=(gate->>'run')::uuid;
 update sdi_private.spatter_draft_jobs set state='claimed',attempts=attempts+1,lease_owner=p_owner,
  lease_expires_at=clock_timestamp()+interval '15 minutes',agent_run=run,error='',updated_at=clock_timestamp() where id=j.id;
 return jsonb_build_object('claimed',true,'job',j.id,'attempt',j.attempts+1,'run',run,'brief',j.brief,'planner_seed',j.planner_seed,
  'instructions',gate->>'instructions','per_run_item_cap',gate->'per_run_item_cap');
end $$;

-- Worker progress. Only the lease holder may move a job, and only forward:
-- claimed→rendering, rendering→failed, rendering→review_pending (which inserts
-- the private review row and finishes the agent run). Approval stays with the
-- owner in the review queue.
create function sdi_private.spatter_draft_progress(p_job uuid,p_owner text,p_state text,p_storyboard jsonb default null,
 p_quality jsonb default null,p_sha text default null,p_error text default '',p_review jsonb default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare j sdi_private.spatter_draft_jobs; review uuid; creator uuid;
begin
 select * into j from sdi_private.spatter_draft_jobs where id=p_job for update;
 if not found or j.lease_owner is distinct from p_owner or j.lease_expires_at<clock_timestamp() then
  return jsonb_build_object('status','refused','reason','Not the current lease holder.'); end if;
 if p_state='rendering' and j.state='claimed' then
  update sdi_private.spatter_draft_jobs set state='rendering',storyboard=coalesce(p_storyboard,storyboard),
   lease_expires_at=clock_timestamp()+interval '15 minutes',updated_at=clock_timestamp() where id=j.id;
  perform sdi_private.agent_run_heartbeat(j.agent_run);
  return jsonb_build_object('status','confirmed','state','rendering');
 elsif p_state='failed' and j.state in('claimed','rendering') then
  update sdi_private.spatter_draft_jobs set state='failed',error=left(coalesce(p_error,'Render failed.'),2000),quality_report=coalesce(p_quality,quality_report),
   lease_owner=null,lease_expires_at=null,updated_at=clock_timestamp() where id=j.id;
  perform sdi_private.agent_run_finish(j.agent_run,'failed',0,0,left(coalesce(p_error,''),2000));
  return jsonb_build_object('status','confirmed','state','failed','attempts',j.attempts);
 elsif p_state='review_pending' and j.state='rendering' then
  if p_sha is null or p_sha !~ '^[a-f0-9]{64}$' or p_storyboard is null or p_quality is null or p_review is null
   or (p_review->>'creator') is null or (p_review->>'preview_url') is null or (p_review->>'source_project_digest') !~ '^[a-f0-9]{64}$' then
   return jsonb_build_object('status','refused','reason','A review needs the render digest, storyboard, quality report, source digest, creator and private preview URL.'); end if;
  if coalesce((p_quality->>'passes')::boolean,false) is not true then
   return jsonb_build_object('status','refused','reason','The quality report did not pass; mark the job failed with the finding instead.'); end if;
  creator:=(p_review->>'creator')::uuid;
  insert into sdi_private.render_reviews(creator,title,source_revision,render_digest,preview_url,preview_expires_at,consent_version,rights_summary,rights_cleared,
   destinations,spatter_generated,storyboard,source_project_digest)
  values(creator,left(coalesce(p_review->>'title','Spatter daily draft '||j.target_date::text),200),coalesce(p_review->>'source_revision','draft:'||j.target_date::text),
   p_sha,p_review->>'preview_url',coalesce((p_review->>'preview_expires_at')::timestamptz,clock_timestamp()+interval '7 days'),
   coalesce(p_review->>'consent_version','spatter-draft-v1'),coalesce(p_review->>'rights_summary','Independently generated stick-figure content; no external source material.'),
   coalesce((p_review->>'rights_cleared')::boolean,true),'{}'::text[],true,p_storyboard,p_review->>'source_project_digest')
  returning id into review;
  update sdi_private.spatter_draft_jobs set state='review_pending',storyboard=p_storyboard,quality_report=p_quality,artifact_sha256=p_sha,review_id=review,
   lease_owner=null,lease_expires_at=null,updated_at=clock_timestamp() where id=j.id;
  perform sdi_private.agent_run_finish(j.agent_run,'succeeded',1,0,'');
  return jsonb_build_object('status','confirmed','state','review_pending','review',review);
 end if;
 return jsonb_build_object('status','refused','reason','Transition '||j.state||' → '||coalesce(p_state,'?')||' is not allowed.');
end $$;

-- Owner/admin view: every day in the range with its real state, so missed and
-- failed days are visible rather than a daily-success claim.
create function sdi_private.spatter_draft_status(p_from date,p_to date) returns jsonb language plpgsql security definer set search_path='' as $$
declare result jsonb;
begin
 if not sdi_private.admin_can('reviews') then return jsonb_build_object('error','Current video-review permission and MFA are required.'); end if;
 if p_from is null or p_to is null or p_to<p_from or p_to-p_from>62 then return jsonb_build_object('error','Choose a range of at most 62 days.'); end if;
 perform sdi_private.spatter_draft_sweep();
 select coalesce(jsonb_agg(jsonb_build_object('date',d::date,'state',coalesce(j.state,case when d::date<(clock_timestamp() at time zone 'utc')::date then 'missed' else 'unplanned' end),
  'attempts',coalesce(j.attempts,0),'error',coalesce(j.error,''),'review',j.review_id,'sha256',j.artifact_sha256,'seed',j.planner_seed) order by d),'[]'::jsonb)
  into result from generate_series(p_from,p_to,interval '1 day') d left join sdi_private.spatter_draft_jobs j on j.target_date=d::date;
 return jsonb_build_object('days',result,'capacity','owner-gated: no render capacity is approved or purchased by this queue');
end $$;

revoke all on function sdi_private.spatter_draft_sweep(),sdi_private.spatter_draft_claim(date,text,bigint,text,jsonb),
 sdi_private.spatter_draft_progress(uuid,text,text,jsonb,jsonb,text,text,jsonb),sdi_private.spatter_draft_status(date,date) from public,anon,authenticated;
grant execute on function sdi_private.spatter_draft_sweep(),sdi_private.spatter_draft_claim(date,text,bigint,text,jsonb),
 sdi_private.spatter_draft_progress(uuid,text,text,jsonb,jsonb,text,text,jsonb) to service_role;
grant execute on function sdi_private.spatter_draft_status(date,date) to authenticated;
create function public.sdi_spatter_draft_claim(p_date date,p_owner text,p_seed bigint,p_brief_version text,p_brief jsonb) returns jsonb
 language sql security invoker set search_path='' as $$select sdi_private.spatter_draft_claim(p_date,p_owner,p_seed,p_brief_version,p_brief)$$;
create function public.sdi_spatter_draft_progress(p_job uuid,p_owner text,p_state text,p_storyboard jsonb default null,p_quality jsonb default null,
 p_sha text default null,p_error text default '',p_review jsonb default null) returns jsonb
 language sql security invoker set search_path='' as $$select sdi_private.spatter_draft_progress(p_job,p_owner,p_state,p_storyboard,p_quality,p_sha,p_error,p_review)$$;
create function public.sdi_spatter_draft_status(p_from date,p_to date) returns jsonb
 language sql security invoker set search_path='' as $$select sdi_private.spatter_draft_status(p_from,p_to)$$;
revoke all on function public.sdi_spatter_draft_claim(date,text,bigint,text,jsonb),public.sdi_spatter_draft_progress(uuid,text,text,jsonb,jsonb,text,text,jsonb),
 public.sdi_spatter_draft_status(date,date) from public,anon,authenticated;
grant execute on function public.sdi_spatter_draft_claim(date,text,bigint,text,jsonb),public.sdi_spatter_draft_progress(uuid,text,text,jsonb,jsonb,text,text,jsonb) to service_role;
grant execute on function public.sdi_spatter_draft_status(date,date) to authenticated;

-- ── Spatter cloud-advice metering (#209) ─────────────────────────────────
-- Server-side prompt accounting for backend/spatter/handler.py. The device never
-- counts its own allowance. Owner decisions (2026-10-07, revised 2026-10-14,
-- issue #209): Free accounts get 5 prompts per UTC calendar month and may only
-- send one of the app's suggested prompts (an id from the fixed allowlist in
-- sdi_private.spatter_suggested_prompt_ids, mirrored by
-- backend/spatter/suggested_prompts.py and the iOS SpatterSuggestedPrompt
-- catalogue); free text is refused before anything is counted. The free trial
-- applies to both paid plans: a 'trialing' subscription maps to its own tier
-- through sdi_private.entitlements. The USD 4.99 'creator' plan gets 15 prompts
-- per billing period, keyed to the subscription's paid_through so a renewal
-- starts a new period; the USD 9.99 'pro' plan has no plan allowance but still
-- obeys the per-user
-- daily safety cap, the per-minute rate, the global daily ceiling and the agent
-- emergency stop. The global ceiling defaults to 0 (closed) so nothing can be
-- spent until the owner sets it. One unit is one prompt; provider-reported
-- usage units are recorded on the reservation when the handler commits it.
create table sdi_private.spatter_usage_controls (
 singleton boolean primary key default true check(singleton),
 global_daily_cap integer not null default 0 check(global_daily_cap between 0 and 10000000),
 user_daily_safety_cap integer not null default 100 check(user_daily_safety_cap between 0 and 10000),
 user_per_minute_cap integer not null default 6 check(user_per_minute_cap between 1 and 600),
 free_prompts integer not null default 5 check(free_prompts between 0 and 1000),
 creator_period_prompts integer not null default 15 check(creator_period_prompts between 0 and 100000),
 revision bigint not null default 1, updated_by uuid references auth.users(id) on delete set null,
 updated_at timestamptz not null default clock_timestamp()
);
insert into sdi_private.spatter_usage_controls(singleton) values(true);
-- One row per (account, bucket). Buckets: 'month:<utc yyyy-mm>' (free calendar
-- month), 'free' (legacy one-time bucket, no longer written),
-- 'period:<paid_through>' (creator billing period), 'day:<utc date>' (safety
-- cap) and 'minute:<utc minute>' (rate). No prompt text is ever stored.
create table sdi_private.spatter_usage_counters (
 user_id uuid not null references auth.users(id) on delete cascade,
 bucket text not null check(bucket ~ '^(free|month:[0-9]{4}-[0-9]{2}|period:[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z|day:[0-9]{4}-[0-9]{2}-[0-9]{2}|minute:[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2})$'),
 used integer not null default 0 check(used>=0),
 updated_at timestamptz not null default clock_timestamp(),
 primary key(user_id,bucket)
);
create table sdi_private.spatter_usage_global (
 day date primary key, used integer not null default 0 check(used>=0), updated_at timestamptz not null default clock_timestamp()
);
create table sdi_private.spatter_usage_reservations (
 id uuid primary key default gen_random_uuid(),
 user_id uuid not null references auth.users(id) on delete cascade,
 plan text not null check(plan in('free','creator','pro')),
 buckets text[] not null, day date not null,
 state text not null default 'reserved' check(state in('reserved','committed','released')),
 units integer not null default 0 check(units between 0 and 1000000000),
 created_at timestamptz not null default clock_timestamp(), settled_at timestamptz
);
alter table sdi_private.spatter_usage_controls enable row level security;
alter table sdi_private.spatter_usage_counters enable row level security;
alter table sdi_private.spatter_usage_global enable row level security;
alter table sdi_private.spatter_usage_reservations enable row level security;
revoke all on sdi_private.spatter_usage_controls,sdi_private.spatter_usage_counters,sdi_private.spatter_usage_global,
 sdi_private.spatter_usage_reservations from public,anon,authenticated;
create index spatter_usage_reservations_open on sdi_private.spatter_usage_reservations(state,created_at);

-- The only prompts a Free account may send. Ids only: the prompt text lives in
-- the handler (backend/spatter/suggested_prompts.py), which replaces any client
-- content with that canonical text for Free requests.
create function sdi_private.spatter_suggested_prompt_ids() returns text[] language sql immutable set search_path='' as $$
 select array['animation_tips','scene_ideas','fight_choreography','style_advice']::text[]
$$;

-- The account's current plan and allowance, without consuming anything.
create function sdi_private.spatter_usage_plan(p_user uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare c sdi_private.spatter_usage_controls; v_tier text; v_paid timestamptz; v_plan text:='free'; v_bucket text; v_limit integer; v_used integer;
 v_month timestamptz:=date_trunc('month',clock_timestamp() at time zone 'utc') at time zone 'utc';
begin
 select * into c from sdi_private.spatter_usage_controls;
 select tier,paid_through into v_tier,v_paid from sdi_private.entitlements where user_id=p_user
  order by case tier when 'pro' then 0 else 1 end,paid_through desc limit 1;
 if v_tier is not null then v_plan:=v_tier; end if;
 if v_plan='pro' then
  return jsonb_build_object('plan','pro','unlimited',true,'limit',null,'used',null,'remaining',null,'period','none','resets_at',null);
 elsif v_plan='creator' then
  v_bucket:='period:'||to_char(v_paid at time zone 'utc','YYYY-MM-DD"T"HH24:MI:SS"Z"'); v_limit:=c.creator_period_prompts;
 else
  v_bucket:='month:'||to_char(v_month at time zone 'utc','YYYY-MM'); v_limit:=c.free_prompts;
 end if;
 select u.used into v_used from sdi_private.spatter_usage_counters u where u.user_id=p_user and u.bucket=v_bucket;
 v_used:=coalesce(v_used,0);
 return jsonb_build_object('plan',v_plan,'unlimited',false,'limit',v_limit,'used',v_used,'remaining',greatest(v_limit-v_used,0),
  'period',case v_plan when 'creator' then 'billing_period' else 'calendar_month' end,
  'resets_at',case v_plan when 'creator' then to_jsonb(v_paid) else to_jsonb(v_month+interval '1 month') end,
  'suggested_prompts_only',v_plan='free','bucket',v_bucket);
end $$;

-- Service-only atomic reservation of one prompt. Every refusal carries a
-- stable code the handler maps to an HTTP status and an honest client message.
create function sdi_private.spatter_usage_reserve(p_user uuid,p_suggested_prompt text default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare c sdi_private.spatter_usage_controls; p jsonb; v_day date:=(clock_timestamp() at time zone 'utc')::date;
 v_minute text:=to_char(date_trunc('minute',clock_timestamp() at time zone 'utc'),'YYYY-MM-DD"T"HH24:MI');
 g integer; d integer; m integer; v_buckets text[]; b text; rid uuid;
begin
 if p_user is null or not exists(select 1 from auth.users where id=p_user) then
  return jsonb_build_object('allowed',false,'code','unauthorized'); end if;
 if exists(select 1 from sdi_private.account_controls where user_id=p_user and state<>'active') then
  return jsonb_build_object('allowed',false,'code','account_restricted'); end if;
 if (select emergency_stop from sdi_private.agent_global) then
  return jsonb_build_object('allowed',false,'code','emergency_stop'); end if;
 if p_suggested_prompt is not null and not (p_suggested_prompt=any(sdi_private.spatter_suggested_prompt_ids())) then
  return jsonb_build_object('allowed',false,'code','unknown_suggested_prompt'); end if;
 -- Free accounts may only send a suggested prompt; free text is refused before counting.
 if sdi_private.spatter_usage_plan(p_user)->>'plan'='free' and p_suggested_prompt is null then
  return jsonb_build_object('allowed',false,'code','suggested_prompt_required','plan','free','upgrade','creator_or_pro'); end if;
 select * into c from sdi_private.spatter_usage_controls;
 -- Serialize per account first, then lock the global day row; the order is fixed.
 perform pg_advisory_xact_lock(hashtextextended('sdi_spatter_usage:'||p_user::text,0));
 insert into sdi_private.spatter_usage_global(day) values(v_day) on conflict(day) do nothing;
 select used into g from sdi_private.spatter_usage_global where day=v_day for update;
 if g>=c.global_daily_cap then return jsonb_build_object('allowed',false,'code','global_limit'); end if;
 select coalesce((select used from sdi_private.spatter_usage_counters where user_id=p_user and bucket='minute:'||v_minute),0) into m;
 if m>=c.user_per_minute_cap then
  return jsonb_build_object('allowed',false,'code','rate_limited',
   'retry_after_seconds',greatest(1,60-floor(extract(second from clock_timestamp() at time zone 'utc'))::integer)); end if;
 select coalesce((select used from sdi_private.spatter_usage_counters where user_id=p_user and bucket='day:'||v_day::text),0) into d;
 if d>=c.user_daily_safety_cap then
  return jsonb_build_object('allowed',false,'code','daily_safety_limit','resets_at',(v_day+1)::timestamp at time zone 'utc'); end if;
 p:=sdi_private.spatter_usage_plan(p_user);
 if not (p->>'unlimited')::boolean and (p->>'remaining')::integer<=0 then
  return jsonb_build_object('allowed',false,'code','plan_allowance_exhausted','plan',p->>'plan','period',p->>'period','resets_at',p->'resets_at',
   'upgrade',case p->>'plan' when 'free' then 'creator_or_pro' else 'pro' end); end if;
 v_buckets:=array['minute:'||v_minute,'day:'||v_day::text];
 if p->>'bucket' is not null then v_buckets:=v_buckets||(p->>'bucket'); end if;
 foreach b in array v_buckets loop
  insert into sdi_private.spatter_usage_counters as u(user_id,bucket,used) values(p_user,b,1)
   on conflict(user_id,bucket) do update set used=u.used+1,updated_at=clock_timestamp();
 end loop;
 update sdi_private.spatter_usage_global set used=used+1,updated_at=clock_timestamp() where day=v_day;
 insert into sdi_private.spatter_usage_reservations(user_id,plan,buckets,day) values(p_user,p->>'plan',v_buckets,v_day) returning id into rid;
 return jsonb_build_object('allowed',true,'reservation',rid,'plan',p->>'plan','period',p->>'period',
  'remaining',case when (p->>'unlimited')::boolean then null else to_jsonb((p->>'remaining')::integer-1) end,'resets_at',p->'resets_at');
end $$;

-- Settle a reservation exactly once: 'commit' records provider units after a
-- delivered reply; 'release' refunds every counter after a provider failure.
create function sdi_private.spatter_usage_settle(p_reservation uuid,p_outcome text,p_units integer default 0) returns jsonb
language plpgsql security definer set search_path='' as $$
declare r sdi_private.spatter_usage_reservations; b text;
begin
 if p_outcome is null or p_outcome not in('commit','release') or p_units is null or p_units<0 then
  return jsonb_build_object('status','refused','reason','Invalid settlement.'); end if;
 select * into r from sdi_private.spatter_usage_reservations where id=p_reservation for update;
 if not found then return jsonb_build_object('status','refused','reason','Unknown reservation.'); end if;
 if r.state<>'reserved' then return jsonb_build_object('status','refused','reason','Reservation is already '||r.state||'.'); end if;
 if p_outcome='release' then
  foreach b in array r.buckets loop
   update sdi_private.spatter_usage_counters set used=greatest(used-1,0),updated_at=clock_timestamp() where user_id=r.user_id and bucket=b;
  end loop;
  update sdi_private.spatter_usage_global set used=greatest(used-1,0),updated_at=clock_timestamp() where day=r.day;
  update sdi_private.spatter_usage_reservations set state='released',settled_at=clock_timestamp() where id=r.id;
 else
  update sdi_private.spatter_usage_reservations set state='committed',units=p_units,settled_at=clock_timestamp() where id=r.id;
 end if;
 return jsonb_build_object('status','confirmed','state',case p_outcome when 'commit' then 'committed' else 'released' end);
end $$;

-- Expired rate buckets are pruned; day buckets are kept 400 days for audit.
-- Unsettled reservations older than 15 minutes stay counted (never refunded
-- silently) and are marked committed with zero units.
create function sdi_private.spatter_usage_sweep() returns integer language plpgsql security definer set search_path='' as $$
declare touched integer:=0; n integer;
begin
 delete from sdi_private.spatter_usage_counters where bucket like 'minute:%' and updated_at<clock_timestamp()-interval '2 hours';
 get diagnostics n=row_count; touched:=touched+n;
 delete from sdi_private.spatter_usage_counters where bucket like 'day:%' and updated_at<clock_timestamp()-interval '400 days';
 get diagnostics n=row_count; touched:=touched+n;
 update sdi_private.spatter_usage_reservations set state='committed',settled_at=clock_timestamp()
  where state='reserved' and created_at<clock_timestamp()-interval '15 minutes';
 get diagnostics n=row_count; touched:=touched+n;
 return touched;
end $$;

-- One service-only entry point for the handler: reserve | settle | sweep.
create function sdi_private.spatter_usage_meter(action text,p_user uuid default null,p_reservation uuid default null,
 p_outcome text default null,p_units integer default 0,p_suggested_prompt text default null) returns jsonb language plpgsql security definer set search_path='' as $$
begin
 if action='reserve' then return sdi_private.spatter_usage_reserve(p_user,p_suggested_prompt);
 elsif action='settle' then return sdi_private.spatter_usage_settle(p_reservation,p_outcome,p_units);
 elsif action='sweep' then return jsonb_build_object('touched',sdi_private.spatter_usage_sweep());
 end if;
 return jsonb_build_object('error','Unknown action.');
end $$;

-- Signed-in account's own allowance for Settings ("remaining prompts").
create function sdi_private.spatter_my_usage() returns jsonb language plpgsql security definer set search_path='' as $$
begin
 if not sdi_private.account_active() then return jsonb_build_object('error','Sign in to view your Spatter allowance.'); end if;
 return (sdi_private.spatter_usage_plan(auth.uid())-'bucket')
  ||jsonb_build_object('service',case when (select emergency_stop from sdi_private.agent_global) then 'paused' else 'metered' end);
end $$;

-- Owner/admin controls with audit. Reading needs overview; changing needs the owner.
create function sdi_private.spatter_usage_admin(action text,revision bigint default null,payload jsonb default '{}',reason text default '') returns jsonb
language plpgsql security definer set search_path='' as $$
declare c sdi_private.spatter_usage_controls; is_owner boolean; v_day date:=(clock_timestamp() at time zone 'utc')::date; next_rev bigint;
begin
 if not sdi_private.admin_can('overview') or not sdi_private.account_active() then return jsonb_build_object('error','Current administrator MFA session required.'); end if;
 select r.owner into is_owner from sdi_private.admin_roles r where r.user_id=auth.uid() and r.enabled;
 select * into c from sdi_private.spatter_usage_controls;
 if action='get' then
  return jsonb_build_object('controls',to_jsonb(c)-'singleton'-'updated_by',
   'global_used_today',coalesce((select g.used from sdi_private.spatter_usage_global g where g.day=v_day),0),
   'committed_units_today',coalesce((select sum(r.units) from sdi_private.spatter_usage_reservations r where r.day=v_day and r.state='committed'),0),
   'emergency_stop',(select a.emergency_stop from sdi_private.agent_global a));
 elsif action='set' then
  if not coalesce(is_owner,false) then return jsonb_build_object('error','Only the owner can change Spatter limits.'); end if;
  if spatter_usage_admin.revision is distinct from c.revision then return jsonb_build_object('error','Limits changed elsewhere; reload.','revision',c.revision); end if;
  if length(trim(coalesce(spatter_usage_admin.reason,''))) not between 1 and 2000 then return jsonb_build_object('error','A reason is required.'); end if;
  if payload is null or jsonb_typeof(payload)<>'object' or exists(select 1 from jsonb_object_keys(payload) k
   where k not in('global_daily_cap','user_daily_safety_cap','user_per_minute_cap','free_prompts','creator_period_prompts')) then
   return jsonb_build_object('error','Unknown limit.'); end if;
  begin
   update sdi_private.spatter_usage_controls u set
    global_daily_cap=coalesce((payload->>'global_daily_cap')::integer,u.global_daily_cap),
    user_daily_safety_cap=coalesce((payload->>'user_daily_safety_cap')::integer,u.user_daily_safety_cap),
    user_per_minute_cap=coalesce((payload->>'user_per_minute_cap')::integer,u.user_per_minute_cap),
    free_prompts=coalesce((payload->>'free_prompts')::integer,u.free_prompts),
    creator_period_prompts=coalesce((payload->>'creator_period_prompts')::integer,u.creator_period_prompts),
    revision=c.revision+1,updated_by=auth.uid(),updated_at=clock_timestamp()
   returning u.revision into next_rev;
  exception when check_violation or invalid_text_representation or numeric_value_out_of_range then
   return jsonb_build_object('error','A limit is outside its allowed range.');
  end;
  insert into sdi_private.agent_audit(actor,agent_key,action,reason)
   values(auth.uid(),'spatter_advice','set_usage_limits '||payload::text,trim(spatter_usage_admin.reason));
  return jsonb_build_object('status','confirmed','revision',next_rev);
 end if;
 return jsonb_build_object('error','Unknown action.');
end $$;

