-- ===== agent-proposals.sql (sha256 51ad16a4d407c0ef) =====
-- Unapplied candidate. Install after spatter-draft-jobs.sql (needs agent-controls.sql
-- and admin-users.sql). Approval inbox for actions an agent proposes above its caps
-- (#284): a running agent with the `propose` permission files a proposal instead of
-- acting; only the owner approves or rejects it, with a reason and an audit row; the
-- service worker executes approved proposals and records the outcome; a pending
-- proposal expires after fourteen days. Nothing executes when a proposal is filed.
begin;
create table sdi_private.agent_proposals (
 id uuid primary key default gen_random_uuid(),
 agent_key text not null references sdi_private.agents(key) on delete cascade,
 run_id uuid references sdi_private.agent_runs(id) on delete set null,
 kind text not null check(kind ~ '^[a-z0-9_]{1,40}$'),
 summary text not null check(length(summary) between 1 and 500),
 payload jsonb not null default '{}' check(jsonb_typeof(payload)='object' and length(payload::text)<=16384),
 estimated_cost_minor bigint not null default 0 check(estimated_cost_minor>=0),
 cap_reason text not null check(length(cap_reason) between 1 and 200),
 state text not null default 'pending' check(state in('pending','approved','rejected','expired','executed','failed')),
 proposed_at timestamptz not null default clock_timestamp(),
 expires_at timestamptz not null default clock_timestamp()+interval '14 days',
 decided_by uuid references auth.users(id) on delete set null, decided_at timestamptz,
 decision_note text not null default '' check(length(decision_note)<=2000),
 executed_run uuid references sdi_private.agent_runs(id) on delete set null,
 outcome text not null default '' check(length(outcome)<=2000),
 revision bigint not null default 1
);
alter table sdi_private.agent_proposals enable row level security;
revoke all on sdi_private.agent_proposals from public,anon,authenticated;
create index agent_proposals_inbox on sdi_private.agent_proposals(state,proposed_at desc);
create index agent_proposals_agent on sdi_private.agent_proposals(agent_key,state);

-- Service: a live run files a proposal. Idempotent for an identical pending proposal.
create function sdi_private.agent_propose(run uuid,kind text,summary text,payload jsonb default '{}',
 estimated_cost_minor bigint default 0,cap_reason text default 'cap') returns jsonb
language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare r sdi_private.agent_runs; a sdi_private.agents; p sdi_private.agent_proposals;
begin
 select * into r from sdi_private.agent_runs where id=run and state='running';
 if not found then return jsonb_build_object('error','A running agent run is required to propose.'); end if;
 select * into a from sdi_private.agents where key=r.agent_key;
 if a.paused or (select emergency_stop from sdi_private.agent_global) then return jsonb_build_object('error','Agent is paused.'); end if;
 if not ('propose' = any(a.permissions)) then return jsonb_build_object('error','This agent may not propose actions.'); end if;
 if kind is null or kind !~ '^[a-z0-9_]{1,40}$' or summary is null or length(trim(summary)) not between 1 and 500
  or payload is null or jsonb_typeof(payload)<>'object' or length(payload::text)>16384
  or estimated_cost_minor is null or estimated_cost_minor<0 or cap_reason is null or length(trim(cap_reason)) not between 1 and 200 then
  return jsonb_build_object('error','Proposal needs a kind, a summary, an object payload, a non-negative estimate and the cap it exceeds.'); end if;
 select * into p from sdi_private.agent_proposals where agent_key=a.key and state='pending' and agent_proposals.kind=agent_propose.kind
  and agent_proposals.payload=agent_propose.payload and expires_at>clock_timestamp() limit 1;
 if found then return jsonb_build_object('proposal',p.id,'state','pending','expires_at',p.expires_at,'duplicate',true); end if;
 if (select count(*) from sdi_private.agent_proposals where agent_key=a.key and state='pending' and expires_at>clock_timestamp())>=50 then
  return jsonb_build_object('error','This agent already has fifty pending proposals. Wait for owner decisions.'); end if;
 insert into sdi_private.agent_proposals(agent_key,run_id,kind,summary,payload,estimated_cost_minor,cap_reason)
  values(a.key,r.id,kind,trim(summary),payload,estimated_cost_minor,trim(cap_reason)) returning * into p;
 return jsonb_build_object('proposal',p.id,'state','pending','expires_at',p.expires_at);
end $$;

-- Service: expire stale proposals, then hand approved ones to the worker (oldest first).
create function sdi_private.agent_proposals_due(agent text default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare items jsonb;
begin
 update sdi_private.agent_proposals set state='expired',revision=revision+1 where state='pending' and expires_at<=clock_timestamp();
 if (select emergency_stop from sdi_private.agent_global) then return jsonb_build_object('proposals','[]'::jsonb,'reason','Emergency stop is active.'); end if;
 select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into items from (
  select p.id,p.agent_key,p.kind,p.summary,p.payload,p.estimated_cost_minor,p.decided_at,p.decision_note,p.revision
  from sdi_private.agent_proposals p join sdi_private.agents a on a.key=p.agent_key
  where p.state='approved' and not a.paused and (agent is null or p.agent_key=agent)
  order by p.decided_at,p.id limit 20) item;
 return jsonb_build_object('proposals',items);
end $$;

-- Service: the executing run records the outcome of an approved proposal.
create function sdi_private.agent_proposal_finish(proposal uuid,run uuid,state text,outcome text default '') returns boolean
language plpgsql security definer set search_path='' as $$
begin
 if state not in('executed','failed') then return false; end if;
 update sdi_private.agent_proposals p set state=agent_proposal_finish.state,executed_run=run,outcome=left(coalesce(agent_proposal_finish.outcome,''),2000),revision=p.revision+1
  where p.id=proposal and p.state='approved'
  and exists(select 1 from sdi_private.agent_runs r where r.id=run and r.state='running' and r.agent_key=p.agent_key);
 return found;
end $$;
revoke all on function sdi_private.agent_propose(uuid,text,text,jsonb,bigint,text),sdi_private.agent_proposals_due(text),
 sdi_private.agent_proposal_finish(uuid,uuid,text,text) from public,anon,authenticated;
grant execute on function sdi_private.agent_propose(uuid,text,text,jsonb,bigint,text),sdi_private.agent_proposals_due(text),
 sdi_private.agent_proposal_finish(uuid,uuid,text,text) to service_role;

-- Administrators read the inbox; only the owner decides, with a reason, audited.
create function sdi_private.agent_proposal_admin(action text,proposal uuid default null,revision bigint default null,
 reason text default '',agent text default null) returns jsonb
language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare p sdi_private.agent_proposals; items jsonb; is_owner boolean;
begin
 if not sdi_private.admin_can('overview') or not sdi_private.account_active() then return jsonb_build_object('error','Current administrator MFA session required.'); end if;
 if action='inbox' then
  update sdi_private.agent_proposals set state='expired',revision=revision+1 where state='pending' and expires_at<=clock_timestamp();
  select coalesce(jsonb_agg(row_to_json(item)),'[]'::jsonb) into items from (
   select pr.id,pr.agent_key,pr.kind,pr.summary,pr.payload,pr.estimated_cost_minor,pr.cap_reason,pr.state,pr.proposed_at,pr.expires_at,
    pr.decided_by,pr.decided_at,pr.decision_note,pr.outcome,pr.revision
   from sdi_private.agent_proposals pr where (agent is null or pr.agent_key=agent)
   order by case pr.state when 'pending' then 0 when 'approved' then 1 else 2 end,pr.proposed_at desc,pr.id limit 100) item;
  return jsonb_build_object('proposals',items,'pending',(select count(*) from sdi_private.agent_proposals where state='pending'));
 end if;
 select owner into is_owner from sdi_private.admin_roles where user_id=auth.uid() and enabled;
 if not coalesce(is_owner,false) then return jsonb_build_object('error','Owner permission required for proposal decisions.'); end if;
 if reason is null or length(trim(reason)) not between 1 and 2000 then return jsonb_build_object('error','A reason is required.'); end if;
 if action not in('approve','reject') then return jsonb_build_object('error','Unsupported proposal operation.'); end if;
 select * into p from sdi_private.agent_proposals where id=proposal for update;
 if not found or revision is distinct from p.revision then return jsonb_build_object('error','Proposal changed. Refresh before deciding.'); end if;
 if p.state<>'pending' then return jsonb_build_object('error','Only a pending proposal can be decided.'); end if;
 if p.expires_at<=clock_timestamp() then
  update sdi_private.agent_proposals set state='expired',revision=revision+1 where id=p.id;
  return jsonb_build_object('error','This proposal expired before a decision.'); end if;
 update sdi_private.agent_proposals set state=case action when 'approve' then 'approved' else 'rejected' end,
  decided_by=auth.uid(),decided_at=clock_timestamp(),decision_note=trim(reason),revision=revision+1 where id=p.id;
 insert into sdi_private.agent_audit(actor,agent_key,action,reason) values(auth.uid(),p.agent_key,'proposal_'||action||' '||p.id,trim(reason));
 return jsonb_build_object('status','confirmed','state',case action when 'approve' then 'approved' else 'rejected' end,'revision',p.revision+1);
end $$;
revoke all on function sdi_private.agent_proposal_admin(text,uuid,bigint,text,text) from public,anon;
grant execute on function sdi_private.agent_proposal_admin(text,uuid,bigint,text,text) to authenticated;

create function public.sdi_agent_propose(run uuid,kind text,summary text,payload jsonb default '{}',estimated_cost_minor bigint default 0,cap_reason text default 'cap') returns jsonb
language sql security invoker set search_path='' as $$select sdi_private.agent_propose(run,kind,summary,payload,estimated_cost_minor,cap_reason)$$;
create function public.sdi_agent_proposals_due(agent text default null) returns jsonb
language sql security invoker set search_path='' as $$select sdi_private.agent_proposals_due(agent)$$;
create function public.sdi_agent_proposal_finish(proposal uuid,run uuid,state text,outcome text default '') returns boolean
language sql security invoker set search_path='' as $$select sdi_private.agent_proposal_finish(proposal,run,state,outcome)$$;
revoke all on function public.sdi_agent_propose(uuid,text,text,jsonb,bigint,text),public.sdi_agent_proposals_due(text),
 public.sdi_agent_proposal_finish(uuid,uuid,text,text) from public,anon,authenticated;
grant execute on function public.sdi_agent_propose(uuid,text,text,jsonb,bigint,text),public.sdi_agent_proposals_due(text),
 public.sdi_agent_proposal_finish(uuid,uuid,text,text) to service_role;
create function public.sdi_agent_proposal_admin(action text,proposal uuid default null,revision bigint default null,reason text default '',agent text default null) returns jsonb
language sql security invoker set search_path='' as $$select sdi_private.agent_proposal_admin(action,proposal,revision,reason,agent)$$;
revoke all on function public.sdi_agent_proposal_admin(text,uuid,bigint,text,text) from public,anon;
grant execute on function public.sdi_agent_proposal_admin(text,uuid,bigint,text,text) to authenticated;
commit;

-- ===== worker-configuration.sql (sha256 59e9dacf36e410ce) =====
-- Unapplied candidate. Install after agent-proposals.sql (needs admin-hardening.sql).
-- Masked provider-configuration health (#248): each service worker reports which of
-- its named settings are present as booleans only; the function refuses any other
-- value type, so no key, URL or identifier can ever be stored, and administrators
-- read presence, staleness and nothing else.
begin;
create table sdi_private.worker_configuration (
 worker text primary key check(worker ~ '^[a-z0-9_-]{1,40}$'),
 reported_at timestamptz not null default clock_timestamp(),
 settings jsonb not null default '{}' check(jsonb_typeof(settings)='object' and length(settings::text)<=4096)
);
alter table sdi_private.worker_configuration enable row level security;
revoke all on sdi_private.worker_configuration from public,anon,authenticated;

create function sdi_private.worker_configuration_report(worker text,settings jsonb) returns boolean
language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare entry record; n integer:=0;
begin
 if worker is null or worker !~ '^[a-z0-9_-]{1,40}$' or settings is null or jsonb_typeof(settings)<>'object' then return false; end if;
 for entry in select key,value from jsonb_each(settings) loop
  n:=n+1;
  if n>40 or entry.key !~ '^[a-z0-9_]{1,40}$' or jsonb_typeof(entry.value)<>'boolean' then return false; end if;
 end loop;
 insert into sdi_private.worker_configuration(worker,settings) values(worker,settings)
 on conflict(worker) do update set reported_at=clock_timestamp(),settings=excluded.settings;
 return true;
end $$;
revoke all on function sdi_private.worker_configuration_report(text,jsonb) from public,anon,authenticated;
grant execute on function sdi_private.worker_configuration_report(text,jsonb) to service_role;

create function sdi_private.admin_configuration() returns jsonb language plpgsql security definer set search_path='' as $$
declare denial jsonb; items jsonb;
begin
 denial:=sdi_private.admin_gate('admin_configuration','overview',false,120);
 if denial is not null then return denial; end if;
 select coalesce(jsonb_agg(jsonb_build_object('worker',c.worker,'reported_at',c.reported_at,
   'stale',c.reported_at<clock_timestamp()-interval '1 day','settings',c.settings,
   'missing',(select coalesce(jsonb_agg(e.key order by e.key),'[]'::jsonb) from jsonb_each(c.settings) e where e.value='false'::jsonb)) order by c.worker),'[]'::jsonb)
  into items from sdi_private.worker_configuration c;
 return jsonb_build_object('workers',items,'note','Presence only. Values are never stored or shown; a missing setting means the worker reported it absent.');
end $$;
revoke all on function sdi_private.admin_configuration() from public,anon;
grant execute on function sdi_private.admin_configuration() to authenticated;

create function public.sdi_worker_configuration(worker text,settings jsonb) returns boolean language sql security invoker set search_path='' as $$select sdi_private.worker_configuration_report(worker,settings)$$;
revoke all on function public.sdi_worker_configuration(text,jsonb) from public,anon,authenticated;
grant execute on function public.sdi_worker_configuration(text,jsonb) to service_role;
create function public.sdi_admin_configuration() returns jsonb language sql security invoker set search_path='' as $$select sdi_private.admin_configuration()$$;
revoke all on function public.sdi_admin_configuration() from public,anon;
grant execute on function public.sdi_admin_configuration() to authenticated;
commit;

-- ===== users-profiles.sql (sha256 e878cd13064f1f3f) =====
-- Unapplied candidate. Install last. The member profile row the native app reads and
-- writes as `users` (Models.swift `UserProfile`, AuthService): the member inserts their
-- own row after sign-up and may edit only the editable columns; `role` and
-- `subscription_tier` are server-owned and never client-writable. Administrator
-- authority lives in sdi_private.admin_roles, never in this row. Rows are private to
-- their member; community surfaces carry creator names as snapshots of their own.
begin;
create table public.users (
 id uuid primary key references auth.users(id) on delete cascade,
 email text check(email is null or (length(email) between 3 and 254 and position('@' in email)>1)),
 username text unique check(username is null or length(trim(username)) between 1 and 80),
 bio text not null default '' check(length(bio)<=2000),
 avatar_url text check(avatar_url is null or avatar_url ~ '^https://[^ ]{1,2000}$'),
 role text not null default 'user' check(role in('user','creator','moderator','superadmin')),
 subscription_tier text check(subscription_tier is null or subscription_tier in('free','monthly_4_99','monthly_9_99')),
 onboarded boolean not null default false,
 skill_level text check(skill_level is null or length(skill_level)<=40),
 interests text[] not null default '{}' check(cardinality(interests)<=20),
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now()
);
alter table public.users enable row level security;
revoke all on public.users from public,anon;
grant select on public.users to authenticated;
grant insert(id,email,username,bio,avatar_url,onboarded,skill_level,interests) on public.users to authenticated;
grant update(username,bio,avatar_url,onboarded,skill_level,interests) on public.users to authenticated;
create policy users_read_own on public.users for select to authenticated using (id=auth.uid());
create policy users_insert_own on public.users for insert to authenticated with check (id=auth.uid());
create policy users_update_own on public.users for update to authenticated using (id=auth.uid()) with check (id=auth.uid());
create function sdi_private.users_touch() returns trigger language plpgsql set search_path='' as $$
begin new.updated_at=clock_timestamp(); return new; end $$;
create trigger users_touch before update on public.users for each row execute function sdi_private.users_touch();
-- Handles are unique regardless of letter case (#224). A changed username must
-- follow the public handle rules the app enforces (CreatorHandle): 3-30 ASCII
-- letters, digits or underscores, starting with a letter or digit, not reserved.
-- Sign-up rows keep the original 1-80 character check until the member edits.
create unique index users_username_ci on public.users(lower(username)) where username is not null;
create function sdi_private.users_handle_rules() returns trigger language plpgsql set search_path='' as $$
begin
 if new.username is distinct from old.username then
  if new.username is null or new.username !~ '^[A-Za-z0-9][A-Za-z0-9_]{2,29}$'
   or lower(new.username) in('admin','administrator','owner','moderator','support','system','official',
    'stickdeath','stickdeathinfinity','sdi','spatter','root') then
   raise exception 'Choose a 3-30 character handle of letters, digits or underscores that is not reserved.' using errcode='23514';
  end if;
 end if;
 return new;
end $$;
create trigger users_handle_rules before update of username on public.users for each row execute function sdi_private.users_handle_rules();
-- Avatar storage (#224): a public-read bucket holding one bounded JPEG per member
-- at `<account>/avatar.jpg` (AvatarImagePolicy). Members may write, replace and
-- delete only their own object. Applied only where the Supabase storage schema
-- exists; the local SQL harness has no storage schema and skips this block.
do $avatars$
begin
 if to_regclass('storage.buckets') is not null and to_regclass('storage.objects') is not null then
  execute $q$insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
   values('avatars','avatars',true,307200,array['image/jpeg'])
   on conflict(id) do update set public=true,file_size_limit=307200,allowed_mime_types=array['image/jpeg']$q$;
  execute $q$create policy avatars_owner_read on storage.objects for select to authenticated
   using (bucket_id='avatars' and name=(auth.uid()::text||'/avatar.jpg'))$q$;
  execute $q$create policy avatars_owner_insert on storage.objects for insert to authenticated
   with check (bucket_id='avatars' and name=(auth.uid()::text||'/avatar.jpg'))$q$;
  execute $q$create policy avatars_owner_update on storage.objects for update to authenticated
   using (bucket_id='avatars' and name=(auth.uid()::text||'/avatar.jpg'))
   with check (bucket_id='avatars' and name=(auth.uid()::text||'/avatar.jpg'))$q$;
  execute $q$create policy avatars_owner_delete on storage.objects for delete to authenticated
   using (bucket_id='avatars' and name=(auth.uid()::text||'/avatar.jpg'))$q$;
 end if;
end $avatars$;
commit;

-- ===== diagnostics.sql (sha256 a4382e5b36d4595a) =====
-- Unapplied candidate. Install after users-profiles.sql (needs admin-users.sql for
-- account_active, admin-hardening.sql for admin_gate, agent-controls.sql for agent_runs
-- and pgcrypto in extensions). First-party, opt-in diagnostics intake for #291.
--
-- Contract v1 (shared by iOS DiagnosticsReport.swift and Android DiagnosticsReport.kt):
--   {"v":1,"platform":"ios"|"android","app_version":"1.2.3"|"unknown","build":"123"|"unknown",
--    "os_major":0..99,"day":"YYYY-MM-DD","counters":{"<allowlisted>":1..10000,...}}
-- Only completed UTC days within the last 30 are accepted. Unknown keys, unknown counters,
-- free text, identifiers and precise times are refused, not stored. Stored rows carry no
-- account id: the account is used only for the opt-in assertion, a per-account rate limit
-- and duplicate suppression (diagnostic_receipts, deleted with the account and after 35 days).
-- Raw day rows are kept 90 days. No third-party SDK or service receives any of this.
begin;
create table sdi_private.diagnostic_reports (
 id uuid primary key default gen_random_uuid(),
 platform text not null check(platform in('ios','android')),
 app_version text not null check(app_version ~ '^([0-9]{1,4}(\.[0-9]{1,4}){0,2}|unknown)$'),
 build text not null check(build ~ '^([0-9]{1,9}|unknown)$'),
 os_major smallint not null check(os_major between 0 and 99),
 day date not null,
 counters jsonb not null check(jsonb_typeof(counters)='object' and length(counters::text)<=512),
 received_day date not null default (clock_timestamp() at time zone 'utc')::date
);
create table sdi_private.diagnostic_receipts (
 user_id uuid not null references auth.users(id) on delete cascade,
 bucket text not null check(bucket ~ '^[0-9a-f]{64}$'),
 received_at timestamptz not null default clock_timestamp(),
 primary key(user_id,bucket)
);
alter table sdi_private.diagnostic_reports enable row level security;
alter table sdi_private.diagnostic_receipts enable row level security;
revoke all on sdi_private.diagnostic_reports,sdi_private.diagnostic_receipts from public,anon,authenticated;
create index diagnostic_reports_day on sdi_private.diagnostic_reports(day,platform,build);
create index diagnostic_receipts_recent on sdi_private.diagnostic_receipts(user_id,received_at);

create function sdi_private.diagnostic_counters() returns text[] language sql immutable set search_path='' as $$
 select array['app_launch','crash','hang','cpu_exception','disk_write_exception','memory_limit_exit','watchdog_exit','uncaught_exception']
$$;
revoke all on function sdi_private.diagnostic_counters() from public,anon;
grant execute on function sdi_private.diagnostic_counters() to authenticated,service_role;

create function sdi_private.diagnostics_submit(report jsonb,consent boolean default false) returns jsonb
language plpgsql security definer set search_path='' as $$
declare actor uuid:=auth.uid(); today date:=(clock_timestamp() at time zone 'utc')::date; report_day date; key text; value jsonb;
 clean jsonb:='{}'::jsonb; bucket_key text;
begin
 if actor is null or not sdi_private.account_active() then
  return jsonb_build_object('error','Sign in to send diagnostics.','code','signed_out'); end if;
 if consent is distinct from true then
  return jsonb_build_object('error','Diagnostics consent is required.','code','consent_required'); end if;
 if report is null or jsonb_typeof(report)<>'object' or length(report::text)>2048
  or (select array_agg(k order by k) from jsonb_object_keys(report) k)<>array['app_version','build','counters','day','os_major','platform','v']
  or report->'v'<>'1'::jsonb
  or jsonb_typeof(report->'platform')<>'string' or report->>'platform' not in('ios','android')
  or jsonb_typeof(report->'app_version')<>'string' or report->>'app_version' !~ '^([0-9]{1,4}(\.[0-9]{1,4}){0,2}|unknown)$'
  or jsonb_typeof(report->'build')<>'string' or report->>'build' !~ '^([0-9]{1,9}|unknown)$'
  or jsonb_typeof(report->'os_major')<>'number' or report->>'os_major' !~ '^[0-9]{1,2}$'
  or jsonb_typeof(report->'day')<>'string' or report->>'day' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
  or jsonb_typeof(report->'counters')<>'object' then
  return jsonb_build_object('error','Diagnostics report does not match the contract.','code','invalid'); end if;
 begin report_day:=(report->>'day')::date;
 exception when others then return jsonb_build_object('error','Diagnostics report does not match the contract.','code','invalid'); end;
 if to_char(report_day,'YYYY-MM-DD')<>report->>'day' or report_day>=today or report_day<today-30 then
  return jsonb_build_object('error','Only completed days from the last 30 days are accepted.','code','invalid'); end if;
 for key,value in select * from jsonb_each(report->'counters') loop
  if not key=any(sdi_private.diagnostic_counters()) or jsonb_typeof(value)<>'number' or value::text !~ '^[0-9]{1,5}$'
   or value::text::integer not between 1 and 10000 then
   return jsonb_build_object('error','Diagnostics report does not match the contract.','code','invalid'); end if;
  clean:=clean||jsonb_build_object(key,value::text::integer);
 end loop;
 if clean='{}'::jsonb then return jsonb_build_object('error','Diagnostics report does not match the contract.','code','invalid'); end if;
 bucket_key:=encode(extensions.digest(concat_ws('|',report->>'platform',report->>'day',report->>'app_version',report->>'build',report->>'os_major'),'sha256'),'hex');
 -- One row per account and bucket: serialize this account's submissions.
 perform pg_advisory_xact_lock(hashtextextended('sdi.diagnostics.'||actor::text,0));
 if exists(select 1 from sdi_private.diagnostic_receipts r where r.user_id=actor and r.bucket=bucket_key) then
  return jsonb_build_object('status','duplicate'); end if;
 if (select count(*) from sdi_private.diagnostic_receipts r where r.user_id=actor and r.received_at>clock_timestamp()-interval '1 day')>=20 then
  return jsonb_build_object('error','Daily diagnostics limit reached.','code','rate_limited'); end if;
 insert into sdi_private.diagnostic_receipts(user_id,bucket) values(actor,bucket_key);
 insert into sdi_private.diagnostic_reports(platform,app_version,build,os_major,day,counters)
 values(report->>'platform',report->>'app_version',report->>'build',(report->>'os_major')::smallint,report_day,clean);
 return jsonb_build_object('status','accepted');
end $$;
revoke all on function sdi_private.diagnostics_submit(jsonb,boolean) from public,anon;
grant execute on function sdi_private.diagnostics_submit(jsonb,boolean) to authenticated;
create function public.sdi_diagnostics_submit(report jsonb,consent boolean default false) returns jsonb
language sql security invoker set search_path='' as $$select sdi_private.diagnostics_submit(report,consent)$$;
revoke all on function public.sdi_diagnostics_submit(jsonb,boolean) from public,anon;
grant execute on function public.sdi_diagnostics_submit(jsonb,boolean) to authenticated;

-- Command-center read model (overview capability, MFA). Real counts only; a spike is a
-- (platform, build) whose crash+uncaught_exception total on the latest completed day is at
-- least 5 and more than five times its mean over the seven days before. Failed agent runs
-- in the last 24 hours come from agent_runs. Nothing is estimated or extrapolated.
create function sdi_private.diagnostics_admin(action text,days integer default 14) returns jsonb
language plpgsql security definer set search_path='' as $$
declare denial jsonb; today date:=(clock_timestamp() at time zone 'utc')::date; latest date; totals jsonb; spikes jsonb;
begin
 denial:=sdi_private.admin_gate('diagnostics_admin.'||coalesce(action,'?'),'overview',false,60);
 if denial is not null then return denial; end if;
 if action is distinct from 'summary' then return jsonb_build_object('error','Unsupported diagnostics operation.'); end if;
 if days is null or days not between 1 and 90 then return jsonb_build_object('error','Choose between 1 and 90 days.'); end if;
 latest:=today-1;
 select coalesce(jsonb_agg(row_to_json(t) order by t.day desc,t.platform,t.build,t.counter),'[]'::jsonb) into totals from (
  select d.day,d.platform,d.app_version,d.build,c.key as counter,sum(c.value::text::bigint) as total,count(*) as reports
  from sdi_private.diagnostic_reports d cross join lateral jsonb_each(d.counters) c
  where d.day>=today-days group by d.day,d.platform,d.app_version,d.build,c.key) t;
 select coalesce(jsonb_agg(row_to_json(s) order by s.latest_total desc),'[]'::jsonb) into spikes from (
  select x.platform,x.build,
   sum(x.n) filter(where x.day=latest) as latest_total,
   round(coalesce(sum(x.n) filter(where x.day between latest-7 and latest-1),0)/7.0,2) as prior_daily_mean
  from (select d.day,d.platform,d.build,coalesce((d.counters->>'crash')::bigint,0)+coalesce((d.counters->>'uncaught_exception')::bigint,0) as n
        from sdi_private.diagnostic_reports d where d.day between latest-7 and latest) x
  group by x.platform,x.build
  having coalesce(sum(x.n) filter(where x.day=latest),0)>=5
   and coalesce(sum(x.n) filter(where x.day=latest),0)>5*coalesce(sum(x.n) filter(where x.day between latest-7 and latest-1),0)/7.0) s;
 return jsonb_build_object('since',today-days,'latest_complete_day',latest,
  'reports',(select count(*) from sdi_private.diagnostic_reports d where d.day>=today-days),
  'totals',totals,'crash_spikes',spikes,
  'agent_runs_failed_24h',(select count(*) from sdi_private.agent_runs r where r.state='failed' and r.started_at>clock_timestamp()-interval '24 hours'),
  'retention_days',90);
end $$;
revoke all on function sdi_private.diagnostics_admin(text,integer) from public,anon;
grant execute on function sdi_private.diagnostics_admin(text,integer) to authenticated;
create function public.sdi_diagnostics_admin(action text,days integer default 14) returns jsonb
language sql security invoker set search_path='' as $$select sdi_private.diagnostics_admin(action,days)$$;
revoke all on function public.sdi_diagnostics_admin(text,integer) from public,anon;
grant execute on function public.sdi_diagnostics_admin(text,integer) to authenticated;

-- Retention sweep for the service scheduler: day rows after 90 days, receipts after 35.
create function sdi_private.diagnostics_retention() returns jsonb language plpgsql security definer set search_path='' as $$
declare reports integer; receipts integer;
begin
 delete from sdi_private.diagnostic_reports where day<(clock_timestamp() at time zone 'utc')::date-90;
 get diagnostics reports=row_count;
 delete from sdi_private.diagnostic_receipts where received_at<clock_timestamp()-interval '35 days';
 get diagnostics receipts=row_count;
 return jsonb_build_object('reports_deleted',reports,'receipts_deleted',receipts);
end $$;
revoke all on function sdi_private.diagnostics_retention() from public,anon,authenticated;
grant execute on function sdi_private.diagnostics_retention() to service_role;
create function public.sdi_diagnostics_retention() returns jsonb language sql security invoker set search_path='' as $$select sdi_private.diagnostics_retention()$$;
revoke all on function public.sdi_diagnostics_retention() from public,anon,authenticated;
grant execute on function public.sdi_diagnostics_retention() to service_role;
commit;

-- ===== rate-limits.sql (sha256 6cee3a5be4b78398) =====
-- Unapplied candidate (#263). Install after worker-configuration.sql. Daily account
-- quotas for the paths the per-minute budgets do not bound: media transfer (intake
-- registrations and bytes), publication requests and room invitations. The limits
-- are owner configuration in sdi_private.resource_quotas (candidate defaults sized
-- for the existing single-project infrastructure, not measured capacity). Enforcement
-- is a BEFORE INSERT trigger, so every insert path is bounded, including service
-- paths; a refusal aborts the whole statement with SQLSTATE P0001 and a plain
-- message, and nothing partial is written. Members read their own usage with
-- sdi_quota_status; nothing here estimates provider cost or spends money. AI runs
-- are already bounded by agent daily run caps and monthly cost caps (agent-controls).
begin;
create table sdi_private.resource_quotas (
 key text primary key check(key in('upload_registrations','upload_bytes','publish_requests','room_invites')),
 per_day bigint not null check(per_day between 0 and 1099511627776),
 description text not null check(length(description) between 1 and 200),
 updated_at timestamptz not null default clock_timestamp()
);
alter table sdi_private.resource_quotas enable row level security;
revoke all on sdi_private.resource_quotas from public,anon,authenticated;
insert into sdi_private.resource_quotas(key,per_day,description) values
 ('upload_registrations',20,'Render intake registrations per creator per rolling 24 hours'),
 ('upload_bytes',8589934592,'Registered render bytes per creator per rolling 24 hours (8 GiB)'),
 ('publish_requests',30,'Publication jobs created per creator per rolling 24 hours'),
 ('room_invites',50,'Room invitation codes created per room owner per rolling 24 hours');

create function sdi_private.quota(key text) returns bigint language sql stable security definer set search_path='' as $$
 select q.per_day from sdi_private.resource_quotas q where q.key=quota.key
$$;
revoke all on function sdi_private.quota(text) from public,anon,authenticated;

-- Invitations had no creation time; existing rows count as created at install.
alter table sdi_private.room_invites add column if not exists created_at timestamptz not null default clock_timestamp();
create index if not exists room_invites_created on sdi_private.room_invites(room_id,created_at);
create index if not exists upload_registrations_creator_created on sdi_private.upload_registrations(creator,created_at);
create index if not exists publish_jobs_creator_created on sdi_private.publish_jobs(creator,created_at);

create function sdi_private.enforce_upload_quota() returns trigger language plpgsql security definer set search_path='' as $$
declare used bigint; bytes bigint; incoming bigint;
begin
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(new.creator::text,263));
 select count(*),coalesce(sum(case when (u.metadata->>'size') ~ '^[0-9]{1,13}$' then (u.metadata->>'size')::bigint else 0 end),0) into used,bytes
  from sdi_private.upload_registrations u where u.creator=new.creator and u.created_at>clock_timestamp()-interval '1 day';
 incoming:=case when (new.metadata->>'size') ~ '^[0-9]{1,13}$' then (new.metadata->>'size')::bigint else 0 end;
 if used>=sdi_private.quota('upload_registrations') then
  raise exception 'Daily upload limit reached. Try again tomorrow.' using errcode='P0001';
 end if;
 if bytes+incoming>sdi_private.quota('upload_bytes') then
  raise exception 'Daily upload size limit reached. Try again tomorrow.' using errcode='P0001';
 end if;
 return new;
end $$;
create trigger enforce_upload_quota before insert on sdi_private.upload_registrations for each row execute function sdi_private.enforce_upload_quota();

create function sdi_private.enforce_publish_quota() returns trigger language plpgsql security definer set search_path='' as $$
begin
 -- A duplicate request is left to the unique constraint (no new job, no quota use).
 if exists(select 1 from sdi_private.publish_jobs j where j.review_id=new.review_id and j.review_version=new.review_version and j.destination=new.destination) then
  return new; end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(new.creator::text,264));
 if (select count(*) from sdi_private.publish_jobs j where j.creator=new.creator and j.created_at>clock_timestamp()-interval '1 day')>=sdi_private.quota('publish_requests') then
  raise exception 'Daily publishing limit reached. Try again tomorrow.' using errcode='P0001';
 end if;
 return new;
end $$;
create trigger enforce_publish_quota before insert on sdi_private.publish_jobs for each row execute function sdi_private.enforce_publish_quota();

create function sdi_private.enforce_invite_quota() returns trigger language plpgsql security definer set search_path='' as $$
declare owner uuid;
begin
 select r.owner_id into owner from public.sdi_rooms r where r.id=new.room_id;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(coalesce(owner,new.room_id)::text,265));
 if (select count(*) from sdi_private.room_invites i join public.sdi_rooms r on r.id=i.room_id
     where r.owner_id is not distinct from owner and i.created_at>clock_timestamp()-interval '1 day')>=sdi_private.quota('room_invites') then
  raise exception 'Daily invitation limit reached. Try again tomorrow.' using errcode='P0001';
 end if;
 return new;
end $$;
create trigger enforce_invite_quota before insert on sdi_private.room_invites for each row execute function sdi_private.enforce_invite_quota();
revoke all on function sdi_private.enforce_upload_quota(),sdi_private.enforce_publish_quota(),sdi_private.enforce_invite_quota() from public,anon,authenticated;

-- A member's own usage against each daily quota. Factual counts only.
create function sdi_private.quota_status() returns jsonb language plpgsql security definer set search_path='' as $$
declare me uuid:=auth.uid();
begin
 if me is null or not exists(select 1 from auth.sessions where user_id=me and id::text=auth.jwt()->>'session_id') then
  return jsonb_build_object('error','A current signed-in account is required.'); end if;
 return jsonb_build_object(
  'window','rolling 24 hours',
  'uploads',jsonb_build_object('used',(select count(*) from sdi_private.upload_registrations u where u.creator=me and u.created_at>clock_timestamp()-interval '1 day'),
   'limit',sdi_private.quota('upload_registrations')),
  'upload_bytes',jsonb_build_object('used',(select coalesce(sum(case when (u.metadata->>'size') ~ '^[0-9]{1,13}$' then (u.metadata->>'size')::bigint else 0 end),0)
   from sdi_private.upload_registrations u where u.creator=me and u.created_at>clock_timestamp()-interval '1 day'),'limit',sdi_private.quota('upload_bytes')),
  'publish_requests',jsonb_build_object('used',(select count(*) from sdi_private.publish_jobs j where j.creator=me and j.created_at>clock_timestamp()-interval '1 day'),
   'limit',sdi_private.quota('publish_requests')),
  'room_invites',jsonb_build_object('used',(select count(*) from sdi_private.room_invites i join public.sdi_rooms r on r.id=i.room_id where r.owner_id=me and i.created_at>clock_timestamp()-interval '1 day'),
   'limit',sdi_private.quota('room_invites')));
end $$;
revoke all on function sdi_private.quota_status() from public,anon;
grant execute on function sdi_private.quota_status() to authenticated;
create function public.sdi_quota_status() returns jsonb language sql security invoker set search_path='' as $$select sdi_private.quota_status()$$;
revoke all on function public.sdi_quota_status() from public,anon;
grant execute on function public.sdi_quota_status() to authenticated;
commit;

-- ===== security-credentials.sql (sha256 112fe7c58f4a5dca) =====
-- Unapplied candidate (#238). Install after worker-configuration.sql and before
-- security-audit-integrity.sql. Server-side credential slots for provider keys and
-- the owner's OAuth refresh grant. The secret value lives only in the project's
-- existing secret store (Supabase Vault: encrypted at rest, readable only by the
-- database owner role); this schema keeps the slot's state, revision, a short
-- fingerprint and an audit trail, never the value. Only the service role can store,
-- load, rotate or revoke; administrators read presence and rotation status only.
-- When Vault is not enabled every call reports that plainly and nothing is stored.
-- Clients (iOS, Android, web) never call these functions and never hold these values.
begin;
create table sdi_private.credential_slots (
 slot text primary key check(slot ~ '^[a-z0-9_]{1,40}$'),
 purpose text not null check(length(purpose) between 1 and 200),
 store_ref uuid,
 state text not null default 'unconfigured' check(state in('unconfigured','active','reconnect_required','revoked')),
 revision bigint not null default 0,
 fingerprint text not null default '' check(fingerprint ~ '^([a-f0-9]{12})?$'),
 rotate_after_days integer not null default 90 check(rotate_after_days between 1 and 730),
 rotated_at timestamptz, revoked_at timestamptz, updated_at timestamptz not null default clock_timestamp()
);
create table sdi_private.credential_audit (
 id uuid primary key default gen_random_uuid(), slot text not null, action text not null check(action in('store','rotate','revoke','state','load_refused')),
 revision bigint not null, detail text not null default '' check(length(detail)<=200), created_at timestamptz not null default clock_timestamp()
);
alter table sdi_private.credential_slots enable row level security;
alter table sdi_private.credential_audit enable row level security;
revoke all on sdi_private.credential_slots,sdi_private.credential_audit from public,anon,authenticated;
insert into sdi_private.credential_slots(slot,purpose) values
 ('youtube_owner_grant','Owner channel OAuth client and refresh token (publishing worker)'),
 ('stripe_api','Stripe restricted API key (billing worker)'),
 ('stripe_webhook','Stripe webhook signing secret'),
 ('appstore_server','App Store Server API key'),
 ('push_apns','Apple Push Notification service key'),
 ('push_fcm','Firebase Cloud Messaging service credential'),
 ('mail_provider','Transactional mail provider key'),
 ('ai_provider','App-owned AI provider key (Spatter service)');

create function sdi_private.vault_ready() returns boolean language sql stable security definer set search_path='' as $$
 select to_regnamespace('vault') is not null and to_regclass('vault.decrypted_secrets') is not null
  and to_regprocedure('vault.create_secret(text,text,text,uuid)') is not null
$$;
revoke all on function sdi_private.vault_ready() from public,anon,authenticated;

-- Store or rotate. The previous Vault secret is deleted only after the new one exists,
-- so a failed rotation keeps the last working credential.
create function sdi_private.credential_store(slot text,secret text,detail text default '') returns jsonb
language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare s sdi_private.credential_slots; created uuid; rotating boolean; print text;
begin
 if not sdi_private.vault_ready() then return jsonb_build_object('error','Server secret store is not enabled. Nothing was stored.'); end if;
 select * into s from sdi_private.credential_slots where slot=credential_store.slot for update;
 if not found then return jsonb_build_object('error','Unknown credential slot.'); end if;
 if secret is null or length(secret) not between 16 and 16384 or secret ~ '^\s|\s$' then
  return jsonb_build_object('error','Credential value rejected (length or surrounding whitespace). Nothing was stored.'); end if;
 rotating:=s.store_ref is not null;
 print:=left(encode(extensions.digest(secret,'sha256'),'hex'),12);
 execute 'select vault.create_secret($1,$2,$3)' into created using secret,'sdi_'||s.slot||'_r'||(s.revision+1),'SDI credential slot '||s.slot;
 if rotating then execute 'delete from vault.secrets where id=$1' using s.store_ref; end if;
 update sdi_private.credential_slots set store_ref=created,state='active',revision=s.revision+1,fingerprint=print,
  rotated_at=clock_timestamp(),revoked_at=null,updated_at=clock_timestamp() where slot=s.slot;
 insert into sdi_private.credential_audit(slot,action,revision,detail) values(s.slot,case when rotating then 'rotate' else 'store' end,s.revision+1,left(coalesce(detail,''),200));
 return jsonb_build_object('status',case when rotating then 'rotated' else 'stored' end,'revision',s.revision+1,'fingerprint',print);
end $$;

-- Load for a worker. Missing, revoked or reconnect-required slots return no value.
create function sdi_private.credential_load(slot text) returns jsonb
language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare s sdi_private.credential_slots; value text;
begin
 select * into s from sdi_private.credential_slots where slot=credential_load.slot;
 if not found then return jsonb_build_object('configured',false,'state','unknown'); end if;
 if s.state<>'active' or s.store_ref is null then return jsonb_build_object('configured',false,'state',s.state,'revision',s.revision); end if;
 if not sdi_private.vault_ready() then return jsonb_build_object('configured',false,'state','store_unavailable','revision',s.revision); end if;
 execute 'select decrypted_secret from vault.decrypted_secrets where id=$1' into value using s.store_ref;
 if value is null then
  insert into sdi_private.credential_audit(slot,action,revision,detail) values(s.slot,'load_refused',s.revision,'Secret missing from the store.');
  return jsonb_build_object('configured',false,'state','store_missing','revision',s.revision);
 end if;
 return jsonb_build_object('configured',true,'state','active','revision',s.revision,'secret',value);
end $$;

-- Compare-and-set state from a worker (e.g. the provider answered invalid_grant). A
-- stale revision never overwrites a credential linked after the worker loaded its copy.
create function sdi_private.credential_record_state(slot text,revision bigint,state text) returns boolean
language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
begin
 if credential_record_state.state not in('active','reconnect_required') then return false; end if;
 update sdi_private.credential_slots c set state=credential_record_state.state,updated_at=clock_timestamp()
  where c.slot=credential_record_state.slot and c.revision=credential_record_state.revision and c.store_ref is not null and c.state<>'revoked';
 if not found then return false; end if;
 insert into sdi_private.credential_audit(slot,action,revision,detail) values(credential_record_state.slot,'state',credential_record_state.revision,credential_record_state.state);
 return true;
end $$;

-- Revoke: the stored value is destroyed. Revocation at the provider (Google account
-- permissions, Stripe key roll) is a separate owner step listed in the runbook.
create function sdi_private.credential_revoke(slot text,detail text default '') returns jsonb
language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare s sdi_private.credential_slots;
begin
 select * into s from sdi_private.credential_slots where slot=credential_revoke.slot for update;
 if not found then return jsonb_build_object('error','Unknown credential slot.'); end if;
 if s.store_ref is not null and sdi_private.vault_ready() then execute 'delete from vault.secrets where id=$1' using s.store_ref; end if;
 update sdi_private.credential_slots set store_ref=null,state='revoked',revision=s.revision+1,fingerprint='',revoked_at=clock_timestamp(),updated_at=clock_timestamp() where slot=s.slot;
 insert into sdi_private.credential_audit(slot,action,revision,detail) values(s.slot,'revoke',s.revision+1,left(coalesce(detail,''),200));
 return jsonb_build_object('status','revoked','revision',s.revision+1);
end $$;
revoke all on function sdi_private.credential_store(text,text,text),sdi_private.credential_load(text),
 sdi_private.credential_record_state(text,bigint,text),sdi_private.credential_revoke(text,text) from public,anon,authenticated;
grant execute on function sdi_private.credential_store(text,text,text),sdi_private.credential_load(text),
 sdi_private.credential_record_state(text,bigint,text),sdi_private.credential_revoke(text,text) to service_role;

-- Administrator view: presence, state, fingerprint and rotation due. Never the value.
create function sdi_private.credential_status() returns jsonb language plpgsql security definer set search_path='' as $$
declare denial jsonb; items jsonb;
begin
 denial:=sdi_private.admin_gate('credential_status','overview',false,60);
 if denial is not null then return denial; end if;
 select coalesce(jsonb_agg(jsonb_build_object('slot',c.slot,'purpose',c.purpose,'state',c.state,'revision',c.revision,'fingerprint',c.fingerprint,
   'rotated_at',c.rotated_at,'rotation_due',c.state='active' and c.rotated_at<clock_timestamp()-make_interval(days=>c.rotate_after_days)) order by c.slot),'[]'::jsonb)
  into items from sdi_private.credential_slots c;
 return jsonb_build_object('store_ready',sdi_private.vault_ready(),'slots',items,'note','Presence only. Values live in the server secret store and are never returned here.');
end $$;
revoke all on function sdi_private.credential_status() from public,anon;
grant execute on function sdi_private.credential_status() to authenticated;

create function public.sdi_credential_store(slot text,secret text,detail text default '') returns jsonb language sql security invoker set search_path='' as $$select sdi_private.credential_store(slot,secret,detail)$$;
create function public.sdi_credential_load(slot text) returns jsonb language sql security invoker set search_path='' as $$select sdi_private.credential_load(slot)$$;
create function public.sdi_credential_record_state(slot text,revision bigint,state text) returns boolean language sql security invoker set search_path='' as $$select sdi_private.credential_record_state(slot,revision,state)$$;
create function public.sdi_credential_revoke(slot text,detail text default '') returns jsonb language sql security invoker set search_path='' as $$select sdi_private.credential_revoke(slot,detail)$$;
revoke all on function public.sdi_credential_store(text,text,text),public.sdi_credential_load(text),
 public.sdi_credential_record_state(text,bigint,text),public.sdi_credential_revoke(text,text) from public,anon,authenticated;
grant execute on function public.sdi_credential_store(text,text,text),public.sdi_credential_load(text),
 public.sdi_credential_record_state(text,bigint,text),public.sdi_credential_revoke(text,text) to service_role;
create function public.sdi_credential_status() returns jsonb language sql security invoker set search_path='' as $$select sdi_private.credential_status()$$;
revoke all on function public.sdi_credential_status() from public,anon;
grant execute on function public.sdi_credential_status() to authenticated;
commit;

-- ===== security-retire-communications.sql (sha256 7830814826938977) =====
-- Unapplied candidate (#260). Install after rate-limits.sql. User-to-user messaging,
-- text chat and voice/video calling are retired scope. None of the SQL candidates in
-- this directory create such objects; this file closes any legacy ones a live
-- project may still hold from the earlier app (for example chat rooms, messages or
-- call records) without deleting data blindly: client roles lose every privilege on
-- matching public tables, views and functions, and matching tables leave the
-- realtime publication. Rows are kept for the owner's documented retention decision.
-- Names under sdi_* or containing spatter (the Studio assistant), including Watch
-- Together's approved no-chat playback objects, are never touched. The report lists
-- exactly what was closed; an empty list on a fresh project is the expected result.
begin;
create function sdi_private.legacy_communication_name(name text) returns boolean language sql immutable set search_path='' as $$
 select name !~ '^sdi_' and name !~ 'spatter' and name ~ ('^(chats?|chat_[a-z0-9_]+|[a-z0-9_]+_chats?|messages?|message_[a-z0-9_]+|[a-z0-9_]+_messages?|direct_messages?|dms?|dm_[a-z0-9_]+'
  ||'|conversations?|conversation_[a-z0-9_]+|calls?|call_[a-z0-9_]+|[a-z0-9_]+_calls?|voice_[a-z0-9_]+|video_calls?|video_call_[a-z0-9_]+'
  ||'|livekit_[a-z0-9_]+|[a-z0-9_]+_livekit[a-z0-9_]*|typing_[a-z0-9_]+|watch_part(y|ies)[a-z0-9_]*)$')
$$;
revoke all on function sdi_private.legacy_communication_name(text) from public,anon,authenticated;

create function sdi_private.retire_legacy_communications() returns jsonb language plpgsql security definer set search_path='' as $$
declare item record; closed_relations jsonb:='[]'::jsonb; closed_functions jsonb:='[]'::jsonb; unpublished jsonb:='[]'::jsonb;
begin
 for item in select c.oid,c.relname,c.relkind from pg_class c join pg_namespace n on n.oid=c.relnamespace
  where n.nspname='public' and c.relkind in('r','v','m','p','f') and sdi_private.legacy_communication_name(c.relname) order by c.relname loop
  execute format('revoke all on table public.%I from public,anon,authenticated',item.relname);
  if item.relkind in('r','p') then execute format('alter table public.%I enable row level security',item.relname); end if;
  closed_relations:=closed_relations||to_jsonb(item.relname::text);
  if item.relkind in('r','p') and exists(select 1 from pg_publication_tables p where p.pubname='supabase_realtime' and p.schemaname='public' and p.tablename=item.relname) then
   execute format('alter publication supabase_realtime drop table public.%I',item.relname);
   unpublished:=unpublished||to_jsonb(item.relname::text);
  end if;
 end loop;
 for item in select p.oid,p.proname,pg_catalog.pg_get_function_identity_arguments(p.oid) as args from pg_proc p join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='public' and p.prokind in('f','p') and sdi_private.legacy_communication_name(p.proname) order by p.proname loop
  execute format('revoke all on %s public.%I(%s) from public,anon,authenticated',
   case when (select prokind from pg_proc where oid=item.oid)='p' then 'procedure' else 'function' end,item.proname,item.args);
  closed_functions:=closed_functions||to_jsonb(item.proname||'('||item.args||')');
 end loop;
 return jsonb_build_object('closed_relations',closed_relations,'closed_functions',closed_functions,'removed_from_realtime',unpublished,
  'note','Client access removed; no rows were deleted. Retention or deletion of legacy rows is a separate owner decision.');
end $$;
revoke all on function sdi_private.retire_legacy_communications() from public,anon,authenticated;
grant execute on function sdi_private.retire_legacy_communications() to service_role;

-- Read-only check for the release gate: any client-reachable legacy object left?
create function sdi_private.legacy_communication_exposure() returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object(
  'relations',coalesce((select jsonb_agg(c.relname order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace
   where n.nspname='public' and c.relkind in('r','v','m','p','f') and sdi_private.legacy_communication_name(c.relname)
   and (has_table_privilege('anon',c.oid,'select,insert,update,delete') or has_table_privilege('authenticated',c.oid,'select,insert,update,delete'))),'[]'::jsonb),
  'functions',coalesce((select jsonb_agg(p.proname order by p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace
   where n.nspname='public' and sdi_private.legacy_communication_name(p.proname)
   and (has_function_privilege('anon',p.oid,'execute') or has_function_privilege('authenticated',p.oid,'execute'))),'[]'::jsonb))
$$;
revoke all on function sdi_private.legacy_communication_exposure() from public,anon,authenticated;
grant execute on function sdi_private.legacy_communication_exposure() to service_role;
create function public.sdi_legacy_communication_exposure() returns jsonb language sql security invoker set search_path='' as $$select sdi_private.legacy_communication_exposure()$$;
revoke all on function public.sdi_legacy_communication_exposure() from public,anon,authenticated;
grant execute on function public.sdi_legacy_communication_exposure() to service_role;

do $$ begin perform sdi_private.retire_legacy_communications(); end $$;
commit;

-- ===== security-audit-integrity.sql (sha256 4d08f49397a9fb9a) =====
-- Unapplied candidate (#256). Install after every file that creates an audit table
-- (last in the apply order). Makes each sdi_private.*_audit table append-only for
-- every role that reaches it through the application: UPDATE is refused except when
-- a foreign key's ON DELETE SET NULL clears a member reference, and DELETE or
-- TRUNCATE is refused except inside the account purge (account_deletion_run sets the
-- transaction-local flag sdi.audit_purge). This protects evidence from application
-- paths and mistakes; it does not protect against the database owner, who can drop
-- triggers. audit_integrity_report() lets the restore drill and the owner confirm
-- that every audit table still carries the guard.
begin;
create function sdi_private.audit_append_only() returns trigger language plpgsql set search_path='' as $$
declare before jsonb; after jsonb; k text;
begin
 if tg_op in('DELETE','TRUNCATE') then
  if coalesce(current_setting('sdi.audit_purge',true),'')='on' then
   return case when tg_op='DELETE' then old else null end; end if;
  -- Retention sweeps may delete rows past the 400-day audit window (agent-controls.sql).
  if tg_op='DELETE' and (to_jsonb(old)->>'created_at') is not null
     and (to_jsonb(old)->>'created_at')::timestamptz<clock_timestamp()-interval '400 days' then return old; end if;
  raise exception 'Audit records are append-only (%).',tg_table_name using errcode='42501';
 end if;
 before:=to_jsonb(old); after:=to_jsonb(new);
 for k in select key from jsonb_each(before) loop
  if before->k is distinct from after->k and not (after->k='null'::jsonb and k=any(tg_argv)) then
   raise exception 'Audit records are append-only (%.%).',tg_table_name,k using errcode='42501';
  end if;
 end loop;
 return new;
end $$;
revoke all on function sdi_private.audit_append_only() from public,anon,authenticated;

-- Attach to every audit table present now. Columns whose foreign key clears on
-- delete are the only ones an UPDATE may change, and only to null.
do $$
declare t record; cols text[];
begin
 for t in select c.oid,c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace
  where n.nspname='sdi_private' and c.relkind='r' and c.relname like '%\_audit' order by c.relname loop
  select coalesce(array_agg(distinct a.attname::text),'{}') into cols from pg_constraint k
   join pg_attribute a on a.attrelid=k.conrelid and a.attnum=any(k.conkey)
   where k.conrelid=t.oid and k.contype='f' and k.confdeltype='n';
  execute format('create trigger audit_append_only before update or delete on sdi_private.%I for each row execute function sdi_private.audit_append_only(%s)',
   t.relname,coalesce((select string_agg(quote_literal(c),',') from unnest(cols) c),''));
  execute format('create trigger audit_no_truncate before truncate on sdi_private.%I for each statement execute function sdi_private.audit_append_only()',t.relname);
 end loop;
end $$;

-- Service and owner check: every audit table, whether it is guarded, and its rows.
create function sdi_private.audit_integrity_report() returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('tables',coalesce(jsonb_agg(jsonb_build_object('table',c.relname,
   'guarded',exists(select 1 from pg_trigger g where g.tgrelid=c.oid and g.tgname='audit_append_only' and g.tgenabled<>'D')
    and exists(select 1 from pg_trigger g where g.tgrelid=c.oid and g.tgname='audit_no_truncate' and g.tgenabled<>'D'),
   'rls',c.relrowsecurity) order by c.relname),'[]'::jsonb),
  'unguarded',coalesce(sum(case when exists(select 1 from pg_trigger g where g.tgrelid=c.oid and g.tgname='audit_append_only' and g.tgenabled<>'D') then 0 else 1 end),0))
 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='sdi_private' and c.relkind='r' and c.relname like '%\_audit'
$$;
revoke all on function sdi_private.audit_integrity_report() from public,anon,authenticated;
grant execute on function sdi_private.audit_integrity_report() to service_role;
create function public.sdi_audit_integrity_report() returns jsonb language sql security invoker set search_path='' as $$select sdi_private.audit_integrity_report()$$;
revoke all on function public.sdi_audit_integrity_report() from public,anon,authenticated;
grant execute on function public.sdi_audit_integrity_report() to service_role;
commit;
